    #[test]
    fn mapped_prepared_kernel_extra_permutation_tracks_generated_collapsed_hyperlink() {
        let xml = format!(
            r#"<w:p xmlns:w="{}" keep="root"><w:smartTag><w:r><w:t>kept1</w:t></w:r></w:smartTag><w:r><w:t>AA</w:t></w:r><w:hyperlink w:anchor="target"><w:r><w:t>NEEDLE</w:t></w:r><x:kept xmlns:x="urn:producer"/></w:hyperlink><w:customXml><w:r><w:t>kept2</w:t></w:r></w:customXml></w:p>"#,
            crate::namespace::W_NS
        );
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation
            .source(0..xml.len(), &std::collections::BTreeMap::new())
            .unwrap();
        let mut maps = Vec::new();
        let mut paragraph = operation
            .parse_source_paragraph(&source, Some(&mut maps), None, None)
            .unwrap();
        let texts = crate::placeholder::replaceable_texts(&paragraph);
        let stretch = texts.iter().position(|text| text == "AANEEDLE").unwrap();
        crate::placeholder::replace_prepared_occurrences_borrowed_in(
            &mut paragraph,
            &[(stretch, 0..8, "", None)],
            Some(&mut maps),
            Some(&mut operation.field_work),
            None,
        )
        .unwrap();
        assert_eq!(maps.len(), paragraph.extra_xml.len());
        let mut retained = 0;
        let mut generated = 0;
        for ((_, raw), map) in paragraph.extra_xml.iter().zip(&maps) {
            if raw.starts_with(b"<w:smartTag") || raw.starts_with(b"<w:customXml") {
                let start = if raw.starts_with(b"<w:smartTag") {
                    xml.find("<w:smartTag").unwrap()
                } else {
                    xml.find("<w:customXml").unwrap()
                };
                assert_eq!(
                    map.as_ref().unwrap().original_pieces(),
                    [(0, start, start + raw.len())]
                );
                retained += 1;
            } else if raw.starts_with(b"<w:hyperlink") {
                assert!(
                    map.is_none(),
                    "collapsed source is Generated, not an old extra map"
                );
                generated += 1;
            }
        }
        assert_eq!(retained, 2);
        assert_eq!(generated, 1);
    }

