    #[test]
    fn original_capture_expanding_wrappers_share_the_original_input_allowance() {
        let uri = format!("urn:{}", "u".repeat(400));
        let run = "<w:r><x:opaque/></w:r>";
        for wrappers in [
            format!(
                "<w:smartTag><w:smartTag>{}</w:smartTag></w:smartTag>",
                run.repeat(200)
            ),
            format!(
                "<w:smartTag>{}</w:smartTag><w:customXml>{}</w:customXml>",
                run.repeat(100),
                run.repeat(100)
            ),
        ] {
            let source = capture_document(
                &format!("xmlns:x=\"{uri}\""),
                &format!("<w:r><w:t>before</w:t></w:r>{wrappers}"),
            );
            let error = super::admit_word_xml(source.as_bytes(), &[], None)
                .expect_err("expanded wrapper runs must not escape the shared capture allowance");
            assert!(
                error
                    .to_string()
                    .contains("original source capture exceeds admitted source work"),
                "{error}"
            );
        }
        let smaller = capture_document(
            &format!("xmlns:x=\"{uri}\""),
            &format!("<w:smartTag>{}</w:smartTag>", run.repeat(20)),
        );
        super::admit_word_xml(smaller.as_bytes(), &[], None).unwrap();
        for opaque in ["x:opaque", "w:future"] {
            let source = capture_document(
                &format!("xmlns:x=\"{uri}\""),
                &format!(
                    "<{opaque}><w:p><w:smartTag>{}</w:smartTag></w:p></{opaque}>",
                    run.repeat(200)
                ),
            );
            super::admit_word_xml(source.as_bytes(), &[], None)
                .expect("qualified descendants of opaque paragraph children are not run owners");
        }
    }

    #[test]
    fn original_capture_keeps_supported_raw_control_fallbacks_over_the_typed_budget() {
        let uri = format!("urn:{}", "u".repeat(400));
        let tail = "<w:r><x:opaque/></w:r>".repeat(200);
        let paragraph = format!("<w:p><w:r><w:rPr><w:sz w:val=\"q\"/></w:rPr></w:r>{tail}</w:p>");
        let control = format!(
            "<w:sdt xmlns:w=\"{}\" xmlns:x=\"{uri}\"><w:sdtContent>{paragraph}</w:sdtContent></w:sdt>",
            crate::namespace::W_NS
        );
        assert!(
            crate::content_control::CT_Sdt::from_body_raw(control.as_bytes(), &[]).is_none(),
            "the existing constructor actually chooses the raw fallback"
        );
        let source = format!(
            "<w:document xmlns:w=\"{}\" xmlns:x=\"{uri}\"><w:body><w:sdt><w:sdtContent>{paragraph}</w:sdtContent></w:sdt></w:body></w:document>",
            crate::namespace::W_NS
        );
        super::admit_word_xml(source.as_bytes(), &[], None).expect(
            "a failed typed control parse retains raw XML without the discarded run records",
        );
        let parsed = super::CT_Document::from_xml(source.as_bytes()).unwrap();
        assert!(matches!(
            parsed.body.content.as_slice(),
            [super::BodyContent::RawXml(_)]
        ));
        let saved = parsed.to_xml().unwrap();
        assert!(
            saved
                .windows(paragraph.len())
                .any(|bytes| bytes == paragraph.as_bytes())
        );
    }

    #[test]
    fn original_capture_certifies_early_and_late_measurement_failures_without_runs() {
        let uri = format!("urn:{}", "u".repeat(400));
        for local in ["sz", "szCs", "spacing", "position", "kern", "w"] {
            for late in [false, true] {
                let tail = "<w:r><x:opaque/></w:r>".repeat(200);
                let bad = format!("<w:r><w:rPr><w:{local} w:val=\"q\"/></w:rPr></w:r>");
                let paragraph = if late {
                    format!("<w:p>{tail}{bad}</w:p>")
                } else {
                    format!("<w:p>{bad}{tail}</w:p>")
                };
                let source = format!(
                    "<w:document xmlns:w=\"{}\" xmlns:x=\"{uri}\"><w:body><w:sdt><w:sdtContent>{paragraph}</w:sdtContent></w:sdt></w:body></w:document>",
                    crate::namespace::W_NS
                );
                crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
                let parsed = super::CT_Document::from_xml(source.as_bytes()).unwrap();
                assert!(
                    matches!(
                        parsed.body.content.as_slice(),
                        [super::BodyContent::RawXml(_)]
                    ),
                    "{local}, late={late}"
                );
                assert_eq!(
                    crate::text::PARSED_RUN_CONSTRUCTIONS.get(),
                    0,
                    "discarded runs must not be constructed: {local}, late={late}"
                );
                assert!(
                    parsed
                        .to_xml()
                        .unwrap()
                        .windows(paragraph.len())
                        .any(|bytes| bytes == paragraph.as_bytes())
                );
                let valid = source.replace("w:val=\"q\"", "w:val=\"2\"");
                assert!(
                    super::admit_word_xml(valid.as_bytes(), &[], None)
                        .unwrap_err()
                        .to_string()
                        .contains("original source capture exceeds admitted source work"),
                    "a valid typed control must still be charged: {local}"
                );
            }
        }
    }

    #[test]
    fn original_capture_revision_header_failure_discards_descendant_owner_actions() {
        let word = crate::namespace::W_NS;
        let nested = format!(
            "{}<w:r><w:t>retained</w:t></w:r>{}",
            "<w:sdt><w:sdtContent>".repeat(257),
            "</w:sdtContent></w:sdt>".repeat(257)
        );
        let uri = format!("urn:{}", "u".repeat(400));
        let wide = format!(
            "<w:sdt><w:sdtContent>{}</w:sdtContent></w:sdt>",
            "<w:r><x:opaque/></w:r>".repeat(200)
        );
        for nested in [nested, wide] {
            for header in ["w:id=\"q\" w:author=\"A\"", "w:author=\"A\""] {
                let raw = format!(
                    "<w:ins xmlns:w=\"{word}\" xmlns:x=\"{uri}\" {header}>{nested}</w:ins>"
                );
                assert!(
                    crate::revision::CT_Revision::from_raw_with_input(
                        raw.as_bytes().to_vec(),
                        &[],
                        false,
                        None
                    )
                    .unwrap()
                    .is_none(),
                    "actual revision header fails before children"
                );
                let source = format!(
                    "<w:document xmlns:w=\"{word}\"><w:body><w:p>{raw}</w:p></w:body></w:document>"
                );
                super::admit_word_xml(source.as_bytes(), &[], None)
                    .expect("a rejected revision does not construct nested controls");
                crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
                let parsed = super::CT_Document::from_xml(source.as_bytes()).unwrap();
                assert_eq!(
                    crate::text::PARSED_RUN_CONSTRUCTIONS.get(),
                    0,
                    "no discarded nested run construction"
                );
                let super::BodyContent::Paragraph(paragraph) = &parsed.body.content[0] else {
                    panic!("paragraph")
                };
                assert!(paragraph.revisions.is_empty());
                assert!(
                    parsed
                        .to_xml()
                        .unwrap()
                        .windows(raw.len())
                        .any(|bytes| bytes == raw.as_bytes())
                );
            }
        }
    }

    #[test]
    fn c1_revision_physical_simple_source_does_not_construct_its_children() {
        for instruction in [r#" w:instr="CUSTOM""#, r#" w:instr="""#, ""] {
            let field = format!(
                r#"<w:fldSimple{instruction}><w:r><w:commentReference w:id="bad"/></w:r></w:fldSimple>"#
            );
            let raw = format!(
                r#"<w:ins w:id="1" w:author="A">{field}<w:r><w:t>tail</w:t></w:r></w:ins>"#
            );
            let revision =
                crate::revision::CT_Revision::from_raw(raw.as_bytes().to_vec(), &["w".into()])
                    .unwrap();
            let crate::revision::RevisionContent::Runs(runs) = revision.content() else {
                panic!("physical tail")
            };
            assert_eq!(
                runs.iter().map(crate::text::CT_R::text).collect::<String>(),
                "tail"
            );
            assert!(
                revision
                    .content_paragraph()
                    .unwrap()
                    .extra_xml
                    .iter()
                    .any(|(_, bytes)| bytes == field.as_bytes())
            );
            let source = format!(
                r#"<w:document xmlns:w="{}"><w:body><w:p>{raw}</w:p></w:body></w:document>"#,
                crate::namespace::W_NS
            );
            let admitted = super::admit_word_source(source.as_bytes(), &[], None, None).unwrap();
            assert!(
                admitted.constructors.raw_subtrees.is_empty(),
                "a physical simple source has no invoked Field/child constructor: {instruction}"
            );
        }
    }

    #[test]
    fn c1_revision_terminal_failures_preserve_raw_source_admission() {
        let prefixes = ["w".to_owned()];
        let deep = format!(
            "{}<w:r><w:t>unused</w:t></w:r>{}",
            "<w:sdt><w:sdtContent>".repeat(257),
            "</w:sdtContent></w:sdt>".repeat(257)
        );
        let bad_run = r#"<w:r><w:commentReference w:id="not-a-number"/></w:r>"#;
        assert!(crate::text::parse_run_raw(bad_run.as_bytes(), &prefixes, None).is_err());
        for kind in ["ins", "moveTo", "del", "moveFrom"] {
            let raw = format!(r#"<w:{kind} w:id="1" w:author="A">{bad_run}{deep}</w:{kind}>"#);
            assert!(
                crate::revision::CT_Revision::from_raw(raw.as_bytes().to_vec(), &prefixes)
                    .is_none()
            );
            let source = format!(
                r#"<w:document xmlns:w="{}"><w:body><w:p>{raw}</w:p></w:body></w:document>"#,
                crate::namespace::W_NS
            );
            super::admit_word_source(source.as_bytes(), &[], None, None).unwrap();
            let parsed = super::CT_Document::from_xml(source.as_bytes()).unwrap();
            assert!(parsed.revisions().is_empty());
            assert!(
                parsed
                    .to_xml()
                    .unwrap()
                    .windows(raw.len())
                    .any(|piece| piece == raw.as_bytes())
            );
        }
        let nested = format!(
            r#"<w:ins w:id="1" w:author="A"><w:del w:id="2" w:author="B">{bad_run}</w:del>{deep}</w:ins>"#
        );
        let source = format!(
            r#"<w:document xmlns:w="{}"><w:body><w:p>{nested}</w:p></w:body></w:document>"#,
            crate::namespace::W_NS
        );
        assert!(
            super::admit_word_source(source.as_bytes(), &[], None, None).is_err(),
            "a swallowed nested error must not hide the reached typed outer sibling"
        );
    }

    #[test]
    fn c1_revision_scoped_fallback_keeps_ordinary_error_out_of_resource_receipt() {
        for (prefix, scope) in [
            ("w", format!(r#"xmlns:w="{}""#, crate::namespace::W_NS)),
            (
                "q",
                format!(
                    r#"xmlns:q="{}" xmlns:w="urn:foreign""#,
                    crate::namespace::W_NS
                ),
            ),
        ] {
            let deep = format!(
                "{}<{prefix}:r/>{}",
                format!("<{prefix}:sdt><{prefix}:sdtContent>").repeat(257),
                format!("</{prefix}:sdtContent></{prefix}:sdt>").repeat(257)
            );
            let raw = format!(
                r#"<{prefix}:ins {prefix}:id="1"><{prefix}:r><{prefix}:commentReference {prefix}:id="bad"/></{prefix}:r>{deep}</{prefix}:ins>"#
            );
            let paragraph = format!("<{prefix}:p {scope}>{raw}</{prefix}:p>");
            let mut operation = super::ScopedWordOperation::new(paragraph.as_bytes());
            crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
            let parsed = operation
                .paragraph(0..paragraph.len(), &std::collections::BTreeMap::new())
                .unwrap();
            assert!(parsed.revisions.is_empty());
            assert_eq!(crate::text::PARSED_RUN_CONSTRUCTIONS.get(), 1);
            assert!(
                operation
                    .field_origins
                    .lock()
                    .unwrap()
                    .source_resource_failure()
                    .is_none()
            );
            assert!(!operation.field_work.resource_refused());
            assert!(
                parsed
                    .extra_xml
                    .iter()
                    .any(|(_, bytes)| bytes == raw.as_bytes())
            );
        }
    }

