    #[test]
    fn original_capture_revision_headers_preserve_author_scope_and_first_qualified_values() {
        let word = crate::namespace::W_NS;
        for (header, typed) in [
            ("w:id=\"1\"", true),
            ("w:id=\"1\" w:author=\"A\"", true),
            ("a:id=\"q\" xmlns:a=\"urn:foreign\" w:id=\"1\"", true),
            ("w:id=\"&#49;\"", true),
            ("a:id=\"1\" w:id=\"q\"", true),
            ("w:id=\"q\" a:id=\"1\"", false),
            ("id=\"q\" w:id=\"1\"", true),
            ("w:author=\"A\"", false),
        ] {
            for (before, after, require_author) in [
                ("<w:p>", "</w:p>", false),
                ("<w:p><w:hyperlink>", "</w:hyperlink></w:p>", true),
                ("<w:p><w:r><w:rPr>", "</w:rPr></w:r></w:p>", true),
                ("<w:p><w:pPr><w:numPr>", "</w:numPr></w:pPr></w:p>", true),
                ("<w:tbl><w:tr><w:trPr>", "</w:trPr></w:tr></w:tbl>", true),
                ("<w:sdt><w:sdtContent>", "</w:sdtContent></w:sdt>", true),
            ] {
                for empty in [false, true] {
                    let raw = if empty {
                        format!("<w:ins {header}/>")
                    } else {
                        format!("<w:ins {header}><w:r><w:t>kept</w:t></w:r></w:ins>")
                    };
                    let scope = vec!["w".to_owned(), "a".to_owned()];
                    let actual = if require_author {
                        crate::revision::CT_Revision::from_raw(raw.as_bytes().to_vec(), &scope)
                    } else {
                        crate::revision::CT_Revision::from_raw_with_input(
                            raw.as_bytes().to_vec(),
                            &scope,
                            false,
                            None,
                        )
                        .unwrap()
                    };
                    let expected = typed && (!require_author || header.contains("w:author="));
                    assert_eq!(
                        actual.is_some(),
                        expected,
                        "constructor: {header}, {before}, empty={empty}"
                    );
                    let source = format!(
                        "<w:document xmlns:w=\"{word}\" xmlns:a=\"{word}\"><w:body>{before}{raw}{after}</w:body></w:document>"
                    );
                    let facts =
                        super::admit_word_source(source.as_bytes(), &[], None, None).unwrap();
                    let ranges = &facts.constructors.raw_subtrees;
                    assert_eq!(
                        ranges.len(),
                        usize::from(!expected),
                        "source action: {header}, {before}, empty={empty}"
                    );
                    if let Some(range) = ranges.first() {
                        assert_eq!(&source.as_bytes()[range.span.clone()], raw.as_bytes());
                    }
                }
            }
        }
        // Swallowed revision failure cannot retire the enclosing typed control.
        let uri = format!("urn:{}", "u".repeat(400));
        let tail = "<w:r><x:opaque/></w:r>".repeat(200);
        let source = format!(
            "<w:document xmlns:w=\"{word}\" xmlns:x=\"{uri}\"><w:body><w:sdt><w:sdtContent><w:p><w:ins w:id=\"q\"><w:r/></w:ins>{tail}</w:p></w:sdtContent></w:sdt></w:body></w:document>"
        );
        assert!(
            super::admit_word_xml(source.as_bytes(), &[], None)
                .unwrap_err()
                .to_string()
                .contains("original source capture exceeds admitted source work")
        );
    }

    #[test]
    fn original_capture_negative_certificates_stop_at_fallible_children_and_opaque_slots() {
        use crate::content_control::SdtOwner;
        let word = crate::namespace::W_NS;
        let bad = "<w:r><w:rPr><w:sz w:val=\"q\"/></w:rPr></w:r>";
        let uri = format!("urn:{}", "u".repeat(400));
        // The actual revision constructor swallows this malformed result into
        // raw revision source. It must not make the outer control raw.
        let revision = format!("<w:p><w:ins w:id=\"1\" w:author=\"A\">{bad}</w:ins></w:p>");
        let nested = format!("<w:sdt><w:sdtContent><w:p>{bad}</w:p></w:sdtContent></w:sdt>");
        for child in [revision, nested] {
            let tail = "<w:r><x:opaque/></w:r>".repeat(200);
            let raw = format!(
                "<w:sdt xmlns:w=\"{word}\" xmlns:x=\"{uri}\"><w:sdtContent>{child}<w:p>{tail}</w:p></w:sdtContent></w:sdt>"
            );
            assert!(
                crate::content_control::CT_Sdt::from_body_raw(raw.as_bytes(), &[]).is_some(),
                "the actual outer constructor stays typed"
            );
            assert!(
                !super::control_has_property_measurement_failure(
                    raw.as_bytes(),
                    &[],
                    SdtOwner::Body
                )
                .unwrap()
            );
            let source = format!(
                "<w:document xmlns:w=\"{word}\" xmlns:x=\"{uri}\"><w:body>{raw}</w:body></w:document>"
            );
            assert!(
                super::admit_word_xml(source.as_bytes(), &[], None)
                    .unwrap_err()
                    .to_string()
                    .contains("original source capture exceeds admitted source work")
            );
        }
        let tail = "<w:r><x:opaque/></w:r>".repeat(200);
        for content in [
            format!(
                "<w:sdtContent><w:p>{tail}</w:p></w:sdtContent><w:sdtContent><w:p>{bad}</w:p></w:sdtContent>"
            ),
            format!(
                "<w:sdtContent><w:p><x:opaque>{bad}</x:opaque><w:r><w:rPr><w:sz w:val=\"q\"></w:sz></w:rPr></w:r>{tail}</w:p></w:sdtContent>"
            ),
            format!(
                "<w:sdtContent><w:p><w:r><w:rPr><w:sz xmlns:w=\"urn:foreign\" w:val=\"q\"/><w:sz val=\"q\"/></w:rPr></w:r>{tail}</w:p></w:sdtContent>"
            ),
            format!(
                "<w:sdtContent><w:p><w:pPr/><w:pPr><x:opaque>{bad}</x:opaque></w:pPr><w:r><w:rPr/><w:rPr><w:sz w:val=\"10\"/><w:sz w:val=\"q\"></w:sz></w:rPr></w:r>{tail}</w:p></w:sdtContent>"
            ),
        ] {
            let raw = format!("<w:sdt xmlns:w=\"{word}\" xmlns:x=\"{uri}\">{content}</w:sdt>");
            assert!(
                !super::control_has_property_measurement_failure(
                    raw.as_bytes(),
                    &[],
                    SdtOwner::Body
                )
                .unwrap()
            );
            assert!(crate::content_control::CT_Sdt::from_body_raw(raw.as_bytes(), &[]).is_some());
            let source = format!(
                "<w:document xmlns:w=\"{word}\" xmlns:x=\"{uri}\"><w:body>{raw}</w:body></w:document>"
            );
            assert!(
                super::admit_word_xml(source.as_bytes(), &[], None)
                    .unwrap_err()
                    .to_string()
                    .contains("original source capture exceeds admitted source work"),
                "ignored or opaque bad-looking properties must not exempt the outer retained runs"
            );
        }
        let alias = format!(
            "<q:sdt xmlns:q=\"{word}\" xmlns:w=\"urn:foreign\"><q:sdtContent><q:p><q:r><q:rPr><q:spacing q:val=\"q\"/></q:rPr></q:r></q:p></q:sdtContent></q:sdt>"
        );
        assert!(
            super::control_has_property_measurement_failure(alias.as_bytes(), &[], SdtOwner::Body)
                .unwrap()
        );
        // A body-only paragraph under an inline control is retained raw.
        let raw = format!(
            "<w:sdt xmlns:w=\"{word}\"><w:sdtContent><w:p>{bad}</w:p></w:sdtContent></w:sdt>"
        );
        assert!(
            !super::control_has_property_measurement_failure(raw.as_bytes(), &[], SdtOwner::Inline)
                .unwrap()
        );
        assert!(
            crate::content_control::CT_Sdt::from_raw_with_context(
                raw.as_bytes(),
                &[],
                crate::content_control::SdtOwner::Inline,
                None
            )
            .is_some()
        );
    }

    #[test]
    fn original_capture_control_scan_work_is_counted_and_existing_depth_guard_is_retained() {
        use quick_xml::{Reader, events::Event};
        let document = |depth| {
            let mut body = "<w:p><w:r><w:t>kept</w:t></w:r></w:p>".to_owned();
            for _ in 0..depth {
                body = format!("<w:sdt><w:sdtContent>{body}</w:sdtContent></w:sdt>");
            }
            format!(
                "<w:document xmlns:w=\"{}\"><w:body>{body}</w:body></w:document>",
                crate::namespace::W_NS
            )
        };
        for depth in [1, 8, 32] {
            let source = document(depth);
            let mut reader = Reader::from_reader(source.as_bytes());
            let mut physical_events = 0usize;
            loop {
                physical_events += 1;
                if matches!(reader.read_event().unwrap(), Event::Eof) {
                    break;
                }
            }
            super::CONSTRUCTOR_QUALIFICATION_EVENTS.set(0);
            super::CT_Document::from_xml(source.as_bytes()).unwrap();
            let visits = super::CONSTRUCTOR_QUALIFICATION_EVENTS.get();
            assert_eq!(
                visits, physical_events,
                "one original qualifier scan at depth {depth}"
            );
            println!(
                "control-depth={depth} qualifier-events={visits} physical-events={physical_events}"
            );
        }
        crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
        assert!(super::CT_Document::from_xml(document(257).as_bytes()).is_err());
        assert_eq!(crate::text::PARSED_RUN_CONSTRUCTIONS.get(), 0);
    }

    #[test]
    fn original_capture_occurrence_context_skips_opaque_and_first_only_slots() {
        let good = "<q:sdt><q:sdtContent><q:r><q:t>inside</q:t></q:r></q:sdtContent></q:sdt>";
        let bad = "<w:sdt><w:sdtContent><w:p><w:r><w:rPr><w:sz w:val=\"bad\"/></w:rPr></w:r></w:p></w:sdtContent></w:sdt>";
        let outer = format!(
            "<w:sdt><w:sdtPr></w:sdtPr><w:sdtPr><w:id w:val=\"bad\"/></w:sdtPr><w:sdtContent><q:p>{good}<q:sdt xmlns:q=\"urn:foreign\"><q:sdtContent>{bad}</q:sdtContent></q:sdt></q:p><x:opaque>{bad}</x:opaque></w:sdtContent><w:sdtContent>{bad}</w:sdtContent></w:sdt>"
        );
        let tail = "<w:sdt><w:sdtContent><w:p/></w:sdtContent></w:sdt>";
        let source = format!(
            "<w:document xmlns:w=\"{}\" xmlns:x=\"urn:opaque\"><w:body xmlns:q=\"{}\">{outer}{tail}</w:body></w:document>",
            crate::namespace::W_NS,
            crate::namespace::W_NS
        );
        super::CONTROL_SOURCE_OCCURRENCES_TAKEN.with_borrow_mut(Vec::clear);
        super::CT_Document::from_xml(source.as_bytes()).unwrap();
        let expected = [
            source.find(&outer).unwrap(),
            source.find(good).unwrap(),
            source.find(tail).unwrap(),
        ];
        super::CONTROL_SOURCE_OCCURRENCES_TAKEN
            .with_borrow(|taken| assert_eq!(taken.as_slice(), expected));
    }

    #[test]
    fn original_capture_public_primary_readers_consume_their_prepared_occurrences() {
        let paragraph = "<w:p><w:r><w:t>kept</w:t></w:r></w:p>";
        for (owner, payload) in [
            ("body", paragraph.to_owned()),
            ("p", "<w:r><w:t>kept</w:t></w:r>".to_owned()),
            ("tbl", format!("<w:tr><w:tc>{paragraph}</w:tc></w:tr>")),
            ("tr", format!("<w:tc>{paragraph}</w:tc>")),
            ("tc", paragraph.to_owned()),
        ] {
            let control = format!("<w:sdt><w:sdtContent>{payload}</w:sdtContent></w:sdt>");
            let source = format!(
                "<w:{owner} xmlns:w=\"{}\">{control}{control}</w:{owner}>",
                crate::namespace::W_NS
            );
            let mut reader = quick_xml::Reader::from_reader(source.as_bytes());
            reader.read_event().unwrap();
            super::CONTROL_SOURCE_OCCURRENCES_TAKEN.with_borrow_mut(Vec::clear);
            match owner {
                "body" => {
                    super::CT_Body::from_xml(&mut reader).unwrap();
                }
                "p" => {
                    crate::text::CT_P::from_xml(&mut reader).unwrap();
                }
                "tbl" => {
                    crate::table::CT_Tbl::from_xml(&mut reader).unwrap();
                }
                "tr" => {
                    crate::table::CT_Row::from_xml(&mut reader).unwrap();
                }
                "tc" => {
                    crate::table::CT_Tc::from_xml(&mut reader).unwrap();
                }
                _ => unreachable!(),
            }
            super::CONTROL_SOURCE_OCCURRENCES_TAKEN
                .with_borrow(|taken| assert_eq!(taken.len(), 2, "{owner}"));
        }
    }

    #[test]
    fn original_capture_encoded_only_inherited_alias_keeps_projected_context_unknown() {
        let prefixes = vec!["w".to_owned(), format!("\0q\0{}", crate::namespace::W_NS)];
        let source = "<w:body><w:sdt><w:sdtContent><w:p><q:sdt><q:sdtContent><q:r><q:rPr><q:sz q:val=\"bad\"/></q:rPr></q:r></q:sdtContent></q:sdt></w:p></w:sdtContent></w:sdt></w:body>";
        let admitted = super::admit_word_source(source.as_bytes(), &prefixes, None, None).unwrap();
        assert!(!admitted.projected_aliases);
        let mut controls = admitted.controls();
        let bindings = crate::numbering::namespace_bindings(&prefixes);
        let mut reader = quick_xml::Reader::from_reader(source.as_bytes());
        reader.read_event().unwrap();
        let parsed = super::CT_Body::from_xml_with_prefixes_and_owner_bindings_until(
            &mut reader,
            &prefixes,
            &bindings,
            b"body",
            Some(&mut controls),
        )
        .unwrap();
        assert!(matches!(
            parsed.content.as_slice(),
            [super::BodyContent::ContentControl(_)]
        ));
    }

    #[test]
    fn original_capture_sibling_controls_share_one_original_qualifier_pass() {
        for siblings in [1, 8, 32] {
            let leaf =
                "<w:sdt><w:sdtContent><w:p><w:r><w:t>kept</w:t></w:r></w:p></w:sdtContent></w:sdt>";
            let source = format!(
                "<w:document xmlns:w=\"{}\"><w:body>{}</w:body></w:document>",
                crate::namespace::W_NS,
                leaf.repeat(siblings)
            );
            let mut physical = quick_xml::Reader::from_reader(source.as_bytes());
            let mut events = 0;
            loop {
                events += 1;
                if matches!(
                    physical.read_event().unwrap(),
                    quick_xml::events::Event::Eof
                ) {
                    break;
                }
            }
            super::CONSTRUCTOR_QUALIFICATION_EVENTS.set(0);
            super::CONTROL_SOURCE_OCCURRENCES_TAKEN.with_borrow_mut(Vec::clear);
            let parsed = super::CT_Document::from_xml(source.as_bytes()).unwrap();
            assert_eq!(parsed.body.content.len(), siblings);
            assert_eq!(super::CONSTRUCTOR_QUALIFICATION_EVENTS.get(), events);
            super::CONTROL_SOURCE_OCCURRENCES_TAKEN
                .with_borrow(|taken| assert_eq!(taken.len(), siblings));
        }
    }

