    #[test]
    fn original_capture_control_occurrences_reserve_raw_subtrees_before_siblings() {
        let failed = "<w:p><w:r><w:t>discarded</w:t></w:r><w:r><w:rPr><w:sz w:val=\"bad\"/></w:rPr></w:r></w:p>";
        let nested = "<w:sdt><w:sdtContent><w:p/></w:sdtContent></w:sdt>";
        let raw_parent = format!("<w:sdt><w:sdtContent>{nested}{failed}</w:sdtContent></w:sdt>");
        let raw_sibling = format!("<w:sdt><w:sdtContent>{failed}</w:sdtContent></w:sdt>");
        let typed_sibling =
            "<w:sdt><w:sdtContent><w:p><w:r><w:t>kept</w:t></w:r></w:p></w:sdtContent></w:sdt>";
        let source = format!(
            "<w:document xmlns:w=\"{}\"><w:body>{raw_parent}{raw_sibling}{typed_sibling}{typed_sibling}</w:body></w:document>",
            crate::namespace::W_NS
        );
        let first = source.find(&raw_parent).unwrap();
        let second = first + raw_parent.len();
        let third = second + raw_sibling.len();
        super::CONTROL_SOURCE_OCCURRENCES_TAKEN.with_borrow_mut(Vec::clear);
        crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
        let parsed = super::CT_Document::from_xml(source.as_bytes()).unwrap();
        assert!(matches!(
            parsed.body.content.as_slice(),
            [
                super::BodyContent::RawXml(_),
                super::BodyContent::RawXml(_),
                super::BodyContent::ContentControl(_),
                super::BodyContent::ContentControl(_)
            ]
        ));
        assert_eq!(crate::text::PARSED_RUN_CONSTRUCTIONS.get(), 2);
        super::CONTROL_SOURCE_OCCURRENCES_TAKEN.with_borrow(|taken| {
            assert_eq!(
                taken.as_slice(),
                [first, second, third, third + typed_sibling.len()]
            )
        });
    }

