    #[test]
    fn original_capture_compound_dispatch_retains_typed_owners() {
        let cases = [
            (
                "paired-page-size",
                "",
                "<w:p><w:pPr><w:sectPr><w:pgSz w:w=\"bad\"></w:pgSz></w:sectPr></w:pPr></w:p>",
            ),
            (
                "paired-table-width",
                "",
                "<w:tbl><w:tblPr><w:tblW w:w=\"bad\"></w:tblW></w:tblPr></w:tbl>",
            ),
            (
                "paired-row-height",
                "",
                "<w:tbl><w:tr><w:trPr><w:trHeight w:val=\"bad\"></w:trHeight></w:trPr></w:tr></w:tbl>",
            ),
            (
                "ignored-control-properties",
                "<w:sdtPr></w:sdtPr><w:sdtPr><w:id w:val=\"bad\"/></w:sdtPr>",
                "<w:p/>",
            ),
            (
                "opaque-table-child",
                "",
                "<w:tbl><w:tblPr><w:opaque><w:tblW w:w=\"bad\"/></w:opaque></w:tblPr></w:tbl>",
            ),
            (
                "retained-page-number",
                "",
                "<w:p><w:pPr><w:sectPr><w:pgNumType w:start=\"bad\"/></w:sectPr></w:pPr></w:p>",
            ),
            (
                "signed-compound",
                "<w:sdtPr><w:id w:val=\"-2147483648\"/></w:sdtPr>",
                "<w:p><w:r><w:rPr><w:fitText w:val=\"-2147483648\" w:id=\"-2147483648\"/><w:eastAsianLayout w:id=\"-2147483648\"/></w:rPr></w:r></w:p>",
            ),
        ];
        let uri = format!("urn:{}", "u".repeat(400));
        for (name, properties, children) in cases {
            let root = format!(
                "<w:sdt xmlns:w=\"{}\" xmlns:x=\"{uri}\">{properties}<w:sdtContent>{children}</w:sdtContent></w:sdt>",
                crate::namespace::W_NS
            );
            assert!(
                crate::content_control::CT_Sdt::from_body_raw(root.as_bytes(), &[]).is_some(),
                "actual constructor remains typed: {name}"
            );
            let tail = "<w:r><x:opaque/></w:r>".repeat(200);
            let source = root.replace(
                "</w:sdtContent>",
                &format!("<w:p>{tail}</w:p></w:sdtContent>"),
            );
            assert!(
                super::admit_word_xml(source.as_bytes(), &[], None)
                    .unwrap_err()
                    .to_string()
                    .contains("original source capture exceeds admitted source work"),
                "actual typed owners must retain charges: {name}"
            );
        }
    }

    #[test]
    fn original_capture_compound_property_constructor_matrix() {
        let uri = format!("urn:{}", "u".repeat(400));
        let cases = [
            (
                "run-border",
                "",
                "<w:p><w:r><w:rPr><w:bdr w:sz=\"!invalid!\"/></w:rPr></w:r></w:p>",
                "2",
            ),
            (
                "paragraph-border",
                "",
                "<w:p><w:pPr><w:pBdr><w:top w:space=\"!invalid!\"/></w:pBdr></w:pPr></w:p>",
                "2",
            ),
            (
                "tab",
                "",
                "<w:p><w:pPr><w:tabs><w:tab w:pos=\"!invalid!\"/></w:tabs></w:pPr></w:p>",
                "2",
            ),
            (
                "page-size",
                "",
                "<w:p><w:pPr><w:sectPr><w:pgSz w:w=\"!invalid!\"/></w:sectPr></w:pPr></w:p>",
                "2",
            ),
            (
                "page-margin",
                "",
                "<w:p><w:pPr><w:sectPr><w:pgMar w:top=\"!invalid!\"/></w:sectPr></w:pPr></w:p>",
                "2",
            ),
            (
                "columns",
                "",
                "<w:p><w:pPr><w:sectPr><w:cols w:num=\"!invalid!\"/></w:sectPr></w:pPr></w:p>",
                "2",
            ),
            (
                "table-width",
                "",
                "<w:tbl><w:tblPr><w:tblW w:w=\"!invalid!\"/></w:tblPr></w:tbl>",
                "2",
            ),
            (
                "table-band",
                "",
                "<w:tbl><w:tblPr><w:tblStyleRowBandSize w:val=\"!invalid!\"/></w:tblPr></w:tbl>",
                "2",
            ),
            (
                "table-position",
                "",
                "<w:tbl><w:tblPr><w:tblpPr w:tblpX=\"!invalid!\"/></w:tblPr></w:tbl>",
                "2",
            ),
            (
                "table-grid",
                "",
                "<w:tbl><w:tblGrid><w:gridCol w:w=\"!invalid!\"/></w:tblGrid></w:tbl>",
                "2",
            ),
            (
                "row-height",
                "",
                "<w:tbl><w:tr><w:trPr><w:trHeight w:val=\"!invalid!\"/></w:trPr></w:tr></w:tbl>",
                "2",
            ),
            (
                "row-grid-before",
                "",
                "<w:tbl><w:tr><w:trPr><w:gridBefore w:val=\"!invalid!\"/></w:trPr></w:tr></w:tbl>",
                "2",
            ),
            (
                "cell-grid-span",
                "",
                "<w:tbl><w:tr><w:tc><w:tcPr><w:gridSpan w:val=\"!invalid!\"/></w:tcPr><w:p/></w:tc></w:tr></w:tbl>",
                "2",
            ),
            (
                "cell-merge",
                "",
                "<w:tbl><w:tr><w:tc><w:tcPr><w:vMerge w:val=\"!invalid!\"/></w:tcPr><w:p/></w:tc></w:tr></w:tbl>",
                "continue",
            ),
            (
                "control-id",
                "<w:sdtPr><w:id w:val=\"!invalid!\"/></w:sdtPr>",
                "<w:p/>",
                "2",
            ),
            (
                "table-border",
                "",
                "<w:tbl><w:tblPr><w:tblBorders><w:insideH w:sz=\"!invalid!\"/></w:tblBorders></w:tblPr></w:tbl>",
                "2",
            ),
            (
                "cell-margin",
                "",
                "<w:tbl><w:tr><w:tc><w:tcPr><w:tcMar><w:top w:w=\"!invalid!\"/></w:tcMar></w:tcPr><w:p/></w:tc></w:tr></w:tbl>",
                "2",
            ),
        ];
        let mut failures = Vec::new();
        for (name, properties, bad, valid_value) in cases {
            for late in [false, true] {
                let tail = format!("<w:p>{}</w:p>", "<w:r><x:opaque/></w:r>".repeat(200));
                let children = if late {
                    format!("{tail}{bad}")
                } else {
                    format!("{bad}{tail}")
                };
                let control =
                    format!("<w:sdt>{properties}<w:sdtContent>{children}</w:sdtContent></w:sdt>");
                let oracle = control.replacen(
                    "<w:sdt>",
                    &format!(
                        "<w:sdt xmlns:w=\"{}\" xmlns:x=\"{uri}\">",
                        crate::namespace::W_NS
                    ),
                    1,
                );
                assert!(
                    crate::content_control::CT_Sdt::from_body_raw(oracle.as_bytes(), &[]).is_none(),
                    "actual constructor oracle {name}"
                );
                let source = format!(
                    "<w:document xmlns:w=\"{}\" xmlns:x=\"{uri}\"><w:body>{control}</w:body></w:document>",
                    crate::namespace::W_NS
                );
                if let Err(error) = super::admit_word_xml(source.as_bytes(), &[], None) {
                    failures.push(format!("{name} late={late}: {error}"));
                    continue;
                }
                crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
                let parsed = super::CT_Document::from_xml(source.as_bytes()).unwrap();
                assert!(
                    matches!(
                        parsed.body.content.as_slice(),
                        [super::BodyContent::RawXml(_)]
                    ),
                    "{name}"
                );
                assert_eq!(
                    crate::text::PARSED_RUN_CONSTRUCTIONS.get(),
                    0,
                    "{name} late={late}"
                );
                let valid = source.replace("!invalid!", valid_value);
                assert!(
                    super::admit_word_xml(valid.as_bytes(), &[], None)
                        .unwrap_err()
                        .to_string()
                        .contains("original source capture exceeds admitted source work"),
                    "typed owners still charged for {name}"
                );
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));
    }
    #[test]
    fn original_capture_unused_long_uri_selects_no_new_work() {
        let namespace = crate::namespace::W_NS;
        let uri = format!("urn:{}", "u".repeat(4096));
        let document = format!(
            "<w:document xmlns:w=\"{namespace}\" xmlns:x=\"{uri}\"><w:body><w:p>{}</w:p></w:body></w:document>",
            "<w:r><w:t>plain</w:t></w:r>".repeat(200)
        );
        super::admit_word_xml(document.as_bytes(), &[], None).unwrap();
        let parsed = super::CT_Document::from_xml(document.as_bytes()).unwrap();
        assert_eq!(parsed.body.paragraphs().count(), 1);
    }

