    #[test]
    fn original_capture_typed_drawing_without_word_use_stays_within_admitted_work() {
        let wp = "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing";
        // The inline declares its own prefix, so the parser copies no
        // ancestor binding into the retained raw record.
        let run = format!(
            "<w:r><w:drawing><wp:inline xmlns:wp=\"{wp}\"><wp:docPr id=\"1\"/></wp:inline></w:drawing></w:r>"
        );
        let document = format!(
            "<w:document xmlns:w=\"{}\"><w:body><w:p>{}</w:p></w:body></w:document>",
            crate::namespace::W_NS,
            run.repeat(400)
        );
        super::admit_word_xml(document.as_bytes(), &[], None).unwrap();
        let parsed = super::CT_Document::from_xml(document.as_bytes()).unwrap();
        let saved = String::from_utf8(parsed.to_xml().unwrap()).unwrap();
        assert!(
            saved.contains(&format!("<wp:inline xmlns:wp=\"{wp}\">")),
            "{saved}"
        );
        let paragraph = parsed.body.paragraphs().next().expect("one paragraph");
        let run = &paragraph.runs[0];
        assert!(
            !run.extra_xml.iter().any(|raw| {
                raw.starts_with(b"<rdocxRootAttributes")
                    && String::from_utf8_lossy(raw).contains("xmlns:wp=")
            }),
            "inline-local wp must not become a run-frame record"
        );
    }

