    #[test]
    fn original_capture_typed_drawing_retains_consumed_ancestor_binding() {
        let wp = "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing";
        let run =
            "<w:r><w:drawing><wp:inline><wp:docPr id=\"1\"/><w:o/></wp:inline></w:drawing></w:r>";
        let document = format!(
            "<w:document xmlns:w=\"{}\"><w:body><w:p xmlns:wp=\"{wp}\">{run}</w:p></w:body></w:document>",
            crate::namespace::W_NS,
        );
        let parsed = super::CT_Document::from_xml(document.as_bytes()).unwrap();
        let saved = String::from_utf8(parsed.to_xml().unwrap()).unwrap();
        assert!(saved.contains("<w:o/>"), "{saved}");
        let paragraph = parsed.body.paragraphs().next().expect("one paragraph");
        let run = &paragraph.runs[0];
        assert!(
            run.extra_xml.iter().any(|raw| {
                raw.starts_with(b"<rdocxRootAttributes")
                    && String::from_utf8_lossy(raw).contains("xmlns:w=")
            }),
            "consumed canonical w must reach the run-frame record"
        );
    }

    #[test]
    fn original_capture_typed_drawing_charges_document_scope_binding() {
        let wp = "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing";
        let uri = format!("urn:{}", "u".repeat(400));
        let run =
            "<w:r><w:drawing><wp:inline><wp:docPr id=\"1\"/><x:o/></wp:inline></w:drawing></w:r>";
        let document = format!(
            "<w:document xmlns:w=\"{}\" xmlns:x=\"{uri}\"><w:body><w:p xmlns:wp=\"{wp}\">{}</w:p></w:body></w:document>",
            crate::namespace::W_NS,
            run.repeat(400)
        );
        let error = super::admit_word_xml(document.as_bytes(), &[], None).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("original source capture exceeds admitted source work"),
            "unexpected refusal: {error}"
        );
        let single = format!(
            "<w:document xmlns:w=\"{}\" xmlns:x=\"{uri}\"><w:body><w:p xmlns:wp=\"{wp}\">{run}</w:p></w:body></w:document>",
            crate::namespace::W_NS,
        );
        let parsed = super::CT_Document::from_xml(single.as_bytes()).unwrap();
        let paragraph = parsed.body.paragraphs().next().expect("one paragraph");
        let run = &paragraph.runs[0];
        assert!(
            run.extra_xml.iter().any(|raw| {
                raw.starts_with(b"<rdocxRootAttributes")
                    && String::from_utf8_lossy(raw).contains("xmlns:x=")
            }),
            "document-scope binding used by the inline must reach the run-frame record"
        );
    }

    #[test]
    fn original_capture_typed_drawing_retains_drawing_scope_binding() {
        let wp = "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing";
        let uri = format!("urn:{}", "u".repeat(400));
        let run = format!(
            "<w:r><w:drawing xmlns:x=\"{uri}\"><wp:inline><wp:docPr id=\"1\"/><x:o/></wp:inline></w:drawing></w:r>"
        );
        // A drawing-scope declaration is present in each run's own input, so
        // charging it stays within the admitted work. The parser copies it
        // into the retained inline raw rather than into the run-frame record.
        let document = format!(
            "<w:document xmlns:w=\"{}\"><w:body><w:p xmlns:wp=\"{wp}\">{}</w:p></w:body></w:document>",
            crate::namespace::W_NS,
            run.repeat(400)
        );
        super::admit_word_xml(document.as_bytes(), &[], None).unwrap();
        let single = format!(
            "<w:document xmlns:w=\"{}\"><w:body><w:p xmlns:wp=\"{wp}\">{run}</w:p></w:body></w:document>",
            crate::namespace::W_NS,
        );
        let parsed = super::CT_Document::from_xml(single.as_bytes()).unwrap();
        let saved = String::from_utf8(parsed.to_xml().unwrap()).unwrap();
        assert!(
            saved.contains(&format!("<wp:inline xmlns:x=\"{uri}\">")),
            "drawing-scope binding must be copied into the retained inline: {saved}"
        );
        let paragraph = parsed.body.paragraphs().next().expect("one paragraph");
        let run = &paragraph.runs[0];
        assert!(
            !run.extra_xml.iter().any(|raw| {
                raw.starts_with(b"<rdocxRootAttributes")
                    && String::from_utf8_lossy(raw).contains("xmlns:x=")
            }),
            "a drawing-scope binding copied into the inline is not a run-frame record"
        );
    }

