    fn capture_document(declarations: &str, runs: &str) -> String {
        format!(
            "<w:document xmlns:w=\"{}\" {declarations}><w:body><w:p>{runs}</w:p></w:body></w:document>",
            crate::namespace::W_NS
        )
    }

    fn planning_uri_copies_for(xml: &str) -> usize {
        super::ORIGINAL_CAPTURE_PLANNING_URI_COPIES.with(|copies| copies.set(0));
        let _ = super::admit_word_xml(xml.as_bytes(), &[], None);
        super::ORIGINAL_CAPTURE_PLANNING_URI_COPIES.with(std::cell::Cell::get)
    }

    #[test]
    fn original_capture_empty_inline_and_anchor_select_no_record() {
        let uri = format!("urn:{}", "u".repeat(400));
        let wp = "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing";
        for child in [
            "<wp:inline x:keep=\"1\"/>".to_owned(),
            "<wp:anchor x:keep=\"1\"/>".to_owned(),
            "<w:inline x:keep=\"1\"/>".to_owned(),
            "<w:anchor x:keep=\"1\"/>".to_owned(),
        ] {
            let run = format!("<w:r><w:drawing>{child}</w:drawing></w:r>");
            let document = capture_document(
                &format!("xmlns:wp=\"{wp}\" xmlns:x=\"{uri}\""),
                &run.repeat(160),
            );
            super::admit_word_xml(document.as_bytes(), &[], None).unwrap_or_else(|error| {
                panic!("empty {child} must not charge a record the parser drops: {error}");
            });
        }
        let positive = capture_document(
            &format!("xmlns:wp=\"{wp}\" xmlns:x=\"{uri}\""),
            &"<w:r><w:drawing><wp:inline><x:o/></wp:inline></w:drawing></w:r>".repeat(160),
        );
        let error = super::admit_word_xml(positive.as_bytes(), &[], None).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("original source capture exceeds admitted source work"),
            "a nonempty inline that uses the ancestor binding stays charged: {error}"
        );
        let single = capture_document(
            &format!("xmlns:wp=\"{wp}\" xmlns:x=\"{uri}\""),
            "<w:r><w:drawing><wp:inline x:keep=\"1\"/></w:drawing></w:r>",
        );
        let parsed = super::CT_Document::from_xml(single.as_bytes()).unwrap();
        let saved = String::from_utf8(parsed.to_xml().unwrap()).unwrap();
        assert!(saved.contains("<w:drawing></w:drawing>"), "{saved}");
        assert!(!saved.contains("x:keep"), "{saved}");
    }

