    #[test]
    fn original_capture_physical_drawing_copies_are_not_deduped() {
        let uri = format!("urn:{}", "d".repeat(400));
        let both = format!(
            "<w:r><w:drawing xmlns:x=\"{uri}\"><inline><x:a/></inline><anchor><x:b/></anchor></w:drawing></w:r>"
        );
        let refused = capture_document("", &both.repeat(160));
        let error = super::admit_word_xml(refused.as_bytes(), &[], None).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("original source capture exceeds admitted source work"),
            "inline and anchor each store the drawing-local binding: {error}"
        );
        let shared =
            "<w:r><w:drawing><inline><x:a/></inline><anchor><x:b/></anchor></w:drawing></w:r>"
                .to_owned();
        let inherited = capture_document(&format!("xmlns:x=\"{uri}\""), &shared.repeat(40));
        super::admit_word_xml(inherited.as_bytes(), &[], None).unwrap_or_else(|error| {
            panic!("one inherited binding used by both raws is one shared record: {error}");
        });
        let separate = format!(
            "<w:r><w:drawing xmlns:x=\"{uri}\"><wp:inline><wp:docPr id=\"1\"/><x:a/></wp:inline></w:drawing><w:drawing xmlns:x=\"{uri}\"><wp:anchor><wp:docPr id=\"2\"/><x:b/></wp:anchor></w:drawing></w:r>"
        );
        // Each drawing already contains the URI, and each raw stores one copy.
        // That pair stays inside the unchanged allowance at every repeat count.
        // The stored bytes show the copies are not collapsed.
        let wp = "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing";
        super::admit_word_xml(
            capture_document(&format!("xmlns:wp=\"{wp}\""), &separate.repeat(160)).as_bytes(),
            &[],
            None,
        )
        .unwrap_or_else(|error| {
            panic!("two source-local drawing copies stay within admitted work: {error}");
        });
        let parsed = super::CT_Document::from_xml(
            capture_document(&format!("xmlns:wp=\"{wp}\""), &separate).as_bytes(),
        )
        .unwrap();
        let saved = String::from_utf8(parsed.to_xml().unwrap()).unwrap();
        assert_eq!(
            saved.matches(&format!("xmlns:x=\"{uri}\"")).count(),
            2,
            "{saved}"
        );
        let local =
            format!("<w:r xmlns:x=\"{uri}\"><w:drawing><inline><x:a/></inline></w:drawing></w:r>");
        let lexical = capture_document("", &local.repeat(200));
        let error = super::admit_word_xml(lexical.as_bytes(), &[], None).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("original source capture exceeds admitted source work"),
            "a run-root declaration used by a drawing charges the shared and local records: {error}"
        );
        let one_copy =
            format!("<w:r><w:drawing xmlns:x=\"{uri}\"><inline><x:a/></inline></w:drawing></w:r>");
        super::admit_word_xml(
            capture_document("", &one_copy.repeat(160)).as_bytes(),
            &[],
            None,
        )
        .unwrap_or_else(|error| {
            panic!("one physical raw copy of a drawing-local binding stays admitted: {error}");
        });
    }

    #[test]
    fn original_capture_default_namespace_dependencies_match_recorded_bindings() {
        let uri = format!("urn:{}", "n".repeat(400));
        let opaque = "<w:r><opaque/></w:r>";
        let refused = capture_document(&format!("xmlns=\"{uri}\""), &opaque.repeat(160));
        let error = super::admit_word_xml(refused.as_bytes(), &[], None).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("original source capture exceeds admitted source work"),
            "an inherited default namespace used by an unprefixed child is one record per run: {error}"
        );
        let admitted = capture_document(&format!("xmlns=\"{uri}\""), opaque);
        super::admit_word_xml(admitted.as_bytes(), &[], None).unwrap();
        let parsed = super::CT_Document::from_xml(admitted.as_bytes()).unwrap();
        let run = &parsed.body.paragraphs().next().expect("paragraph").runs[0];
        assert!(
            run.extra_xml
                .iter()
                .any(|raw| { String::from_utf8_lossy(raw).contains(&format!("xmlns=\"{uri}\"")) }),
            "the retained run record keeps the default namespace"
        );
        for child in [
            "<w:r><opaque xmlns=\"urn:short\"/></w:r>",
            "<w:r><opaque xmlns=\"\"/></w:r>",
            "<w:r><x:opaque xmlns:x=\"urn:x\" keep=\"1\"/></w:r>",
        ] {
            let document = capture_document(&format!("xmlns=\"{uri}\""), &child.repeat(160));
            super::admit_word_xml(document.as_bytes(), &[], None).unwrap_or_else(|error| {
                panic!("a shadowed, cleared, or unprefixed attribute does not take the inherited default: {child} {error}");
            });
        }
        let xsi = "http://www.w3.org/2001/XMLSchema-instance";
        let bare = "<w:r><x:opaque xmlns:x=\"urn:x\" xsi:type=\"bare\"/></w:r>";
        let qname = capture_document(
            &format!("xmlns=\"{uri}\" xmlns:xsi=\"{xsi}\""),
            &bare.repeat(160),
        );
        let error = super::admit_word_xml(qname.as_bytes(), &[], None).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("original source capture exceeds admitted source work"),
            "an unprefixed xsi:type token uses the default namespace: {error}"
        );
        let prefixed =
            "<w:r><x:opaque xmlns:x=\"urn:x\" xmlns:p=\"urn:p\" xsi:type=\"p:bare\"/></w:r>";
        super::admit_word_xml(
            capture_document(
                &format!("xmlns=\"{uri}\" xmlns:xsi=\"{xsi}\""),
                &prefixed.repeat(160),
            )
            .as_bytes(),
            &[],
            None,
        )
        .unwrap_or_else(|error| {
            panic!("a prefixed xsi:type token does not take the default namespace: {error}");
        });
    }

