    #[test]
    fn original_capture_special_child_option_outcomes_charge_only_actual_raw_records() {
        use crate::text::{CT_R, RunContent};
        let word = crate::namespace::W_NS;
        let uri = format!("urn:{}", "u".repeat(400));
        let scope = vec![
            "w".to_owned(),
            format!("\0w\0{word}"),
            format!("\0x\0{uri}"),
        ];
        for child in [
            r#"<w:sym w:font="Font" w:char="0000" x:opaque="v"/>"#,
            r#"<w:ptab w:alignment="left" w:relativeTo="margin" w:leader="none" x:opaque="v"/>"#,
            r#"<w:cr x:opaque="v"/>"#,
        ] {
            let raw = format!("<w:r>{child}</w:r>");
            let mut reader = quick_xml::Reader::from_reader(raw.as_bytes());
            let quick_xml::events::Event::Start(start) = reader.read_event().unwrap() else {
                panic!("run")
            };
            let run =
                CT_R::from_xml_with_prefixes_and_root(&mut reader, &scope, Some(&start), None)
                    .unwrap();
            assert!(
                !run.content.iter().any(|content| matches!(
                    content,
                    RunContent::Symbol { .. } | RunContent::SpecialCharacter(_)
                )),
                "actual special parser retains this child raw"
            );
            assert!(
                run.extra_xml
                    .iter()
                    .any(|raw| raw.windows(uri.len()).any(|bytes| bytes == uri.as_bytes())),
                "actual run owns an expanded external namespace record"
            );
            let source = format!(
                "<w:document xmlns:w=\"{word}\" xmlns:x=\"{uri}\"><w:body><w:p>{}</w:p></w:body></w:document>",
                raw.repeat(200)
            );
            assert!(
                super::admit_word_xml(source.as_bytes(), &[], None)
                    .unwrap_err()
                    .to_string()
                    .contains("original source capture exceeds admitted source work"),
                "only real raw children create the repeated record charge"
            );
            crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
            assert!(super::CT_Document::from_xml(source.as_bytes()).is_err());
            assert_eq!(
                crate::text::PARSED_RUN_CONSTRUCTIONS.get(),
                0,
                "refuse before actual run/source record construction"
            );
            let typed = source.replace(" x:opaque=\"v\"", "");
            super::admit_word_xml(typed.as_bytes(), &[], None)
                .expect("typed special children do not copy unused namespace records");
            let no_growth = source.replace("x:opaque=\"v\"", "data-opaque=\"v\"");
            super::admit_word_xml(no_growth.as_bytes(), &[], None)
                .expect("raw outcome alone is not a refusal when it selects no expanded binding");
        }
    }

