    fn original_capture_ruby_all_reached_runs_keep_late_none_boundary() {
        let word = crate::namespace::W_NS;
        let uri = format!("urn:{}", "u".repeat(400));
        let tail = "<w:r><x:opaque/></w:r>".repeat(200);
        for prefix in [
            "<w:r><w:t>first</w:t></w:r><w:r><w:t>second</w:t></w:r>",
            "<w:r/><w:r><w:rPr><w:b/></w:rPr><w:t>second</w:t></w:r>",
            "<w:r><w:t>first</w:t></w:r><w:r/>",
        ] {
            let ruby = format!(
                r#"<w:ruby xmlns:w="{word}" xmlns:x="{uri}"><w:rt>{prefix}</w:rt><w:rubyPr>BAD</w:rubyPr><w:rubyBase>{tail}</w:rubyBase></w:ruby>"#
            );
            crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
            assert!(
                crate::ruby::CT_Ruby::from_raw(ruby.as_bytes(), &[])
                    .unwrap()
                    .is_none()
            );
            let reached = crate::text::PARSED_RUN_CONSTRUCTIONS.get();
            let source = format!(
                r#"<w:document xmlns:w="{word}"><w:body><w:p>{ruby}</w:p></w:body></w:document>"#
            );
            crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
            let parsed = super::CT_Document::from_xml(source.as_bytes())
                .expect("all successful run prefixes preserve the actual later None");
            assert_eq!(crate::text::PARSED_RUN_CONSTRUCTIONS.get(), reached);
            assert!(
                parsed
                    .to_xml()
                    .unwrap()
                    .windows(ruby.len())
                    .any(|v| v == ruby.as_bytes())
            );
            assert!(
                super::admit_word_xml(
                    source
                        .replace("<w:rubyPr>BAD</w:rubyPr>", "<w:rubyPr/>")
                        .as_bytes(),
                    &[],
                    None
                )
                .is_err()
            );
        }
    }

