    #[test]
    fn original_capture_ruby_captured_root_prefix_defers_completion_until_success() {
        let word = crate::namespace::W_NS;
        let uri = format!("urn:{}", "u".repeat(400));
        let tail = "<w:r><x:opaque/></w:r>".repeat(200);
        for raw in [
            "<x:opaque/>",
            "<x:opaque><w:r><w:commentReference w:id=\"bad\"/></w:r></x:opaque>",
        ] {
            for aliased in [false, true] {
                let mut ruby = format!(
                    r#"<w:ruby xmlns:w="{word}" xmlns:x="{uri}">{raw}<w:rubyPr><w:hps w:val="10"></w:hps>BAD</w:rubyPr><w:rubyBase>{tail}</w:rubyBase></w:ruby>"#
                );
                if aliased {
                    ruby = ruby.replace("w:", "q:").replace("xmlns:w=", "xmlns:q=");
                    ruby = ruby.replacen("<q:ruby ", "<q:ruby xmlns:w=\"urn:foreign\" ", 1);
                }
                crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
                assert!(
                    crate::ruby::CT_Ruby::from_raw(ruby.as_bytes(), &[])
                        .unwrap()
                        .is_none()
                );
                assert_eq!(crate::text::PARSED_RUN_CONSTRUCTIONS.get(), 0);
                let source = format!(
                    r#"<w:document xmlns:w="{word}"><w:body><w:p>{ruby}</w:p></w:body></w:document>"#
                );
                let parsed = super::CT_Document::from_xml(source.as_bytes())
                    .expect("captured raw prefix does not run success-only completion before None");
                assert!(
                    parsed
                        .to_xml()
                        .unwrap()
                        .windows(ruby.len())
                        .any(|v| v == ruby.as_bytes())
                );
                assert!(
                    super::admit_word_xml(source.replace("BAD</", "</").as_bytes(), &[], None)
                        .is_err(),
                    "actual success still reaches the resource-heavy base"
                );
            }
        }
    }

