    #[test]
    fn original_capture_ruby_eof_capture_keeps_actual_scalar_and_opening_context() {
        let word = crate::namespace::W_NS;
        let value = "a".repeat(64 * 1024);
        for closing in ["", "</w:opaque>"] {
            let ruby = format!(
                r#"<w:ruby xmlns:w="{word}"><w:rubyPr><w:lid w:val="{value}"><w:opaque xmlns:w="urn:foreign">{closing}"#
            );
            crate::ruby::RUBY_PROPERTY_READS.set(0);
            crate::ruby::RUBY_PROPERTY_LANGUAGE_BYTES.set(0);
            assert!(
                crate::ruby::CT_Ruby::from_raw(ruby.as_bytes(), &[])
                    .unwrap()
                    .is_none(),
                "EOF capture is intentionally permissive and missing base is None"
            );
            assert_eq!(crate::ruby::RUBY_PROPERTY_READS.get(), 1);
            assert_eq!(crate::ruby::RUBY_PROPERTY_LANGUAGE_BYTES.get(), value.len());
            crate::ruby::RUBY_PROPERTY_READS.set(0);
            crate::ruby::RUBY_PROPERTY_LANGUAGE_BYTES.set(0);
            let source = format!(r#"<w:p xmlns:w="{word}">{ruby}"#);
            let mut pool = super::CaptureDeclarations::default();
            let _ = super::qualify_constructor_failures(
                super::WordXmlInput::Contiguous(source.as_bytes()),
                &[],
                &mut pool,
                None,
                &[],
                None,
                None,
            )
            .unwrap();
            assert_eq!(
                crate::ruby::RUBY_PROPERTY_READS.get(),
                1,
                "EOF reaches the same scalar under its opening Word scope"
            );
            assert_eq!(crate::ruby::RUBY_PROPERTY_LANGUAGE_BYTES.get(), value.len());
            let split = source.find("w:val").unwrap() + 3;
            let pieces = [
                &source.as_bytes()[..split],
                &source.as_bytes()[split..split + 111],
                &source.as_bytes()[split + 111..],
            ];
            crate::ruby::RUBY_PROPERTY_READS.set(0);
            crate::ruby::RUBY_PROPERTY_LANGUAGE_BYTES.set(0);
            let mut pool = super::CaptureDeclarations::default();
            super::qualify_constructor_failures(
                super::WordXmlInput::pieces(&pieces),
                &[],
                &mut pool,
                None,
                &[],
                None,
                None,
            )
            .unwrap();
            assert_eq!(crate::ruby::RUBY_PROPERTY_READS.get(), 1);
            assert_eq!(crate::ruby::RUBY_PROPERTY_LANGUAGE_BYTES.get(), value.len());
        }
    }

    #[test]
    fn original_capture_ruby_empty_raw_properties_defer_only_completion() {
        let word = crate::namespace::W_NS;
        let uri = format!("urn:{}", "u".repeat(400));
        let tail = "<w:r><x:opaque/></w:r>".repeat(200);
        let mut outcomes = Vec::new();
        for property in [
            "<w:hps/>",
            r#"<w:hps w:val="bad"/>"#,
            r#"<w:hpsRaise w:val="-2"/>"#,
            "<x:opaque/>",
            "<w:lid/>",
        ] {
            let ruby = format!(
                r#"<w:ruby xmlns:w="{word}" xmlns:x="{uri}"><w:rt><w:r><w:t>prefix</w:t></w:r></w:rt><w:rubyPr>{property}BAD</w:rubyPr><w:rubyBase>{tail}</w:rubyBase></w:ruby>"#
            );
            crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
            assert!(
                crate::ruby::CT_Ruby::from_raw(ruby.as_bytes(), &[])
                    .unwrap()
                    .is_none()
            );
            assert_eq!(crate::text::PARSED_RUN_CONSTRUCTIONS.get(), 1);
            let source = format!(
                r#"<w:document xmlns:w="{word}"><w:body><w:p>{ruby}</w:p></w:body></w:document>"#
            );
            let parsed = super::CT_Document::from_xml(source.as_bytes());
            outcomes.push(parsed.is_ok());
            if let Ok(parsed) = parsed {
                assert!(
                    parsed
                        .to_xml()
                        .unwrap()
                        .windows(ruby.len())
                        .any(|bytes| bytes == ruby.as_bytes())
                );
            }
            let no_none = source.replace("BAD</w:rubyPr>", "</w:rubyPr>");
            assert!(
                super::admit_word_xml(no_none.as_bytes(), &[], None).is_err(),
                "without the actual None the base constructors are still reached"
            );
            let mut earlier_error = ruby
                .replace("BAD</w:rubyPr>", "<w:lid w:val=\"INVALID\"/>BAD</w:rubyPr>")
                .into_bytes();
            let offset = earlier_error
                .windows(7)
                .position(|bytes| bytes == b"INVALID")
                .unwrap();
            earlier_error.splice(offset..offset + 7, [0xff]);
            assert!(crate::ruby::CT_Ruby::from_raw(&earlier_error, &[]).is_err());
            let mut outer = format!(r#"<w:sdt xmlns:w="{word}"><w:sdtContent><w:p>"#).into_bytes();
            outer.extend_from_slice(&earlier_error);
            outer.extend_from_slice(b"</w:p></w:sdtContent></w:sdt>");
            let admitted = super::admit_word_source(
                &outer,
                &[],
                None,
                Some(crate::content_control::SdtOwner::Body),
            );
            // A genuine reached error must not become a swallowed Ruby None.
            // Collect this outcome with the positive one for all raw variants.
            outcomes.push(admitted.is_ok_and(|admitted| admitted.constructors.root_raw));
        }
        assert_eq!(
            outcomes, [true; 10],
            "empty raw capture precedes None, but deferred completion does not"
        );
    }

