    #[test]
    fn original_capture_inline_drawing_opaque_word_names_are_not_model_owners() {
        use crate::text::{CT_R, RunContent};
        let word = crate::namespace::W_NS;
        let wp = "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing";
        let uri = format!("urn:{}", "u".repeat(400));
        let runs = "<w:r><x:opaque/></w:r>".repeat(200);
        let raw = format!(
            "<w:r><w:drawing><wp:inline><wp:docPr id=\"1\" name=\"I\"/><x:container><w:p>{runs}</w:p></x:container></wp:inline></w:drawing></w:r>"
        );
        let scope = vec![
            "w".into(),
            format!("\0w\0{word}"),
            format!("\0wp\0{wp}"),
            format!("\0x\0{uri}"),
        ];
        let mut reader = quick_xml::Reader::from_reader(raw.as_bytes());
        let quick_xml::events::Event::Start(start) = reader.read_event().unwrap() else {
            panic!("run")
        };
        crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
        let run =
            CT_R::from_xml_with_prefixes_and_root(&mut reader, &scope, Some(&start), None).unwrap();
        assert_eq!(
            crate::text::PARSED_RUN_CONSTRUCTIONS.get(),
            1,
            "actual inline reader never constructs Word runs"
        );
        assert!(
            matches!(run.content.as_slice(), [RunContent::Drawing(drawing)] if drawing.inline.is_some())
        );
        let source = format!(
            "<w:document xmlns:w=\"{word}\" xmlns:wp=\"{wp}\" xmlns:x=\"{uri}\"><w:body><w:p>{raw}</w:p></w:body></w:document>"
        );
        crate::text::PARSED_RUN_CONSTRUCTIONS.set(0);
        super::CT_Document::from_xml(source.as_bytes())
            .expect("opaque inline names do not create independent run owners");
        assert_eq!(crate::text::PARSED_RUN_CONSTRUCTIONS.get(), 1);
    }

    #[test]
    fn original_capture_property_leaves_do_not_invent_run_owners() {
        let uri = format!("urn:{}", "p".repeat(400));
        let decls = format!("xmlns:x=\"{uri}\"");
        // `<w:r x:keep="1"/>` does manufacture a root-attribute record, but
        // those attribute bytes also enter the allowance at factor 124, so
        // repeating it stays inside the envelope. A child element of that
        // false owner charges a shared record and is the refusal witness.
        for child in [
            "<w:r><w:rPr><x:box><w:r><x:child/></w:r></x:box></w:rPr><w:t>t</w:t></w:r>",
            "<w:r><w:rPr><w:r><x:child/></w:r></w:rPr></w:r>",
            "<w:pPr><x:box><w:r><x:child/></w:r></x:box></w:pPr>",
            "<w:r><w:rPr><w:ins w:id=\"1\"><w:r><x:child/></w:r></w:ins></w:rPr></w:r>",
            "<w:ruby w:mark=\"1\"><w:rt><w:r><x:child/></w:r></w:rt><w:rubyBase><w:r><w:t>b</w:t></w:r></w:rubyBase></w:ruby>",
        ] {
            super::admit_word_xml(
                capture_document(&decls, &child.repeat(160)).as_bytes(),
                &[],
                None,
            )
            .unwrap_or_else(|error| {
                panic!("a property extension is not a constructed run owner: {child} {error}");
            });
        }
        for child in [
            "<w:r><w:rPr><w:ins w:id=\"1\" w:author=\"a\"><w:r><x:child/></w:r></w:ins></w:rPr></w:r>",
            "<w:ins w:id=\"1\"><w:r><x:child/></w:r></w:ins>",
            "<w:ruby><w:rt><w:r><x:child/></w:r></w:rt><w:rubyBase><w:r><w:t>b</w:t></w:r></w:rubyBase></w:ruby>",
        ] {
            let error = super::admit_word_xml(
                capture_document(&decls, &child.repeat(160)).as_bytes(),
                &[],
                None,
            )
            .unwrap_err();
            assert!(
                error
                    .to_string()
                    .contains("original source capture exceeds admitted source work"),
                "a constructor that parses nested runs still charges them: {child} {error}"
            );
        }
    }

    #[test]
    fn original_capture_redundant_drawing_declaration_is_not_lost() {
        let uri = format!("urn:{}", "d".repeat(400));
        let both = format!(
            "<w:r><w:drawing xmlns:x=\"{uri}\"><inline><x:a/></inline><anchor><x:b/></anchor></w:drawing></w:r>"
        );
        // At 160 owners the two-copy charge is 2593 bytes over the allowance
        // and the one shared record is 60287 bytes under it.
        super::admit_word_xml(
            capture_document(&format!("xmlns:x=\"{uri}\""), &both.repeat(160)).as_bytes(),
            &[],
            None,
        )
        .unwrap_or_else(|error| {
            panic!("a drawing declaration that repeats the run-frame URI is not injected into each raw: {error}");
        });
        let other = format!("urn:{}", "q".repeat(400));
        let rebound = format!(
            "<w:r><w:drawing xmlns:x=\"{other}\"><inline><x:a/></inline><anchor><x:b/></anchor></w:drawing></w:r>"
        );
        let error = super::admit_word_xml(
            capture_document(&format!("xmlns:x=\"{uri}\""), &rebound.repeat(160)).as_bytes(),
            &[],
            None,
        )
        .unwrap_err();
        assert!(
            error
                .to_string()
                .contains("original source capture exceeds admitted source work"),
            "a rebound drawing URI is still stored on both raws: {error}"
        );
        let wp = "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing";
        let shaped = format!(
            "<w:r><w:drawing xmlns:x=\"{uri}\"><wp:inline xmlns:wp=\"{wp}\"><wp:docPr id=\"1\"/><x:a/></wp:inline><wp:anchor xmlns:wp=\"{wp}\"><wp:docPr id=\"2\"/><x:b/></wp:anchor></w:drawing></w:r>"
        );
        let parsed = super::CT_Document::from_xml(
            capture_document(&format!("xmlns:x=\"{uri}\""), &shaped).as_bytes(),
        )
        .unwrap();
        let saved = String::from_utf8(parsed.to_xml().unwrap()).unwrap();
        let run = &parsed.body.paragraphs().next().expect("paragraph").runs[0];
        assert!(
            run.extra_xml.iter().any(|raw| {
                raw.starts_with(b"<rdocxRootAttributes")
                    && String::from_utf8_lossy(raw).contains(&format!("xmlns:x=\"{uri}\""))
            }),
            "the repeated URI stays on the shared run record: {saved}"
        );
        assert!(
            !saved.contains(&format!("<wp:inline xmlns:x=\"{uri}\"")),
            "the drawing parser does not inject a binding the run frame already has: {saved}"
        );
        assert!(
            !saved.contains(&format!("<wp:anchor xmlns:x=\"{uri}\"")),
            "the drawing parser does not inject a binding the run frame already has: {saved}"
        );
        let lost = format!(
            "<w:r><w:drawing xmlns:x=\"{other}\"><wp:inline xmlns:wp=\"{wp}\"><wp:docPr id=\"1\"/><x:a/></wp:inline><wp:anchor xmlns:wp=\"{wp}\"><wp:docPr id=\"2\"/><x:b/></wp:anchor></w:drawing></w:r>"
        );
        let parsed = super::CT_Document::from_xml(
            capture_document(&format!("xmlns:x=\"{uri}\""), &lost).as_bytes(),
        )
        .unwrap();
        let saved = String::from_utf8(parsed.to_xml().unwrap()).unwrap();
        assert_eq!(
            saved.matches(&format!("xmlns:x=\"{other}\"")).count(),
            2,
            "each raw keeps the rebound URI: {saved}"
        );
    }

    #[test]
    fn original_capture_planning_does_not_repeat_shared_uri() {
        let uri = format!("urn:{}", "u".repeat(400));
        let run = "<w:r><x:opaque/></w:r>";
        let refused = capture_document(&format!("xmlns:x=\"{uri}\""), &run.repeat(200));
        let copies = planning_uri_copies_for(&refused);
        assert_eq!(
            copies, 2,
            "planning retains Word and the shared producer URI once, not once per owner"
        );
        let error = super::admit_word_xml(refused.as_bytes(), &[], None).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("original source capture exceeds admitted source work"),
            "{error}"
        );
        let admitted = capture_document(&format!("xmlns:x=\"{uri}\""), &run.repeat(20));
        assert_eq!(planning_uri_copies_for(&admitted), 2);
        let shadowed = capture_document(
            &format!("xmlns:x=\"{uri}\" xmlns:q=\"urn:q\""),
            &run.repeat(20),
        );
        assert_eq!(
            planning_uri_copies_for(&shadowed),
            3,
            "one new namespace is one planning entry, including when no owner uses it"
        );
        super::admit_word_xml(admitted.as_bytes(), &[], None).unwrap();
    }

    #[test]
    fn fx211_table_source_limit_is_inclusive_and_survives_owner_captures() {
        let wrap = |payload: &str| {
            format!(
                "<w:document xmlns:w=\"{}\" xmlns:wp=\"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\"><w:body>{payload}</w:body></w:document>",
                crate::namespace::W_NS
            )
        };
        let table = |depth: usize| {
            format!(
                "{}<w:p/>{}",
                "<w:tbl><w:tr><w:tc>".repeat(depth),
                "</w:tc></w:tr></w:tbl>".repeat(depth)
            )
        };
        for depth in [32, 33] {
            let payload = table(depth);
            let result = super::admit_word_xml(wrap(&payload).as_bytes(), &[], None);
            assert_eq!(result.is_ok(), depth == 32, "source table depth {depth}");
            // A typed control causes the local parser to enter another table
            // at depth zero. Independent source admission must not reset it.
            let controlled = format!(
                "{}<w:sdt><w:sdtContent>{}</w:sdtContent></w:sdt>{}",
                "<w:tbl><w:tr><w:tc>".repeat(depth - 1),
                table(1),
                "</w:tc></w:tr></w:tbl>".repeat(depth - 1)
            );
            assert_eq!(
                super::admit_word_xml(wrap(&controlled).as_bytes(), &[], None).is_ok(),
                depth == 32
            );
            let boxed = controlled
                .replace(
                    "<w:sdt><w:sdtContent>",
                    "<w:p><w:r><w:drawing><wp:anchor><wp:docPr id=\"1\"/><w:txbxContent>",
                )
                .replace(
                    "</w:sdtContent></w:sdt>",
                    "</w:txbxContent></wp:anchor></w:drawing></w:r></w:p>",
                );
            assert_eq!(
                super::admit_word_xml(wrap(&boxed).as_bytes(), &[], None).is_ok(),
                depth == 32
            );
        }
        super::admit_word_xml(
            wrap(&format!("{}{}", table(32), table(32))).as_bytes(),
            &[],
            None,
        )
        .unwrap();
        let foreign = format!(
            "<x:opaque xmlns:x=\"urn:opaque\">{}</x:opaque><w:p/>",
            table(33)
        );
        super::admit_word_xml(wrap(&foreign).as_bytes(), &[], None).unwrap();
    }

    #[test]
    fn fx211_table_32_actual_model_lifecycle_and_33_writer_refusal() {
        let mut table = crate::table::CT_Tbl::new();
        for _ in 1..32 {
            let mut outer = crate::table::CT_Tbl::new();
            let mut row = crate::table::CT_Row::new();
            let mut cell = crate::table::CT_Tc::new();
            cell.content = vec![crate::table::CellContent::Table(table)];
            row.cells = vec![cell];
            outer.rows = vec![row];
            table = outer;
        }
        let count_tables = |root: &crate::table::CT_Tbl| {
            let mut pending = vec![root];
            let mut count = 0;
            while let Some(table) = pending.pop() {
                count += 1;
                for row in &table.rows {
                    for cell in &row.cells {
                        for child in &cell.content {
                            if let crate::table::CellContent::Table(table) = child {
                                pending.push(table);
                            }
                        }
                    }
                }
            }
            count
        };
        assert_eq!(count_tables(&table), 32);
        super::admit_word_model(super::WordOwner::Table(&table)).unwrap();
        let mut model = super::CT_Document::from_xml(
            format!(
                "<w:document xmlns:w=\"{}\"><w:body/></w:document>",
                crate::namespace::W_NS
            )
            .as_bytes(),
        )
        .unwrap();
        model.body.content = vec![super::BodyContent::Table(Box::new(table))];
        let clone = model.clone();
        let saved = clone.to_xml().unwrap();
        let reopened = super::CT_Document::from_xml(&saved).unwrap();
        reopened.validate_resource_limits().unwrap();
        let super::BodyContent::Table(reopened_table) = &reopened.body.content[0] else {
            panic!("reopened table");
        };
        assert_eq!(count_tables(reopened_table), 32);
        assert_eq!(reopened.to_xml().unwrap(), saved);
        println!("actual authored32 clone/save/source-parse/reopen qualified");
        drop(reopened);
        drop(clone);
        let super::BodyContent::Table(inner) = model.body.content.remove(0) else {
            panic!("table");
        };
        let mut table = crate::table::CT_Tbl::new();
        let mut row = crate::table::CT_Row::new();
        let mut cell = crate::table::CT_Tc::new();
        cell.content = vec![crate::table::CellContent::Table(*inner)];
        row.cells = vec![cell];
        table.rows = vec![row];
        assert!(super::admit_word_model(super::WordOwner::Table(&table)).is_err());
        let mut output = vec![9, 8, 7];
        assert!(
            table
                .to_xml(&mut quick_xml::Writer::new(&mut output))
                .is_err()
        );
        assert_eq!(output, vec![9, 8, 7]);
    }

    #[test]
    fn fx211_authored_table_guard_refuses_existing_limit_without_serializing() {
        let mut outcomes = Vec::new();
        for depth in [33, 128] {
            let mut table = crate::table::CT_Tbl::new();
            for _ in 1..depth {
                let mut outer = crate::table::CT_Tbl::new();
                let mut row = crate::table::CT_Row::new();
                let mut cell = crate::table::CT_Tc::new();
                cell.content = vec![crate::table::CellContent::Table(table)];
                row.cells = vec![cell];
                outer.rows = vec![row];
                table = outer;
            }
            let result = super::admit_word_model(super::WordOwner::Table(&table));
            println!("authored tables={depth} guarded result={result:?}");
            // The failing-before control never serializes or recursively clones
            // over-limit ownership, and dismantles it iteratively before panic.
            let mut pending = vec![table];
            while let Some(table) = pending.pop() {
                for row in table.rows {
                    for cell in row.cells {
                        for child in cell.content {
                            if let crate::table::CellContent::Table(table) = child {
                                pending.push(table);
                            }
                        }
                    }
                }
            }
            outcomes.push(result);
        }
        for result in outcomes {
            assert!(
                result.is_err(),
                "authored table limit must apply before recursion"
            );
        }
    }

    #[test]
    fn model_alternate_drawings_follow_existing_anchor_budget() {
        fn drawing_run(depth: usize, alternate: bool, authoritative: bool) -> crate::text::CT_R {
            let mut run = crate::text::CT_R::new("leaf");
            for _ in 0..depth {
                let mut paragraph = crate::text::CT_P::new();
                paragraph.runs.push(run);
                let mut shape = crate::drawing::CT_Shape::default();
                if authoritative {
                    let mut body = super::CT_Body::new();
                    body.content
                        .push(super::BodyContent::Paragraph(Box::new(paragraph)));
                    shape.text_body = Some(body);
                } else {
                    shape.text.push(paragraph);
                }
                let mut anchor = crate::drawing::CT_Anchor::background("", 0, 0);
                anchor.shape = Some(shape);
                let drawing = crate::drawing::CT_Drawing::anchor(anchor);
                run = crate::text::CT_R::new("");
                if alternate {
                    run.alt_drawings.push(drawing);
                } else {
                    run.content.push(crate::text::RunContent::Drawing(drawing));
                }
            }
            run
        }
        for authoritative in [false, true] {
            for alternate in [false, true] {
                for depth in [1, 16, 17] {
                    let run = drawing_run(depth, alternate, authoritative);
                    let actual = super::admit_word_model(super::WordOwner::Run(&run));
                    let reference = super::admit_word_model_reference(super::WordOwner::Run(&run));
                    assert_eq!(
                        actual.as_ref().map(|_| ()).map_err(ToString::to_string),
                        reference.as_ref().map(|_| ()).map_err(ToString::to_string)
                    );
                    assert_eq!(
                        actual.is_ok(),
                        depth <= 16,
                        "alternate={alternate}, authoritative={authoritative}, depth={depth}"
                    );
                    if actual.is_ok() {
                        assert_eq!(super::MODEL_LAST_ROOT_MAXIMA.get(), (16 * depth, 0));
                    }
                }
            }
        }
    }

    #[test]
    fn model_summary_finish_survives_wide_queue_growth_and_shared_roots() {
        for count in [0, 1, 513] {
            let mut body = super::CT_Body::new();
            for index in 0..count {
                let mut paragraph = crate::text::CT_P::new();
                paragraph.add_run(&format!("node {index}"));
                body.add_paragraph(paragraph);
            }
            let mut roots = vec![super::WordOwner::Body(&body)];
            if let Some(super::BodyContent::Paragraph(paragraph)) = body.content.first() {
                roots.push(super::WordOwner::Paragraph(paragraph));
                roots.push(super::WordOwner::Body(&body));
            }
            assert_eq!(
                super::word_model_children_maxima(&roots, 0).unwrap(),
                (0, 0)
            );
            assert_eq!(
                super::word_model_children_maxima(&roots, 256).unwrap(),
                (0, 0)
            );
            super::admit_word_model_reference(super::WordOwner::Body(&body)).unwrap();
        }

        let template = crate::content_control::CT_Sdt::from_body_raw(
            format!(
                "<w:sdt xmlns:w='{}'><w:sdtContent><w:p/></w:sdtContent></w:sdt>",
                crate::namespace::W_NS
            )
            .as_bytes(),
            &[],
        )
        .unwrap();
        let mut control = template.clone();
        for _ in 1..257 {
            let mut outer = template.clone();
            outer.content = vec![crate::content_control::SdtContent::ContentControl(control)];
            control = outer;
        }
        let mut body = super::CT_Body::new();
        for _ in 0..513 {
            body.add_paragraph(crate::text::CT_P::new());
        }
        body.content
            .push(super::BodyContent::ContentControl(Box::new(control)));
        let actual = super::admit_word_model(super::WordOwner::Body(&body)).unwrap_err();
        let reference =
            super::admit_word_model_reference(super::WordOwner::Body(&body)).unwrap_err();
        assert_eq!(actual.to_string(), reference.to_string());
    }

    #[test]
    fn model_maxima_keep_independent_limits_sibling_reset_and_early_refusal() {
        use crate::content_control::{CT_Sdt, SdtContent};
        use crate::table::{CT_Row, CT_Tbl, CT_Tc, CellContent};
        fn controls(depth: usize) -> CT_Sdt {
            let source = format!(
                "<w:sdt xmlns:w=\"{}\"><w:sdtContent><w:p/></w:sdtContent></w:sdt>",
                crate::namespace::W_NS
            );
            let template = CT_Sdt::from_body_raw(source.as_bytes(), &[]).unwrap();
            let mut inner = template.clone();
            for _ in 1..depth {
                let mut outer = template.clone();
                outer.content = vec![SdtContent::ContentControl(inner)];
                inner = outer;
            }
            inner
        }
        fn tables(depth: usize) -> CT_Tbl {
            let mut inner = CT_Tbl::new();
            for _ in 1..depth {
                let mut cell = CT_Tc::new();
                cell.content = vec![CellContent::Table(inner)];
                let mut row = CT_Row::new();
                row.cells = vec![cell];
                inner = CT_Tbl::new();
                inner.rows = vec![row];
            }
            inner
        }
        for (weighted, table_depth, accepted) in
            [(256, 32, true), (257, 32, false), (256, 33, false)]
        {
            let body = super::CT_Body {
                content: vec![
                    super::BodyContent::ContentControl(Box::new(controls(weighted))),
                    super::BodyContent::Table(Box::new(tables(table_depth))),
                ],
                ..super::CT_Body::new()
            };
            let reference = super::admit_word_model_reference(super::WordOwner::Body(&body));
            let actual = super::admit_word_model(super::WordOwner::Body(&body));
            assert_eq!(actual.is_ok(), accepted);
            assert_eq!(
                actual.as_ref().map(|_| ()).map_err(ToString::to_string),
                reference.as_ref().map(|_| ()).map_err(ToString::to_string)
            );
            if accepted {
                assert_eq!(super::MODEL_LAST_ROOT_MAXIMA.get(), (256, 32));
            }
        }
        let body = super::CT_Body {
            content: vec![
                super::BodyContent::ContentControl(Box::new(controls(200))),
                super::BodyContent::ContentControl(Box::new(controls(200))),
            ],
            ..super::CT_Body::new()
        };
        super::admit_word_model(super::WordOwner::Body(&body)).unwrap();
        assert_eq!(
            super::MODEL_LAST_ROOT_MAXIMA.get(),
            (200, 0),
            "alternatives are not sibling sums"
        );
        for (legacy, depth, accepted) in [
            (true, 240, true),
            (true, 241, false),
            (false, 240, true),
            (false, 241, false),
        ] {
            let mut anchor = crate::drawing::CT_Anchor::background("", 0, 0);
            let mut shape = crate::drawing::CT_Shape {
                text_body: Some(super::CT_Body::new()),
                ..crate::drawing::CT_Shape::default()
            };
            if legacy {
                shape.text = vec![crate::text::CT_P {
                    content_controls: vec![(0, 0, 0, controls(depth))],
                    ..crate::text::CT_P::default()
                }];
            } else {
                shape.text_body.as_mut().unwrap().content =
                    vec![super::BodyContent::ContentControl(Box::new(controls(
                        depth,
                    )))];
            }
            anchor.shape = Some(shape);
            let reference = super::admit_word_model_reference(super::WordOwner::Anchor(&anchor));
            let actual = super::admit_word_model(super::WordOwner::Anchor(&anchor));
            assert_eq!(
                actual.is_ok(),
                accepted,
                "authoritative and legacy text owners: legacy={legacy}, depth={depth}"
            );
            assert_eq!(
                actual.as_ref().map(|_| ()).map_err(ToString::to_string),
                reference.as_ref().map(|_| ()).map_err(ToString::to_string)
            );
            if accepted {
                assert_eq!(super::MODEL_LAST_ROOT_MAXIMA.get(), (256, 0));
            }
        }
        let mut anchor = crate::drawing::CT_Anchor::background("", 0, 0);
        anchor.shape = Some(crate::drawing::CT_Shape::default());
        super::admit_word_model(super::WordOwner::Anchor(&anchor)).unwrap();
        assert_eq!(super::MODEL_LAST_ROOT_MAXIMA.get(), (0, 0));
        anchor.shape.as_mut().unwrap().text_body = Some(super::CT_Body::new());
        super::admit_word_model(super::WordOwner::Anchor(&anchor)).unwrap();
        assert_eq!(
            super::MODEL_LAST_ROOT_MAXIMA.get(),
            (16, 0),
            "an empty typed text body retains its local charge"
        );
        let deep = controls(2048);
        super::MODEL_SUMMARY_OWNER_ENTRIES.set(0);
        let result = super::admit_word_model(super::WordOwner::Control(&deep));
        let visits = super::MODEL_SUMMARY_OWNER_ENTRIES.get();
        // Dismantle before asserting so an error does not recursively drop an invalid tail.
        let mut pending = vec![deep];
        while let Some(control) = pending.pop() {
            for child in control.content {
                if let SdtContent::ContentControl(child) = child {
                    pending.push(child);
                }
            }
        }
        assert!(result.is_err());
        assert_eq!(
            visits, 256,
            "refuse at the actual entry before enumerating the invalid tail"
        );
    }

    #[test]
    fn fx211_authored_model_refusal_precedes_writer_output() {
        let wrap = |payload: &str| {
            format!(
                "<w:document xmlns:w=\"{}\"><w:body>{payload}</w:body></w:document>",
                crate::namespace::W_NS
            )
        };
        // Build authored ownership iteratively. Fixture construction must not
        // invoke the recursive XML parser before the model guard under test.
        let mut accepted =
            super::CT_Document::from_xml(wrap(&fx211_control_xml(1)).as_bytes()).unwrap();
        let super::BodyContent::ContentControl(template) = &accepted.body.content[0] else {
            panic!("expected template");
        };
        let template = template.as_ref().clone();
        let mut inner = template.clone();
        for _ in 1..256 {
            let mut outer = template.clone();
            outer.content = vec![crate::content_control::SdtContent::ContentControl(inner)];
            inner = outer;
        }
        accepted.body.content = vec![super::BodyContent::ContentControl(Box::new(inner))];
        println!("authored256 constructed iteratively");
        accepted.validate_resource_limits().unwrap();
        println!("authored256 borrowed admission passed");
        let mut outer =
            super::CT_Document::from_xml(wrap(&fx211_control_xml(1)).as_bytes()).unwrap();
        let super::BodyContent::ContentControl(control) = &mut outer.body.content[0] else {
            panic!("expected control");
        };
        let super::BodyContent::ContentControl(inner) = accepted.body.content.remove(0) else {
            panic!("expected inner control");
        };
        control.content = vec![crate::content_control::SdtContent::ContentControl(*inner)];
        assert!(outer.validate_resource_limits().is_err());
        assert!(outer.to_xml().is_err());
        let mut bytes = vec![1, 2, 3];
        assert!(
            outer
                .body
                .to_xml(&mut quick_xml::Writer::new(&mut bytes))
                .is_err()
        );
        assert_eq!(bytes, vec![1, 2, 3]);
    }

    #[test]
    fn fx211_resource_admission_inclusive_control_boundary_and_sibling_reset() {
        let accepted = fx211_control_xml(256);
        let refused = fx211_control_xml(257);
        super::admit_word_xml(accepted.as_bytes(), &["w".into()], None).unwrap();
        assert!(super::admit_word_xml(refused.as_bytes(), &["w".into()], None).is_err());
        let siblings = format!("<w:body>{accepted}{accepted}</w:body>");
        super::admit_word_xml(siblings.as_bytes(), &["w".into()], None).unwrap();
        // A prior admission grants no authority to another independently parsed input.
        assert!(super::admit_word_xml(refused.as_bytes(), &["w".into()], None).is_err());
        super::admit_word_xml(accepted.as_bytes(), &["w".into()], None).unwrap();
    }

    #[test]
    fn fx211_resource_admission_respects_opaque_and_rebound_owner_contexts() {
        let deep = fx211_control_xml(257);
        for opaque in [
            format!(
                "<w:body xmlns:w=\"{}\"><x:opaque xmlns:x=\"urn:producer\">{deep}</x:opaque></w:body>",
                crate::namespace::W_NS
            ),
            format!(
                "<w:body xmlns:w=\"{}\"><w:producerExtension>{deep}</w:producerExtension></w:body>",
                crate::namespace::W_NS
            ),
            format!(
                "<w:body xmlns:w=\"{}\"><w:sdt xmlns:w=\"urn:producer\">{deep}</w:sdt></w:body>",
                crate::namespace::W_NS
            ),
        ] {
            super::admit_word_xml(opaque.as_bytes(), &[], None).unwrap();
        }
        let inline_opaque = format!(
            "<w:p xmlns:w=\"{}\"><w:sdt><w:sdtContent><w:p>{deep}</w:p></w:sdtContent></w:sdt></w:p>",
            crate::namespace::W_NS
        );
        super::admit_word_xml(inline_opaque.as_bytes(), &[], None).unwrap();
        let alias = deep.replace("w:", "q:");
        let qualified = format!(
            "<q:body xmlns:q=\"{}\">{alias}</q:body>",
            crate::namespace::W_NS
        );
        assert!(super::admit_word_xml(qualified.as_bytes(), &[], None).is_err());
        let default = deep.replace("w:", "");
        let qualified = format!(
            "<body xmlns=\"{}\">{default}</body>",
            crate::namespace::W_NS
        );
        assert!(super::admit_word_xml(qualified.as_bytes(), &[], None).is_err());
    }

    #[test]
    fn fx211_inline_shape_is_opaque_but_anchor_body_is_typed() {
        let payload = fx211_control_xml(257);
        let drawing = |owner: &str, payload: &str| {
            format!(
                "<wp:{owner}><wp:extent cx=\"10\" cy=\"20\"/><wp:docPr id=\"1\" name=\"owned\"/><a:graphic><a:graphicData uri=\"urn:producer-route\"><wps:wsp><wps:txbx><w:txbxContent>{payload}</w:txbxContent></wps:txbx></wps:wsp></a:graphicData></a:graphic></wp:{owner}>"
            )
        };
        let wrap = |drawing: &str| {
            format!(
                "<w:document xmlns:w=\"{}\" xmlns:wp=\"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\" xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\" xmlns:wps=\"http://schemas.microsoft.com/office/word/2010/wordprocessingShape\"><w:body><w:p><w:r><w:drawing>{drawing}</w:drawing></w:r></w:p></w:body></w:document>",
                crate::namespace::W_NS
            )
        };
        let opaque = drawing("inline", &payload);
        let source = wrap(&opaque);
        let parsed = super::CT_Document::from_xml(source.as_bytes()).unwrap();
        let saved = parsed.to_xml().unwrap();
        let saved = std::str::from_utf8(&saved).unwrap();
        assert!(
            saved.contains(&opaque),
            "opaque inline source remains exact"
        );
        let reopened = super::CT_Document::from_xml(saved.as_bytes()).unwrap();
        assert_eq!(reopened.to_xml().unwrap(), saved.as_bytes());
        assert!(
            super::CT_Document::from_xml(wrap(&drawing("anchor", &payload)).as_bytes()).is_err()
        );
        // The current native anchor parser types qualified txbxContent even
        // when graphicData's URI is not a known shape URI.
        let accepted = wrap(&drawing(
            "anchor",
            "<w:p><w:r><w:t>typed leaf</w:t></w:r></w:p>",
        ));
        let parsed = super::CT_Document::from_xml(accepted.as_bytes()).unwrap();
        let paragraph = parsed.body.paragraphs().next().unwrap();
        let run = paragraph.runs().into_iter().next().unwrap();
        let crate::text::RunContent::Drawing(drawing) = &run.content[0] else {
            panic!("expected native drawing");
        };
        let body = drawing
            .anchor
            .as_ref()
            .unwrap()
            .shape
            .as_ref()
            .unwrap()
            .text_body
            .as_ref()
            .unwrap();
        assert_eq!(body.paragraphs().next().unwrap().text(), "typed leaf");
    }

    #[test]
    fn fx211_resource_admission_refuses_before_related_story_construction() {
        let deep = fx211_control_xml(257);
        let wrap = |root: &str, payload: &str| {
            format!(
                "<w:{root} xmlns:w=\"{}\">{payload}</w:{root}>",
                crate::namespace::W_NS
            )
        };
        assert!(
            super::CT_Document::from_xml(wrap("document", &wrap("body", &deep)).as_bytes())
                .is_err()
        );
        // These readers preserve direct block controls as opaque XML. Only
        // their actual paragraph descendants enter typed inline construction.
        let header = crate::header_footer::CT_HdrFtr::from_xml(wrap("hdr", &deep).as_bytes())
            .unwrap()
            .to_xml_header()
            .unwrap();
        assert!(std::str::from_utf8(&header).unwrap().contains(&deep));
        let comments = crate::comments::CT_Comments::from_xml(
            wrap(
                "comments",
                &format!("<w:comment w:id=\"1\">{deep}</w:comment>"),
            )
            .as_bytes(),
        )
        .unwrap()
        .to_xml()
        .unwrap();
        assert!(std::str::from_utf8(&comments).unwrap().contains(&deep));
        for (root, entry) in [("footnotes", "footnote"), ("endnotes", "endnote")] {
            let notes = crate::footnotes::CT_Footnotes::from_xml(
                wrap(root, &wrap(entry, &deep)).as_bytes(),
            )
            .unwrap();
            assert_eq!(notes.footnotes.len(), 1);
            assert!(notes.footnotes[0].paragraphs.is_empty());
            let saved = if root == "footnotes" {
                notes.to_xml_footnotes()
            } else {
                notes.to_xml_endnotes()
            }
            .unwrap();
            assert_eq!(
                crate::footnotes::CT_Footnotes::from_xml(&saved).unwrap(),
                notes
            );
        }
        for depth in [2, 257] {
            let inline = wrap(
                "p",
                &format!(
                    "{}<w:r><w:t>typed</w:t></w:r>{}",
                    "<w:sdt><w:sdtContent>".repeat(depth),
                    "</w:sdtContent></w:sdt>".repeat(depth),
                ),
            );
            for root in ["hdr", "ftr"] {
                let result =
                    crate::header_footer::CT_HdrFtr::from_xml(wrap(root, &inline).as_bytes());
                assert_eq!(result.is_err(), depth == 257, "{root} typed depth {depth}");
                if depth == 2 {
                    assert_eq!(result.unwrap().paragraphs[0].accepted_text(), "typed");
                }
            }
            let result = crate::comments::CT_Comments::from_xml(
                wrap(
                    "comments",
                    &format!("<w:comment w:id=\"1\">{inline}</w:comment>"),
                )
                .as_bytes(),
            );
            assert_eq!(result.is_err(), depth == 257, "comment typed depth {depth}");
            if depth == 2 {
                assert_eq!(
                    result.unwrap().comments[0].paragraphs[0].accepted_text(),
                    "typed"
                );
            }
            for (root, entry) in [("footnotes", "footnote"), ("endnotes", "endnote")] {
                let result = crate::footnotes::CT_Footnotes::from_xml(
                    wrap(root, &format!("<w:{entry} w:id=\"1\">{inline}</w:{entry}>")).as_bytes(),
                );
                assert_eq!(result.is_err(), depth == 257, "{root} typed depth {depth}");
                if depth == 2 {
                    assert_eq!(
                        result.unwrap().footnotes[0].paragraphs[0].accepted_text(),
                        "typed"
                    );
                }
            }
        }
        assert!(
            crate::glossary::CT_GlossaryDocument::from_xml(
                wrap(
                    "glossaryDocument",
                    &wrap("docParts", &wrap("docPart", &wrap("docPartBody", &deep)))
                )
                .as_bytes()
            )
            .is_err()
        );
    }

    // F-X018, an unmodelled enumerated value must not fail a document open.

    /// Every enumeration reachable from document parsing, with an unmodelled
    /// but plausibly spec-valid value, plus a sibling property on the same
    /// element that must survive.
    #[test]
    fn a_document_with_an_unmodelled_enumerated_value_still_opens() {
        let cases: [(&str, &str); 8] = [
            (
                "ST_Jc",
                r#"<w:pPr><w:jc w:val="thaiDistribute"/><w:keepNext/></w:pPr>"#,
            ),
            (
                "ST_Underline",
                r#"<w:pPr><w:keepNext/></w:pPr><w:r><w:rPr><w:u w:val="wavyHeavy"/><w:b/></w:rPr><w:t>x</w:t></w:r>"#,
            ),
            (
                "ST_HighlightColor",
                r#"<w:pPr><w:keepNext/></w:pPr><w:r><w:rPr><w:highlight w:val="chartreuse"/><w:b/></w:rPr><w:t>x</w:t></w:r>"#,
            ),
            (
                "ST_Border",
                r#"<w:pPr><w:keepNext/><w:pBdr><w:top w:val="tribal4" w:sz="8"/></w:pBdr></w:pPr>"#,
            ),
            (
                "ST_TabJc",
                r#"<w:pPr><w:keepNext/><w:tabs><w:tab w:val="numbering" w:pos="720"/></w:tabs></w:pPr>"#,
            ),
            (
                "ST_TabLeader",
                r#"<w:pPr><w:keepNext/><w:tabs><w:tab w:val="left" w:pos="720" w:leader="middleDot"/></w:tabs></w:pPr>"#,
            ),
            (
                "ST_SectionType",
                r#"<w:pPr><w:keepNext/><w:sectPr><w:type w:val="oddPage2"/></w:sectPr></w:pPr>"#,
            ),
            (
                "ST_PageOrientation",
                r#"<w:pPr><w:keepNext/><w:sectPr><w:pgSz w:w="12240" w:h="15840" w:orient="sideways"/></w:sectPr></w:pPr>"#,
            ),
        ];

        for (name, body) in cases {
            let xml = format!(
                r#"<?xml version="1.0"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body><w:p>{body}</w:p></w:body></w:document>"#
            );
            let document = CT_Document::from_xml(xml.as_bytes()).unwrap_or_else(|e| {
                panic!("{name}: an unmodelled value must not fail the open, got {e}")
            });

            let BodyContent::Paragraph(paragraph) = &document.body.content[0] else {
                panic!("{name}: expected a paragraph");
            };
            let properties = paragraph
                .properties
                .as_ref()
                .unwrap_or_else(|| panic!("{name}: properties survive"));
            assert_eq!(
                properties.keep_next,
                Some(true),
                "{name}: an unmodelled value must not cost the element its siblings"
            );
        }
    }

    #[test]
    fn an_unmodelled_value_leaves_the_property_unset() {
        // None means "not specified", so the style chain still supplies it.
        // A guessed variant would override a style that does specify one.
        let xml = br#"<?xml version="1.0"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body><w:p><w:pPr><w:jc w:val="thaiDistribute"/></w:pPr></w:p></w:body></w:document>"#;
        let document = CT_Document::from_xml(xml).expect("opens");
        let BodyContent::Paragraph(paragraph) = &document.body.content[0] else {
            panic!("expected a paragraph");
        };
        assert_eq!(paragraph.properties.as_ref().unwrap().jc, None);
    }
