            r#"<w:document xmlns:w="{W_NS}" xmlns:q="{W_NS}" xmlns:x="urn:producer"><w:body><w:sectPr><q:pgNumType x:note="q:start='producer'>still producer" q:start = '3' x:tail="keep"/></w:sectPr></w:body></w:document>"#
