    #[test]
    fn source_section_uses_explicit_word_alias_and_preserves_retained_metadata() {
        let xml = format!(
            r#"<q:sectPr xmlns:q="{W_NS}" xmlns:w="urn:producer" xmlns:r="{R_NS}" w:opaque="keep"><q:headerReference q:type="default" r:id="rId7"/><q:pgSz q:w="12240" q:h="15840"/><x:opaque xmlns:x="urn:producer" x:flag="keep"/></q:sectPr>"#,
            R_NS = crate::namespace::R_NS,
        );
        let section = CT_SectPr::from_xml_fragment_checked(xml.as_bytes()).unwrap();
        let context = [
            ("q", W_NS),
            ("w", "urn:producer"),
            ("r", crate::namespace::R_NS),
        ];
        let mut writer = Writer::new(Vec::new());
        section
            .write_xml_role(
                &mut writer,
                crate::text::XmlWriteRole::Source,
                Some(&context),
            )
            .unwrap();
        let output = writer.into_inner();
        let text = String::from_utf8_lossy(&output);
        assert!(text.starts_with("<q:sectPr"), "{text}");
        assert!(text.ends_with("</q:sectPr>"), "{text}");
        assert!(
            text.contains(r#"<q:pgSz q:w="12240" q:h="15840"/>"#),
            "{text}"
        );
        assert!(
            text.contains(r#"<q:headerReference q:type="default" r:id="rId7"/>"#),
            "{text}"
        );
        assert!(
            text.contains(r#"<x:opaque xmlns:x="urn:producer" x:flag="keep"/>"#),
            "{text}"
        );
        assert!(text.contains(r#"xmlns:w="urn:producer""#), "{text}");
        assert!(text.contains(r#"w:opaque="keep""#), "{text}");
        let facts = section_expanded_facts(&wrapped_fragment(
            &output,
            &format!(
                r#"xmlns:q="{W_NS}" xmlns:w="urn:producer" xmlns:r="{}""#,
                crate::namespace::R_NS
            ),
        ));
        assert!(facts.iter().any(|(uri, attributes)| {
            uri == W_NS
                && attributes.iter().any(|(attribute_uri, local, value)| {
                    attribute_uri == W_NS && local == "w" && value == "12240"
                })
        }));
        assert!(facts.iter().any(|(uri, attributes)| {
            uri == W_NS
                && attributes.iter().any(|(attribute_uri, local, value)| {
                    attribute_uri == crate::namespace::R_NS && local == "id" && value == "rId7"
                })
        }));
    }

    #[test]
    fn source_section_keeps_foreign_relationship_shadow_and_uses_safe_alias() {
        let xml = format!(
            r#"<q:document xmlns:q="{W_NS}" xmlns:r="urn:producer-rel" xmlns="urn:producer-default" xmlns:x="urn:producer"><q:body><q:sectPr q:marker="keep"><q:headerReference xmlns:rel="{R_NS}" q:type="default" rel:id="rId7"/><x:opaque xmlns:x="urn:producer" x:flag="keep"/></q:sectPr></q:body></q:document>"#,
            R_NS = crate::namespace::R_NS,
        );
        let document = CT_Document::from_xml(xml.as_bytes()).unwrap();
        let section = document.body.sect_pr.unwrap();
        let context = [
            ("q", W_NS),
            ("r", "urn:producer-rel"),
            ("rel", crate::namespace::R_NS),
            ("", "urn:producer-default"),
            ("x", "urn:producer"),
        ];
        let mut writer = Writer::new(Vec::new());
        section
            .write_xml_role(
                &mut writer,
                crate::text::XmlWriteRole::Source,
                Some(&context),
            )
            .unwrap();
        let output = writer.into_inner();
        let text = String::from_utf8_lossy(&output);
        assert!(
            text.contains(r#"<w:headerReference w:type="default" rel:id="rId7"/>"#),
            "{text}"
        );
        assert!(!text.contains("r:id=\"rId7\""), "{text}");
        assert!(
            text.contains(r#"<x:opaque xmlns:x="urn:producer" x:flag="keep"/>"#),
            "{text}"
        );
        assert!(text.contains(r#"q:marker="keep""#), "{text}");
        let facts = section_expanded_facts(&wrapped_fragment(
            &output,
            &format!(
                r#"xmlns:q="{W_NS}" xmlns:rel="{}" xmlns:r="urn:producer-rel""#,
                crate::namespace::R_NS
            ),
        ));
        assert!(facts.iter().any(|(uri, attributes)| {
            uri == W_NS
                && attributes.iter().any(|(attribute_uri, local, value)| {
                    attribute_uri == crate::namespace::R_NS && local == "id" && value == "rId7"
                })
        }));
        assert!(!text.contains(r#"xmlns="urn:producer-default""#), "{text}");
    }

