    #[test]
    fn source_section_child_local_shadow_preserves_generated_qualifier_and_opaque_names() {
        let xml = format!(
            r#"<q:sectPr xmlns:q="{W_NS}" xmlns:w="urn:producer" q:marker="keep"><z:paperSrc xmlns:z="{W_NS}" xmlns:q="urn:producer" z:first="1" q:opaque="keep"/><z:pgBorders xmlns:z="{W_NS}" xmlns:q="urn:producer" z:zOrder="front" q:opaque="keep"><z:top z:val="single" z:sz="4" q:keep="edge"/></z:pgBorders><z:lnNumType xmlns:z="{W_NS}" xmlns:q="urn:producer" z:countBy="2" z:start="3" q:opaque="keep"/><z:docGrid xmlns:z="{W_NS}" xmlns:q="urn:producer" z:type="lines" z:linePitch="360" q:opaque="keep"/></q:sectPr>"#
        );
        let section = CT_SectPr::from_xml_fragment_checked(xml.as_bytes()).unwrap();
        let context = [("q", W_NS), ("w", "urn:producer")];
        let mut writer = Writer::new(Vec::new());
        section
            .write_xml_role(
                &mut writer,
                crate::text::XmlWriteRole::Source,
                Some(&context),
            )
            .unwrap();
        let output = writer.into_inner();
        let text = String::from_utf8_lossy(&output);
        for expected in [
            "<z:paperSrc",
            r#"z:first="1""#,
            r#"q:opaque="keep""#,
            "<z:pgBorders",
            "<z:top",
            r#"z:val="single""#,
            r#"z:sz="4""#,
            r#"q:keep="edge""#,
            "<z:lnNumType",
            r#"z:countBy="2""#,
            r#"z:start="3""#,
            "<z:docGrid",
            r#"z:type="lines""#,
            r#"z:linePitch="360""#,
        ] {
            assert!(text.contains(expected), "{expected}: {text}");
        }
        let facts = section_expanded_named_facts(&output);
        for local in ["paperSrc", "pgBorders", "lnNumType", "docGrid"] {
            assert!(
                facts
                    .iter()
                    .any(|(name, uri, _)| name == local && uri == W_NS),
                "{local}: {facts:?}"
            );
        }
        assert!(facts.iter().any(|(name, uri, attributes)| {
            name == "paperSrc"
                && uri == W_NS
                && attributes.iter().any(|(attribute_uri, local, value)| {
                    attribute_uri == W_NS && local == "first" && value == "1"
                })
                && attributes.iter().any(|(attribute_uri, local, value)| {
                    attribute_uri == "urn:producer" && local == "opaque" && value == "keep"
                })
        }));
        assert!(facts.iter().any(|(name, uri, attributes)| {
            name == "top"
                && uri == W_NS
                && attributes.iter().any(|(attribute_uri, local, value)| {
                    attribute_uri == W_NS && local == "val" && value == "single"
                })
                && attributes.iter().any(|(attribute_uri, local, value)| {
                    attribute_uri == "urn:producer" && local == "keep" && value == "edge"
                })
        }));
    }

    #[test]
    fn original_capture_inherited_duplicates_resolve_the_last_exact_binding() {
        let older = format!("urn:{}", "a".repeat(400));
        let drawing = format!(
            "<w:r><w:drawing xmlns:x=\"{older}\"><inline><x:a/></inline><anchor><x:b/></anchor></w:drawing></w:r>"
        );
        let xml = capture_document("", &drawing.repeat(160));
        let prefixes = vec![
            crate::numbering::namespace_binding("x", &older),
            "x".to_owned(),
        ];
        let error = super::admit_word_xml(xml.as_bytes(), &prefixes, None).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("original source capture exceeds admitted source work"),
            "the last inherited binding shadows the older equal prefix: {error}"
        );
        let wp = "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing";
        let shaped = format!(
            "<w:r><w:drawing xmlns:x=\"{older}\"><wp:inline xmlns:wp=\"{wp}\"><wp:docPr id=\"1\"/><x:a/></wp:inline><wp:anchor xmlns:wp=\"{wp}\"><wp:docPr id=\"2\"/><x:b/></wp:anchor></w:drawing></w:r>"
        );
        let parsed = super::CT_Document::from_xml(
            capture_document(&format!("xmlns:wp=\"{wp}\""), &shaped).as_bytes(),
        )
        .expect("the single drawing stays admitted");
        let saved = String::from_utf8(parsed.to_xml().unwrap()).unwrap();
        assert_eq!(
            saved.matches(&format!("xmlns:x=\"{older}\"")).count(),
            2,
            "each physical raw keeps its own drawing declaration: {saved}"
        );
    }

    #[test]
    fn original_capture_nearer_shadow_does_not_borrow_an_older_equal_pair() {
        let older = format!("urn:{}", "a".repeat(400));
        let newer = "urn:b".to_owned();
        let run = format!(
            "<w:r xmlns:x=\"{newer}\"><w:drawing xmlns:x=\"{older}\"><inline><x:a/></inline><anchor><x:b/></anchor></w:drawing></w:r>"
        );
        let xml = capture_document(&format!("xmlns:x=\"{older}\""), &run.repeat(160));
        let error = super::admit_word_xml(xml.as_bytes(), &[], None).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("original source capture exceeds admitted source work"),
            "a nearer run shadow makes the drawing declaration a lost binding: {error}"
        );
        let wp = "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing";
        let shaped = format!(
            "<w:r xmlns:x=\"{newer}\"><w:drawing xmlns:x=\"{older}\"><wp:inline xmlns:wp=\"{wp}\"><wp:docPr id=\"1\"/><x:a/></wp:inline><wp:anchor xmlns:wp=\"{wp}\"><wp:docPr id=\"2\"/><x:b/></wp:anchor></w:drawing></w:r>"
        );
        let parsed = super::CT_Document::from_xml(
            capture_document(&format!("xmlns:x=\"{older}\" xmlns:wp=\"{wp}\""), &shaped).as_bytes(),
        )
        .expect("the single drawing stays admitted");
        let saved = String::from_utf8(parsed.to_xml().unwrap()).unwrap();
        assert_eq!(
            saved.matches(&format!("xmlns:x=\"{older}\"")).count(),
            3,
            "the document and both physical raws keep the lost binding: {saved}"
        );
    }

    #[test]
    fn original_capture_near_prefix_is_a_different_key_and_last_exact_binding_wins() {
        let older = format!("urn:{}", "a".repeat(400));
        let drawing = format!(
            "<w:r><w:drawing xmlns:x=\"{older}\"><inline><x:a/></inline><anchor><x:b/></anchor></w:drawing></w:r>"
        );
        let xml = capture_document("", &drawing.repeat(160));
        let prefixes = vec![
            crate::numbering::namespace_binding("x", &older),
            crate::numbering::namespace_binding("xy", &older),
            "x".to_owned(),
        ];
        let error = super::admit_word_xml(xml.as_bytes(), &prefixes, None).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("original source capture exceeds admitted source work"),
            "the last exact x binding shadows the older x while xy stays a different key: {error}"
        );
        let exact = vec![
            crate::numbering::namespace_binding("x", &older),
            crate::numbering::namespace_binding("xy", &older),
        ];
        super::admit_word_xml(xml.as_bytes(), &exact, None).unwrap_or_else(|error| {
            panic!("a genuinely different longer prefix is not a shadow of x: {error}")
        });
    }

