    #[test]
    fn scoped_template_word_ruby_base_companions_exclude_phonetic_and_late_none() {
        let xml = format!(
            r#"<q:p xmlns:q="{}" xmlns:w="urn:opaque"><q:ruby><q:rt><q:r><q:t>phonetic</q:t></q:r></q:rt><q:rubyBase><q:r><q:t>base&amp;</q:t></q:r><q:r/><q:r><q:t>tail</q:t></q:r></q:rubyBase></q:ruby><q:ruby><q:rt><q:r><q:t>ignored</q:t></q:r></q:rt><q:rubyBase><q:r><q:t>unselected</q:t></q:r><q:bad/></q:rubyBase></q:ruby></q:p>"#,
            crate::namespace::W_NS
        );
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        let parsed = operation.source_paragraph(&source).unwrap();
        let expected = crate::placeholder::replaceable_texts(&parsed);
        assert_eq!(expected, ["base&tail"]);
        assert_eq!(
            operation.template_replaceable_texts(&source).unwrap(),
            expected
        );
        assert_eq!(
            operation.template_copy_work.allowance,
            9 * (crate::namespace::W_NS.len() + 64)
        );
        assert_eq!(operation.template_copy_work.word_inputs.len(), 2);
        for (encoded, decoded) in [("base&amp;", 5), ("tail", 4)] {
            let at = xml.find(encoded).unwrap();
            let origin = crate::text::TemplateWordOrigin::Raw {
                start: xml.as_ptr() as usize + at,
                end: xml.as_ptr() as usize + at + encoded.len(),
            };
            assert_eq!(
                operation.template_copy_work.word_inputs.get(&origin),
                Some(&std::collections::BTreeMap::from([(0, decoded)]))
            );
        }
        assert_eq!(
            operation.template_replaceable_texts(&source).unwrap(),
            expected
        );
        assert_eq!(
            operation.template_copy_work.allowance,
            9 * (crate::namespace::W_NS.len() + 64)
        );
        assert_eq!(source.as_bytes(), xml.as_bytes());
    }

    #[test]
    fn scoped_template_word_hyperlink_runs_use_actual_capture_companions() {
        let xml = format!(
            r#"<q:p xmlns:q="{}" xmlns:w="urn:opaque"><q:r><q:t>before</q:t></q:r><q:hyperlink q:anchor="target"><q:r><q:t>link&amp;</q:t></q:r><q:r><q:t>tail</q:t></q:r><w:opaque><q:r><q:t>ignored</q:t></q:r></w:opaque></q:hyperlink><q:r><q:t>after</q:t></q:r></q:p>"#,
            crate::namespace::W_NS
        );
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        let parsed = operation.source_paragraph(&source).unwrap();
        let expected = crate::placeholder::replaceable_texts(&parsed);
        let copied_before = operation.template_copy_work.copied;
        let actual = operation.template_replaceable_texts(&source).unwrap();
        assert_eq!(actual, expected);
        assert_eq!(actual, ["beforelink&tailafter"]);
        assert_eq!(
            operation.template_copy_work.allowance,
            20 * (crate::namespace::W_NS.len() + 64)
        );
        assert_eq!(operation.template_copy_work.word_inputs.len(), 4);
        for (encoded, decoded) in [("before", 6), ("link&amp;", 5), ("tail", 4), ("after", 5)] {
            let at = xml.find(encoded).unwrap();
            let origin = crate::text::TemplateWordOrigin::Raw {
                start: xml.as_ptr() as usize + at,
                end: xml.as_ptr() as usize + at + encoded.len(),
            };
            assert_eq!(
                operation.template_copy_work.word_inputs.get(&origin),
                Some(&std::collections::BTreeMap::from([(0, decoded)]))
            );
        }
        assert!(operation.template_copy_work.copied > copied_before);
        assert_eq!(
            operation.template_replaceable_texts(&source).unwrap(),
            actual
        );
        assert_eq!(
            operation.template_copy_work.allowance,
            20 * (crate::namespace::W_NS.len() + 64)
        );
        assert_eq!(source.as_bytes(), xml.as_bytes());
    }

    #[test]
    fn scoped_template_word_mixed_field_segments_forward_actual_clones_only() {
        use crate::text::{CT_P, CT_R, CT_Text, Field, RunContent, TemplateWordOrigin};
        let left = CT_Text::new("left&");
        let right = CT_Text::new("right");
        let field = Field::new("CUSTOM", "C");
        let data = serde_json::Value::Null;
        let mut operation = super::ScopedWordOperation::with_template_word_inputs(
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![&left, &right],
            vec![&field],
            Vec::new(),
            &data,
        )
        .unwrap();
        let mut run = CT_R::new("");
        run.content = vec![
            RunContent::Text(left.clone()),
            RunContent::Field(field.clone()),
            RunContent::Text(right.clone()),
            RunContent::Text(CT_Text::new("left&")),
        ];
        let mut paragraph = CT_P::new();
        paragraph.runs.push(run);
        let item = super::BodyContent::Paragraph(Box::new(paragraph));
        let super::BodyContent::Paragraph(paragraph) = &item else {
            unreachable!()
        };
        let [
            RunContent::Text(current_left),
            RunContent::Field(current_field),
            RunContent::Text(current_right),
            _,
        ] = paragraph.runs[0].content.as_slice()
        else {
            unreachable!()
        };
        let source = operation
            .source_model_body_item(
                &super::CT_Document::new(),
                &item,
                &[],
                &[(current_left, &left), (current_right, &right)],
                &[(current_field, &field)],
                &[],
            )
            .unwrap();
        assert_eq!(source.word_events.len(), 3);
        assert_eq!(
            source.word_events[0].origin,
            TemplateWordOrigin::Text(std::ptr::from_ref(&left) as usize)
        );
        assert_eq!(
            source.word_events[1].origin,
            TemplateWordOrigin::CachedResult(std::ptr::from_ref(&field) as usize)
        );
        assert_eq!(
            source.word_events[2].origin,
            TemplateWordOrigin::Text(std::ptr::from_ref(&right) as usize)
        );
        for (event, expected) in
            source
                .word_events
                .iter()
                .zip([b"left&amp;".as_slice(), b"C", b"right"])
        {
            assert_eq!(&source.bytes[event.encoded.clone()], expected);
        }
        assert_eq!(operation.template_copy_work.allowance, 0);
    }

    #[test]
    fn scoped_publication_drawing_body_keeps_table_control_and_following_owner_maps() {
        let inner = r#"<w:fldSimple w:instr="INNER"><w:r><w:t>cache</w:t></w:r></w:fldSimple>"#;
        let following =
            r#"<w:fldSimple w:instr="FOLLOWING"><w:r><w:t>after</w:t></w:r></w:fldSimple>"#;
        for body in [
            format!("<w:tbl><w:tr><w:tc><w:p>{inner}</w:p></w:tc></w:tr></w:tbl>"),
            format!("<w:sdt><w:sdtContent><w:p>{inner}</w:p></w:sdtContent></w:sdt>"),
            format!("<w:p><w:sdt><w:sdtContent>{inner}</w:sdtContent></w:sdt></w:p>"),
        ] {
            let xml = format!(
                r#"<w:p xmlns:w="{}" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"><w:r><w:drawing><wp:anchor><wp:docPr id="1"/><w:txbxContent>{body}</w:txbxContent></wp:anchor></w:drawing></w:r><w:sdt><w:sdtContent>{following}</w:sdtContent></w:sdt></w:p>"#,
                crate::namespace::W_NS
            );
            let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let model = operation
                .parse_source_paragraph(&source, None, None, None)
                .unwrap();
            assert_eq!(model.content_controls.len(), 1);
            let expected = [inner, following]
                .into_iter()
                .map(|field| {
                    let start = xml.find(field).unwrap();
                    start..start + field.len()
                })
                .collect::<Vec<_>>();
            assert_eq!(source.publication.lock().unwrap().fields, expected);
            assert_eq!(
                operation.field_work.original_input_state_for_test(),
                (0, 0, 0)
            );
        }
    }

    #[test]
    fn scoped_publication_drawing_maps_follow_actual_run_families_and_namespace_context() {
        for default_word in [false, true] {
            let prefix = if default_word { "" } else { "q:" };
            let field = format!(
                r#"<{prefix}fldSimple q:instr="CUSTOM"><{prefix}r><{prefix}t>cache</{prefix}t></{prefix}r></{prefix}fldSimple>"#
            );
            let drawing = format!(
                r#"<{prefix}drawing><wp:anchor><wp:docPr id="1"/><{prefix}txbxContent><{prefix}p>{field}</{prefix}p></{prefix}txbxContent></wp:anchor></{prefix}drawing>"#
            );
            let run = format!("<{prefix}r>{drawing}</{prefix}r>");
            let placements = [
                run.clone(),
                format!("<{prefix}hyperlink>{run}</{prefix}hyperlink>"),
                format!(
                    "<{prefix}sdt><{prefix}sdtContent>{run}</{prefix}sdtContent></{prefix}sdt>"
                ),
                format!(r#"<{prefix}ins q:id="1" q:author="reviewer">{run}</{prefix}ins>"#),
                format!(r#"<{prefix}fldSimple q:instr="OUTER">{run}</{prefix}fldSimple>"#),
            ];
            for body in placements {
                let default = if default_word {
                    format!(r#" xmlns="{}""#, crate::namespace::W_NS)
                } else {
                    String::new()
                };
                let xml = format!(
                    r#"<{prefix}p xmlns:q="{}" xmlns:w="urn:foreign" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"{default}>{body}<w:opaque/></{prefix}p>"#,
                    crate::namespace::W_NS
                );
                let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
                let source = operation.source(0..xml.len(), &Default::default()).unwrap();
                let model = operation
                    .parse_source_paragraph(&source, None, None, None)
                    .unwrap();
                assert!(
                    !model.runs.is_empty()
                        || !model.content_controls.is_empty()
                        || !model.revisions.is_empty()
                );
                let at = xml.find(&field).unwrap();
                assert!(
                    source
                        .publication
                        .lock()
                        .unwrap()
                        .fields
                        .iter()
                        .any(|owned| owned.start <= at && at + field.len() <= owned.end),
                    "actual mapped {prefix} run family"
                );
                let opaque = xml.find("<w:opaque/>").unwrap();
                assert!(
                    source
                        .publication
                        .lock()
                        .unwrap()
                        .fields
                        .iter()
                        .all(|owned| owned.end <= opaque || owned.start >= opaque + 11)
                );
                assert_eq!(source.bytes, xml.as_bytes());
                assert_eq!(operation.template_copy_work.allowance, 0);
            }
        }
    }

    #[test]
    fn scoped_publication_drawing_capture_preserves_initial_and_derived_inputs() {
        fn physical_fields(paragraph: &crate::text::CT_P) -> Vec<&crate::text::Field> {
            let mut fields = Vec::new();
            let mut pending = vec![super::WordOwner::Paragraph(paragraph)];
            while let Some(owner) = pending.pop() {
                if let super::WordOwner::Field(field) = owner {
                    fields.push(field);
                }
                pending.extend(owner.resource_children());
            }
            fields
        }
        let field = r#"<w:fldSimple w:instr="CUSTOM"><w:r><w:t>cache</w:t></w:r></w:fldSimple>"#;
        let xml = format!(
            r#"<w:p xmlns:w="{}" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"><w:r><w:drawing><wp:anchor><wp:docPr id="1"/><w:txbxContent><w:p>{field}</w:p></w:txbxContent></wp:anchor></w:drawing></w:r></w:p>"#,
            crate::namespace::W_NS
        );
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let original = operation.source(0..xml.len(), &Default::default()).unwrap();
        let derived = operation
            .compose_sources(&[(Some(&original), 0..original.bytes.len(), &[])])
            .unwrap();
        let derived_model = operation
            .parse_source_paragraph(&derived, None, None, None)
            .unwrap();
        let derived_fields = physical_fields(&derived_model);
        assert_eq!(derived_fields.len(), 1);
        assert!(
            operation
                .field_origins
                .lock()
                .unwrap()
                .original_identity_for_test(derived_fields[0])
                .is_none()
        );
        let original_model = operation
            .parse_source_paragraph(&original, None, None, None)
            .unwrap();
        let original_fields = physical_fields(&original_model);
        assert_eq!(original_fields.len(), 1);
        assert!(
            operation
                .field_origins
                .lock()
                .unwrap()
                .original_identity_for_test(original_fields[0])
                .is_some()
        );
        let start = xml.find(field).unwrap();
        for source in [&original, &derived] {
            assert_eq!(
                source.publication.lock().unwrap().fields,
                vec![start..start + field.len()]
            );
        }
        assert_eq!(
            operation.field_work.original_input_state_for_test(),
            (0, 0, 0)
        );
        assert_eq!(operation.template_copy_work.allowance, 0);
    }

    #[test]
    fn scoped_publication_drawing_commits_only_final_successful_retained_body() {
        let left = r#"<w:fldSimple w:instr="ALPHA"><w:r><w:t>cache</w:t></w:r></w:fldSimple>"#;
        let right = r#"<w:fldSimple w:instr="BRAVO"><w:r><w:t>cache</w:t></w:r></w:fldSimple>"#;
        let anchor = |field: &str, id: &str| {
            format!(
                r#"<wp:anchor><w:txbxContent><w:p>{field}</w:p></w:txbxContent><wp:docPr id="{id}"/></wp:anchor>"#
            )
        };
        for invalid in [false, true] {
            let xml = format!(
                r#"<w:p xmlns:w="{}" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"><w:r><w:drawing>{}{}</w:drawing></w:r></w:p>"#,
                crate::namespace::W_NS,
                anchor(left, "1"),
                anchor(right, if invalid { "bad" } else { "2" })
            );
            let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let result = operation.parse_source_paragraph(&source, None, None, None);
            if invalid {
                assert!(result.is_err());
                assert!(
                    source.publication.lock().unwrap().fields.is_empty(),
                    "late metadata error cannot publish either candidate"
                );
            } else {
                let model = result.unwrap();
                assert_eq!(model.runs.len(), 1);
                let start = xml.find(right).unwrap();
                assert_eq!(
                    source.publication.lock().unwrap().fields,
                    vec![start..start + right.len()],
                    "overwritten anchor body is not delivered"
                );
            }
            assert_eq!(
                operation.field_work.original_input_state_for_test(),
                (0, 0, 0)
            );
        }
    }

    #[test]
    fn scoped_publication_commits_physical_revision_control_owners() {
        for ordered in [false, true] {
            let cache = if ordered {
                "<w:hyperlink><w:r><w:t>cache</w:t></w:r></w:hyperlink>"
            } else {
                "<w:r><w:t>cache</w:t></w:r>"
            };
            let field = format!(r#"<w:fldSimple w:instr="CUSTOM">{cache}</w:fldSimple>"#);
            for kind in ["ins", "del", "moveFrom", "moveTo"] {
                let xml = format!(
                    r#"<w:p xmlns:w="{}"><w:{kind} w:id="1" w:author="reviewer"><w:sdt><w:sdtContent>{field}</w:sdtContent></w:sdt></w:{kind}></w:p>"#,
                    crate::namespace::W_NS
                );
                let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
                let source = operation.source(0..xml.len(), &Default::default()).unwrap();
                let paragraph = operation
                    .parse_source_paragraph(&source, None, None, None)
                    .unwrap();
                assert_eq!(paragraph.revisions.len(), 1, "actual {kind} reader");
                let actual = source.publication.lock().unwrap().fields.clone();
                if ordered || matches!(kind, "ins" | "moveTo") {
                    let start = xml.find(&field).unwrap();
                    assert_eq!(
                        actual,
                        vec![start..start + field.len()],
                        "physical {kind} owner, independent of accepted-view text"
                    );
                } else {
                    assert!(
                        actual.is_empty(),
                        "ordinary deleted wrapper does not construct this raw child"
                    );
                }
                assert_eq!(operation.template_copy_work.allowance, 0);
            }
        }
    }

    #[test]
    fn scoped_publication_model_writer_uses_actual_field_and_retained_source_producers() {
        let begin = r#"<w:fldChar w:fldCharType="begin"/>"#;
        let end = r#"<w:fldChar w:fldCharType="end"/>"#;
        for body in [
            r#"<w:fldSimple w:instr="CUSTOM"><w:r><w:t>cache</w:t></w:r></w:fldSimple>"#.to_owned(),
            format!(
                "<w:r><w:t>outside</w:t>{begin}<w:instrText>CUSTOM</w:instrText><w:fldChar w:fldCharType=\"separate\"/><w:t>cache</w:t>{end}<w:t>after</w:t></w:r>"
            ),
            format!(
                "<w:r><w:t>outside</w:t><w:instrText>orphan</w:instrText>{begin}<w:instrText>CUSTOM</w:instrText><w:fldChar w:fldCharType=\"separate\"/><w:t>cache</w:t>{end}<w:t>after</w:t></w:r>"
            ),
        ] {
            let xml = format!(r#"<w:p xmlns:w="{}">{body}</w:p>"#, crate::namespace::W_NS);
            let paragraph = crate::text::CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
            let data = serde_json::Value::Null;
            let mut operation = super::ScopedWordOperation::with_template_inputs(
                Vec::new(),
                vec![&paragraph],
                &data,
            )
            .unwrap();
            let (_, source) = operation.source_model_paragraph(&paragraph).unwrap();
            let coverage = source.publication.lock().unwrap();
            assert!(!coverage.fields.is_empty());
            let selected = coverage
                .fields
                .iter()
                .flat_map(|range| &source.bytes[range.clone()])
                .copied()
                .collect::<Vec<_>>();
            for unowned in [b"outside".as_slice(), b"after", b"orphan"] {
                assert!(
                    !selected
                        .windows(unowned.len())
                        .any(|window| window == unowned)
                );
            }
            assert!(selected.windows(5).any(|window| window == b"cache"));
            assert_eq!(operation.template_copy_work.allowance, 0);
        }
        let mut paragraph = crate::text::CT_P::new();
        let mut run = crate::text::CT_R::new("");
        run.content = vec![crate::text::RunContent::Field(crate::text::Field::new(
            "CUSTOM", "cache",
        ))];
        paragraph.runs.push(run);
        let data = serde_json::Value::Null;
        let mut operation =
            super::ScopedWordOperation::with_template_inputs(Vec::new(), vec![&paragraph], &data)
                .unwrap();
        let (_, source) = operation.source_model_paragraph(&paragraph).unwrap();
        assert!(!source.publication.lock().unwrap().fields.is_empty());
    }

    #[test]
    fn scoped_publication_wrapper_commits_only_successful_actual_factory() {
        let field = r#"<w:fldSimple w:instr="CUSTOM"><w:r><w:t>cache</w:t></w:r></w:fldSimple>"#;
        let prefixes = vec!["w".to_owned()];
        for (raw, expected) in [
            (format!("<w:smartTag>{field}</w:smartTag>"), true),
            (format!("<w:customXml>{field}</w:customXml>"), true),
            (format!("<w:other>{field}</w:other>"), false),
            (
                format!("<w:smartTag>{field}<w:r></w:bad></w:smartTag>"),
                false,
            ),
        ] {
            let coverage = std::sync::Arc::new(std::sync::Mutex::new(
                super::WordPublicationCoverage::default(),
            ));
            // Actual current coordinates need not begin at the wrapper boundary.
            let offset = 17;
            let map = super::WordSourceMap::generated(offset + raw.len())
                .with_publication_collector(&coverage)
                .slice(offset..offset + raw.len())
                .unwrap();
            let input = super::WordFieldInput::produced(
                map,
                std::sync::Arc::new(std::sync::Mutex::new(
                    crate::text::FieldOriginRegistry::default(),
                )),
            );
            let result = crate::text::run_wrapper_paragraph_in(
                raw.as_bytes(),
                &prefixes,
                Some(&input),
                None,
                None,
                None,
            )
            .unwrap();
            assert_eq!(result.is_some(), expected);
            let actual = coverage.lock().unwrap().fields.clone();
            if expected {
                let start = offset + raw.find(field).unwrap();
                assert_eq!(actual, vec![start..start + field.len()]);
            } else {
                assert!(
                    actual.is_empty(),
                    "failed factory candidates are not delivered"
                );
            }
            assert!(input.resource_failure().is_none());
        }
    }

    #[test]
    fn scoped_publication_nested_wrapper_uses_actual_captured_map_and_control_owner() {
        let field = r#"<w:fldSimple w:instr="CUSTOM"><w:r><w:t>cache</w:t></w:r></w:fldSimple>"#;
        let raw =
            format!("<w:smartTag><w:sdt><w:sdtContent>{field}</w:sdtContent></w:sdt></w:smartTag>");
        let xml = format!(r#"<w:p xmlns:w="{}">{raw}</w:p>"#, crate::namespace::W_NS);
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        let mut extras = Vec::new();
        let paragraph = operation
            .parse_source_paragraph(&source, Some(&mut extras), None, None)
            .unwrap();
        assert!(source.publication.lock().unwrap().fields.is_empty());
        let (index, (_, captured)) = paragraph
            .extra_xml
            .iter()
            .enumerate()
            .find(|(_, (_, bytes))| bytes.starts_with(b"<w:smartTag"))
            .unwrap();
        let input = super::WordFieldInput::produced(
            extras[index].as_ref().unwrap().as_ref().clone(),
            std::sync::Arc::clone(&operation.field_origins),
        );
        let delivered = crate::text::run_wrapper_paragraph_in(
            captured,
            &["w".into()],
            Some(&input),
            Some(&mut operation.field_work),
            None,
            None,
        )
        .unwrap()
        .unwrap();
        assert_eq!(delivered.writer_field_roots().len(), 1);
        let start = xml.find(field).unwrap();
        assert_eq!(
            source.publication.lock().unwrap().fields,
            vec![start..start + field.len()]
        );
        assert_eq!(operation.template_copy_work.allowance, 0);
    }

    #[test]
    fn scoped_publication_shared_field_record_keeps_distinct_current_occurrences() {
        let field = r#"<w:fldSimple w:instr="CUSTOM"><w:r><w:t>cache</w:t></w:r></w:fldSimple>"#;
        let raw = format!("<w:smartTag>{field}</w:smartTag>");
        let registry = std::sync::Arc::new(std::sync::Mutex::new(
            crate::text::FieldOriginRegistry::default(),
        ));
        let left = std::sync::Arc::new(std::sync::Mutex::new(
            super::WordPublicationCoverage::default(),
        ));
        let right = std::sync::Arc::new(std::sync::Mutex::new(
            super::WordPublicationCoverage::default(),
        ));
        let input = super::WordFieldInput::produced(
            super::WordSourceMap::generated(raw.len()).with_publication_collector(&left),
            std::sync::Arc::clone(&registry),
        );
        let paragraph = crate::text::run_wrapper_paragraph_in(
            raw.as_bytes(),
            &["w".into()],
            Some(&input),
            None,
            None,
            None,
        )
        .unwrap()
        .unwrap();
        let actual = paragraph.writer_field_roots()[0];
        let offset = 29;
        // This is an actual shared Field clone, not a reparsed equal value.
        let cloned = paragraph.clone();
        let current = super::WordSourceMap::generated(offset + field.len())
            .with_publication_collector(&right)
            .slice(offset..offset + field.len())
            .unwrap();
        registry
            .lock()
            .unwrap()
            .register_initial(actual, current.clone(), false)
            .unwrap();
        // The second real delivered owner joins only the second input occurrence.
        left.lock().unwrap().fields.clear();
        registry
            .lock()
            .unwrap()
            .commit_publication_owner(WordOwner::Paragraph(&cloned), &current);
        assert!(left.lock().unwrap().fields.is_empty());
        assert_eq!(
            right.lock().unwrap().fields,
            vec![offset..offset + field.len()]
        );
        // A separate delivery against the original occurrence still resolves it.
        registry
            .lock()
            .unwrap()
            .commit_publication_owner(WordOwner::Paragraph(&paragraph), input.projection_parts().0);
        let at = raw.find(field).unwrap();
        assert_eq!(left.lock().unwrap().fields, vec![at..at + field.len()]);
    }

