    #[test]
    fn scoped_publication_cutout_cache_role_survives_drop_framing_and_fresh_parse() {
        let word = crate::namespace::W_NS;
        let inner = "<w:p><w:r><w:t>inside</w:t></w:r></w:p>";
        let xml = format!(
            r#"<w:p xmlns:w="{word}"><w:fldSimple w:instr="CUSTOM">{inner}</w:fldSimple></w:p>"#
        );
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        let paragraph = operation
            .parse_source_paragraph(&source, None, None, None)
            .unwrap();
        assert_eq!(
            operation.field_work.original_input_state_for_test().0,
            0,
            "classification alone grants no input"
        );
        operation
            .field_work
            .register_original_fields(paragraph.writer_field_roots())
            .unwrap();
        let funded = operation.field_work.original_input_state_for_test();
        assert_eq!(
            funded.1, 1,
            "select the actual original Field before copying its cache"
        );
        assert!(funded.0 > 0);
        drop(paragraph);
        let start = xml.find(inner).unwrap();
        let weak = std::sync::Arc::downgrade(&source.publication);
        let copied = operation
            .compose_sources(&[(Some(&source), start..start + inner.len(), &[])])
            .unwrap();
        drop(source);
        assert!(weak.upgrade().is_none());
        assert_eq!(
            copied.publication.lock().unwrap().fields,
            vec![0..inner.len()]
        );
        let copied = operation
            .close_source_namespaces(
                copied,
                &std::collections::BTreeMap::from([("w".into(), word.into())]),
            )
            .unwrap();
        let before = copied.publication.lock().unwrap().fields.clone();
        assert_eq!(
            before.iter().map(|range| range.len()).sum::<usize>(),
            inner.len()
        );
        assert!(copied.bytes.len() > inner.len());
        let paragraph = operation
            .parse_source_paragraph(&copied, None, None, None)
            .unwrap();
        assert!(paragraph.writer_field_roots().is_empty());
        assert_eq!(copied.publication.lock().unwrap().fields, before);
        assert_eq!(operation.field_work.original_input_state_for_test(), funded);
        let twice = operation
            .compose_sources(&[
                (Some(&copied), 0..copied.bytes.len(), &[]),
                (Some(&copied), 0..copied.bytes.len(), &[]),
            ])
            .unwrap();
        let fields = twice.publication.lock().unwrap().fields.clone();
        assert_eq!(
            fields.iter().map(|range| range.len()).sum::<usize>(),
            inner.len() * 2
        );
        assert_eq!(fields[before.len()].start, copied.bytes.len());
        drop(copied);
        assert_eq!(twice.publication.lock().unwrap().fields, fields);
    }

    #[test]
    fn scoped_publication_transport_outlives_consumed_source_without_retained_buffers() {
        let word = crate::namespace::W_NS;
        let field = r#"<w:fldSimple w:instr="CUSTOM"><w:r><w:t>cache</w:t></w:r></w:fldSimple>"#;
        let xml = format!(r#"<w:p xmlns:w="{word}">{field}</w:p>"#);
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        let paragraph = operation
            .parse_source_paragraph(&source, None, None, None)
            .unwrap();
        assert_eq!(
            operation.field_work.original_input_state_for_test().0,
            0,
            "classification alone grants no input"
        );
        operation
            .field_work
            .register_original_fields(paragraph.writer_field_roots())
            .unwrap();
        let funded = operation.field_work.original_input_state_for_test();
        assert_eq!(funded.1, 1);
        assert!(funded.0 > 0);
        let expected = source.publication.lock().unwrap().fields.clone();
        let weak_a = std::sync::Arc::downgrade(&source.publication);
        let next = operation
            .compose_sources(&[(Some(&source), 0..source.bytes.len(), &[])])
            .unwrap();
        drop(paragraph);
        drop(source);
        assert!(weak_a.upgrade().is_none());
        assert_eq!(next.publication.lock().unwrap().fields, expected);
        let weak_b = std::sync::Arc::downgrade(&next.publication);
        let next = operation
            .close_source_namespaces(next, &Default::default())
            .unwrap();
        assert!(weak_b.upgrade().is_none());
        assert_eq!(next.publication.lock().unwrap().fields, expected);
        assert_eq!(next.bytes, xml.as_bytes());
        operation
            .parse_source_paragraph(&next, None, None, None)
            .unwrap();
        assert_eq!(next.publication.lock().unwrap().fields, expected);
        assert_eq!(operation.field_work.original_input_state_for_test(), funded);
    }

