    #[test]
    fn scoped_format_paragraph_callback_and_dependencies_require_actual_selected_field() {
        let word = crate::namespace::W_NS;
        let field = format!(
            r#"<w:p xmlns:w="{word}"><w:fldSimple w:instr="CUSTOM"><w:r><w:t>TOKEN</w:t></w:r></w:fldSimple></w:p>"#
        );
        let ordinary = format!(r#"<w:p xmlns:w="{word}"><w:r><w:t>TOKEN</w:t></w:r></w:p>"#);
        let data = serde_json::Value::String("input".into());
        let foreign = serde_json::Value::String("input".into());
        for xml in [&field, &ordinary] {
            let event = std::cell::Cell::new(false);
            let mut operation = super::ScopedWordOperation::with_template_inputs(
                vec![("main", xml.as_bytes())],
                Vec::new(),
                &data,
            )
            .unwrap();
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let before = operation.field_work.original_input_state_for_test();
            assert!(
                operation
                    .format_paragraph(
                        source,
                        Vec::new(),
                        &[(0, 0..5, "x", None, None, &[&foreign])]
                    )
                    .is_err()
            );
            assert_eq!(operation.field_work.original_input_state_for_test(), before);
            assert!(!event.get());
            for deps in [&[&foreign][..], &[&data][..]] {
                let source = operation.source(0..xml.len(), &Default::default()).unwrap();
                let before = operation.field_work.original_input_state_for_test();
                assert!(
                    operation
                        .format_paragraph(
                            source,
                            Vec::new(),
                            &[(0, 0..5, "x", None, Some(&event), deps)]
                        )
                        .is_err()
                );
                assert!(!event.get());
                assert_eq!(operation.field_work.original_input_state_for_test(), before);
            }
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let before = operation.field_work.original_input_state_for_test();
            assert!(
                operation
                    .format_paragraph(
                        source,
                        Vec::new(),
                        &[
                            (0, 0..4, "x", None, Some(&event), &[]),
                            (0, 2..5, "y", None, Some(&event), &[])
                        ]
                    )
                    .is_err()
            );
            assert!(!event.get());
            assert_eq!(operation.field_work.original_input_state_for_test(), before);
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            operation
                .format_paragraph(
                    source,
                    Vec::new(),
                    &[(0, 0..5, "x", None, Some(&event), &[])],
                )
                .unwrap();
            assert_eq!(event.get(), xml == &field);
            assert_eq!(operation.template_copy_work.allowance, 0);
            assert_eq!(xml.as_bytes(), operation.original_parts[0]);
        }
    }

    #[test]
    fn scoped_format_paragraph_children_preserve_ranges_namespaces_and_atomic_validation() {
        let word = crate::namespace::W_NS;
        let data = serde_json::Value::Null;
        for (prefix, declarations) in [
            ("w:", format!(r#"xmlns:w="{word}""#)),
            ("q:", format!(r#"xmlns:q="{word}" xmlns:w="urn:opaque""#)),
            ("", format!(r#"xmlns="{word}" xmlns:w="urn:opaque""#)),
            ("q:", format!(r#"xmlns:q="{word}""#)),
            ("", format!(r#"xmlns="{word}""#)),
        ] {
            let run = format!("<{prefix}r><{prefix}t>TOKEN</{prefix}t></{prefix}r>");
            let xml = format!("<{prefix}p {declarations}>{run}</{prefix}p>");
            let mut operation = super::ScopedWordOperation::with_template_inputs(
                vec![("main", xml.as_bytes())],
                Vec::new(),
                &data,
            )
            .unwrap();
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let child = operation.source(0..xml.len(), &Default::default()).unwrap();
            let before = operation.field_work.original_input_state_for_test();
            assert!(
                operation
                    .format_paragraph(source, vec![(1..xml.len() + 1, child)], &[])
                    .is_err()
            );
            assert_eq!(operation.field_work.original_input_state_for_test(), before);
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let at = xml.find(&run).unwrap();
            let mut scope = std::collections::BTreeMap::new();
            if prefix.is_empty() {
                scope.insert(String::new(), word.to_owned());
            } else {
                scope.insert(prefix.trim_end_matches(':').to_owned(), word.to_owned());
            }
            if declarations.contains("urn:opaque") {
                scope.insert("w".to_owned(), "urn:opaque".to_owned());
            }
            let child = operation.source(at..at + run.len(), &scope).unwrap();
            let result = operation
                .format_paragraph(
                    source,
                    vec![(at..at + run.len(), child)],
                    &[(0, 0..5, "literal", None, None, &[])],
                )
                .unwrap();
            let parsed = operation.source_paragraph(&result).unwrap();
            assert_eq!(crate::placeholder::replaceable_texts(&parsed), ["literal"]);
            assert_eq!(operation.field_work.original_input_state_for_test().0, 0);
            assert!(!result.source_map.entirely_original());
            assert_eq!(operation.template_copy_work.allowance, 0);
        }
    }

    #[test]
    fn scoped_template_word_nested_ordered_request_requires_actual_reparse_facts() {
        use crate::text::{CT_P, CT_R, RunContent};
        let word = crate::namespace::W_NS;
        let data = serde_json::Value::Null;
        for body in [
            r#"<w:ins w:id="1" w:author="Ada"><w:r><w:t>old</w:t></w:r></w:ins>"#,
            r#"<w:sdt><w:sdtContent><w:r><w:t>old</w:t></w:r></w:sdtContent></w:sdt>"#,
        ] {
            let xml = format!(
                r#"<w:p xmlns:w="{word}"><w:fldSimple w:instr="CUSTOM">{body}</w:fldSimple></w:p>"#
            );
            let parsed = CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
            let mut frozen = parsed
                .runs
                .into_iter()
                .flat_map(|run| run.content)
                .find_map(|content| {
                    if let RunContent::Field(field) = content {
                        Some(field)
                    } else {
                        None
                    }
                })
                .unwrap();
            frozen.cached_result = "A&\tB".into();
            let mut operation = super::ScopedWordOperation::with_template_word_inputs(
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                vec![&frozen],
                Vec::new(),
                &data,
            )
            .unwrap();
            let prepared = operation
                .prepare_template_field(&frozen, &frozen, true)
                .unwrap();
            let mut run = CT_R::new("");
            run.content = vec![RunContent::Field(prepared)];
            let mut paragraph = CT_P::new();
            paragraph.runs.push(run);
            let item = super::BodyContent::Paragraph(Box::new(paragraph));
            let super::BodyContent::Paragraph(paragraph) = &item else {
                unreachable!()
            };
            let RunContent::Field(current) = &paragraph.runs[0].content[0] else {
                unreachable!()
            };
            let frame = super::CT_Document::new();
            let expected = frame
                .body_item_xml_with_ancestor_declarations(&item, &[])
                .unwrap();
            let source = operation
                .source_model_body_item(&frame, &item, &[], &[], &[(current, &frozen)], &[])
                .unwrap();
            assert_eq!(source.bytes, expected);
            assert!(
                source.word_events.is_empty(),
                "nested slot path alone cannot forward a Text role: {body}"
            );
            assert_eq!(operation.template_copy_work.allowance, 0);
            assert_eq!(frozen.cached_result, "A&\tB");
        }
    }

    #[test]
    fn scoped_template_word_ordered_requested_text_keeps_actual_producer_intervals() {
        use crate::text::{CT_P, CT_R, RunContent};
        let word = crate::namespace::W_NS;
        let data = serde_json::Value::Null;
        for (prefix, declarations, attribute) in [
            ("w:", format!(r#"xmlns:w="{word}""#), "w:"),
            (
                "q:",
                format!(r#"xmlns:q="{word}" xmlns:w="urn:opaque""#),
                "q:",
            ),
            (
                "",
                format!(r#"xmlns="{word}" xmlns:x="{word}" xmlns:w="urn:opaque""#),
                "x:",
            ),
        ] {
            for empty in [false, true] {
                let cache = if empty {
                    String::new()
                } else {
                    format!("<{prefix}r><{prefix}t>old</{prefix}t></{prefix}r>")
                };
                let xml = format!(
                    r#"<{prefix}p {declarations}><{prefix}fldSimple {attribute}instr="CUSTOM"><{prefix}hyperlink>{cache}</{prefix}hyperlink></{prefix}fldSimple></{prefix}p>"#
                );
                let parsed = CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
                let mut frozen = parsed
                    .runs
                    .into_iter()
                    .flat_map(|run| run.content)
                    .find_map(|content| {
                        if let RunContent::Field(field) = content {
                            Some(field)
                        } else {
                            None
                        }
                    })
                    .unwrap();
                frozen.cached_result = "A&\tB".into();
                let mut operation = super::ScopedWordOperation::with_template_word_inputs(
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    vec![&frozen],
                    Vec::new(),
                    &data,
                )
                .unwrap();
                let prepared = operation
                    .prepare_template_field(&frozen, &frozen, true)
                    .unwrap();
                let mut run = CT_R::new("");
                run.content = vec![RunContent::Field(prepared)];
                let mut paragraph = CT_P::new();
                paragraph.runs.push(run);
                let item = super::BodyContent::Paragraph(Box::new(paragraph));
                let super::BodyContent::Paragraph(paragraph) = &item else {
                    unreachable!()
                };
                let RunContent::Field(current) = &paragraph.runs[0].content[0] else {
                    unreachable!()
                };
                let source = operation
                    .source_model_body_item(
                        &super::CT_Document::new(),
                        &item,
                        &[],
                        &[],
                        &[(current, &frozen)],
                        &[],
                    )
                    .unwrap();
                assert_eq!(source.word_events.len(), 2, "{prefix} empty={empty}");
                for (event, decoded) in source.word_events.iter().zip([0..2, 3..4]) {
                    assert_eq!(
                        event.origin,
                        crate::text::TemplateWordOrigin::CachedResult(
                            std::ptr::from_ref(&frozen) as usize
                        )
                    );
                    assert_eq!(event.decoded, decoded);
                    assert!(source.as_bytes().get(event.encoded.clone()).is_some());
                }
                assert_eq!(operation.template_copy_work.allowance, 0);
                let source = operation
                    .close_source_namespaces(
                        source,
                        &std::collections::BTreeMap::from([("w".into(), word.into())]),
                    )
                    .unwrap();
                let expected = crate::placeholder::replaceable_texts(
                    &operation.source_paragraph(&source).unwrap(),
                );
                assert_eq!(
                    operation.template_replaceable_texts(&source).unwrap(),
                    expected
                );
                let before = operation.template_copy_work.allowance;
                assert_eq!(
                    operation.template_replaceable_texts(&source).unwrap(),
                    expected
                );
                assert_eq!(operation.template_copy_work.allowance, before);
                assert_eq!(frozen.cached_result, "A&\tB");
            }
        }
    }

    #[test]
    fn scoped_template_word_header_only_cache_retains_raw_role_through_flags() {
        use crate::text::{CT_P, CT_R, RunContent};
        let word = crate::namespace::W_NS;
        let data = serde_json::Value::Null;
        for (prefix, declarations, attribute) in [
            ("w:", format!(r#"xmlns:w="{word}""#), "w:"),
            (
                "q:",
                format!(r#"xmlns:q="{word}" xmlns:w="urn:opaque""#),
                "q:",
            ),
            (
                "",
                format!(r#"xmlns="{word}" xmlns:x="{word}" xmlns:w="urn:opaque""#),
                "x:",
            ),
        ] {
            let xml = format!(
                r#"<{prefix}p {declarations}><{prefix}fldSimple {attribute}instr="CUSTOM"><{prefix}r><{prefix}t>old</{prefix}t></{prefix}r></{prefix}fldSimple></{prefix}p>"#
            );
            let parsed = CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
            let mut frozen = parsed
                .runs
                .into_iter()
                .flat_map(|run| run.content)
                .find_map(|content| match content {
                    RunContent::Field(field) => Some(field),
                    _ => None,
                })
                .unwrap();
            frozen.set_locked(Some(true));
            let mut operation = super::ScopedWordOperation::with_template_word_inputs(
                Vec::new(),
                Vec::new(),
                Vec::new(),
                Vec::new(),
                vec![&frozen],
                Vec::new(),
                &data,
            )
            .unwrap();
            let mut run = CT_R::new("");
            run.content = vec![RunContent::Field(frozen.clone())];
            let mut paragraph = CT_P::new();
            paragraph.runs.push(run);
            let item = super::BodyContent::Paragraph(Box::new(paragraph));
            let super::BodyContent::Paragraph(paragraph) = &item else {
                unreachable!()
            };
            let RunContent::Field(current) = &paragraph.runs[0].content[0] else {
                unreachable!()
            };
            let source = operation
                .source_model_body_item(
                    &super::CT_Document::new(),
                    &item,
                    &[],
                    &[],
                    &[(current, &frozen)],
                    &[],
                )
                .unwrap();
            assert!(source.word_events.is_empty());
            let source = operation
                .close_source_namespaces(
                    source,
                    &std::collections::BTreeMap::from([("w".to_owned(), word.to_owned())]),
                )
                .unwrap();
            assert_eq!(
                operation.template_replaceable_texts(&source).unwrap(),
                ["old"]
            );
            assert_eq!(
                operation.template_copy_work.allowance,
                3 * (word.len() + 64)
            );
            let raw = frozen.raw_source_for_test().unwrap();
            let at = raw.windows(3).position(|bytes| bytes == b"old").unwrap();
            assert_eq!(operation.template_copy_work.word_inputs.len(), 1);
            assert_eq!(
                operation.template_copy_work.word_inputs.get(
                    &crate::text::TemplateWordOrigin::Raw {
                        start: raw.as_ptr() as usize + at,
                        end: raw.as_ptr() as usize + at + 3
                    }
                ),
                Some(&std::collections::BTreeMap::from([(0, 3)]))
            );
            assert!(!source.source_map.entirely_original());
        }
    }

    #[test]
    fn scoped_template_word_parsed_changed_cache_maps_survive_publication() {
        use crate::text::{CT_P, CT_R, RunContent};
        let word = crate::namespace::W_NS;
        let data = serde_json::Value::Null;
        for (prefix, declarations, attribute) in [
            ("w:", format!(r#"xmlns:w="{word}""#), "w:"),
            (
                "q:",
                format!(r#"xmlns:q="{word}" xmlns:w="urn:opaque""#),
                "q:",
            ),
            (
                "",
                format!(r#"xmlns="{word}" xmlns:x="{word}" xmlns:w="urn:opaque""#),
                "x:",
            ),
        ] {
            for (complex, locked) in [
                (false, None),
                (true, None),
                (false, Some(true)),
                (true, Some(true)),
            ] {
                let body = if complex {
                    format!(
                        r#"<{prefix}r><{prefix}fldChar {attribute}fldCharType="begin"/></{prefix}r><{prefix}r><{prefix}instrText>CUSTOM</{prefix}instrText></{prefix}r><{prefix}r><{prefix}fldChar {attribute}fldCharType="separate"/></{prefix}r><{prefix}r><{prefix}t>old</{prefix}t></{prefix}r><{prefix}r><{prefix}fldChar {attribute}fldCharType="end"/></{prefix}r>"#
                    )
                } else {
                    format!(
                        r#"<{prefix}fldSimple {attribute}instr="CUSTOM"><{prefix}r><{prefix}t>old</{prefix}t></{prefix}r></{prefix}fldSimple>"#
                    )
                };
                let xml = format!("<{prefix}p {declarations}>{body}</{prefix}p>");
                let parsed = CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
                let mut frozen = parsed
                    .runs
                    .into_iter()
                    .flat_map(|run| run.content)
                    .find_map(|content| match content {
                        RunContent::Field(field) => Some(field),
                        _ => None,
                    })
                    .unwrap();
                frozen.cached_result = "A&\tB".into(); // Genuine incoming scalar before operation freeze.
                frozen.set_locked(locked);
                let mut operation = super::ScopedWordOperation::with_template_word_inputs(
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    vec![&frozen],
                    Vec::new(),
                    &data,
                )
                .unwrap();
                let prepared = operation
                    .prepare_template_field(&frozen, &frozen, false)
                    .unwrap();
                let mut run = CT_R::new("");
                run.content = vec![RunContent::Field(prepared)];
                let mut paragraph = CT_P::new();
                paragraph.runs.push(run);
                let item = super::BodyContent::Paragraph(Box::new(paragraph));
                let super::BodyContent::Paragraph(paragraph) = &item else {
                    unreachable!()
                };
                let RunContent::Field(current) = &paragraph.runs[0].content[0] else {
                    unreachable!()
                };
                let frame = super::CT_Document::new();
                let source = operation
                    .source_model_body_item(&frame, &item, &[], &[], &[(current, &frozen)], &[])
                    .unwrap();
                let expected = frame
                    .body_item_xml_with_ancestor_declarations(&item, &[])
                    .unwrap();
                assert_eq!(source.as_bytes(), expected, "{prefix} complex={complex}");
                let source = operation
                    .close_source_namespaces(
                        source,
                        &std::collections::BTreeMap::from([("w".to_owned(), word.to_owned())]),
                    )
                    .unwrap();
                assert_eq!(source.word_events.len(), 2, "{prefix} complex={complex}");
                for event in &source.word_events {
                    assert_eq!(
                        event.origin,
                        crate::text::TemplateWordOrigin::CachedResult(
                            std::ptr::from_ref(&frozen) as usize
                        )
                    );
                }
                assert_eq!(source.word_events[0].decoded, 0..2);
                assert_eq!(source.word_events[1].decoded, 3..4);
                assert_eq!(operation.template_copy_work.allowance, 0);
                let reparsed = operation.source_paragraph(&source).unwrap();
                let expected_walk = crate::placeholder::replaceable_texts(&reparsed);
                assert_eq!(expected_walk, if complex { vec![""] } else { vec!["A&B"] });
                assert_eq!(
                    operation.template_replaceable_texts(&source).unwrap(),
                    expected_walk,
                    "{prefix} complex={complex}"
                );
                let allowance = if complex { 0 } else { 3 * (word.len() + 64) };
                assert_eq!(operation.template_copy_work.allowance, allowance);
                assert_eq!(
                    operation.template_replaceable_texts(&source).unwrap(),
                    expected_walk
                );
                assert_eq!(operation.template_copy_work.allowance, allowance);
                assert_eq!(frozen.cached_result, "A&\tB");
            }
        }
    }

    #[test]
    fn scoped_template_word_parsed_field_raw_storage_is_not_scalar_authority() {
        use crate::text::{CT_P, CT_R, Field, RunContent};
        fn parse_field(xml: &[u8]) -> Field {
            let paragraph = CT_P::from_xml_fragment(xml).unwrap();
            paragraph
                .runs
                .into_iter()
                .flat_map(|run| run.content)
                .find_map(|content| match content {
                    RunContent::Field(field) => Some(field),
                    _ => None,
                })
                .unwrap()
        }
        fn item(field: Field) -> super::BodyContent {
            let mut run = CT_R::new("");
            run.content = vec![RunContent::Field(field)];
            let mut paragraph = CT_P::new();
            paragraph.runs.push(run);
            super::BodyContent::Paragraph(Box::new(paragraph))
        }
        fn emit<'a>(
            operation: &mut super::ScopedWordOperation<'a>,
            item: &super::BodyContent,
            frozen: &'a Field,
        ) -> crate::Result<super::ScopedWordSource> {
            let super::BodyContent::Paragraph(paragraph) = item else {
                unreachable!()
            };
            let RunContent::Field(current) = &paragraph.runs[0].content[0] else {
                unreachable!()
            };
            let source = operation.source_model_body_item(
                &super::CT_Document::new(),
                item,
                &[],
                &[],
                &[(current, frozen)],
                &[],
            )?;
            operation.close_source_namespaces(
                source,
                &std::collections::BTreeMap::from([(
                    "w".to_owned(),
                    crate::namespace::W_NS.to_owned(),
                )]),
            )
        }
        let xml = format!(
            r#"<w:p xmlns:w="{}"><w:fldSimple w:instr="CUSTOM"><w:r><w:t>cached&amp;input</w:t></w:r></w:fldSimple></w:p>"#,
            crate::namespace::W_NS
        );
        let frozen = parse_field(xml.as_bytes());
        let raw = frozen.raw_source_for_test().unwrap();
        let data = serde_json::Value::Null;
        let mut operation = super::ScopedWordOperation::with_template_word_inputs(
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![&frozen],
            Vec::new(),
            &data,
        )
        .unwrap();
        let current = item(frozen.clone());
        let source = emit(&mut operation, &current, &frozen).unwrap();
        let payload = source
            .as_bytes()
            .windows(16)
            .position(|bytes| bytes == b"cached&amp;input")
            .unwrap();
        let raw_payload = raw
            .windows(16)
            .position(|bytes| bytes == b"cached&amp;input")
            .unwrap();
        assert_eq!(
            source.source_map.word_range(payload..payload + 16),
            Some(raw.as_ptr() as usize + raw_payload..raw.as_ptr() as usize + raw_payload + 16)
        );
        assert!(source.word_events.is_empty());
        assert!(!source.source_map.entirely_original());
        assert_eq!(operation.template_copy_work.allowance, 0);
        assert_eq!(
            operation.template_replaceable_texts(&source).unwrap(),
            ["cached&input"]
        );
        assert_eq!(
            operation.template_copy_work.allowance,
            12 * (crate::namespace::W_NS.len() + 64)
        );
        let repeated = emit(&mut operation, &current, &frozen).unwrap();
        assert_eq!(
            operation.template_replaceable_texts(&repeated).unwrap(),
            ["cached&input"]
        );
        assert_eq!(
            operation.template_copy_work.allowance,
            12 * (crate::namespace::W_NS.len() + 64)
        );

        let generated_equal = item(parse_field(xml.as_bytes())); // Equal bytes, independent source allocation.
        let mut other = super::ScopedWordOperation::with_template_word_inputs(
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![&frozen],
            Vec::new(),
            &data,
        )
        .unwrap();
        let generated = emit(&mut other, &generated_equal, &frozen).unwrap();
        assert_eq!(
            other.template_replaceable_texts(&generated).unwrap(),
            ["cached&input"]
        );
        assert_eq!(other.template_copy_work.allowance, 0);
        let mut changed = frozen.clone();
        changed.cached_result = "computed".into();
        changed.instruction = Field::new("CUSTOM other", "").instruction;
        let changed = item(changed);
        let changed = emit(&mut other, &changed, &frozen).unwrap();
        assert_eq!(
            other.template_replaceable_texts(&changed).unwrap(),
            ["computed"]
        );
        assert_eq!(other.template_copy_work.allowance, 0);
        assert!(changed.word_events.is_empty());
        assert_eq!(frozen.cached_result, "cached&input");
    }

    #[test]
    fn scoped_template_word_preparation_keeps_refusal_sticky_for_raw_bypass() {
        let frozen = crate::text::Field::new("CUSTOM", "cache");
        let data = serde_json::Value::Null;
        let mut operation = super::ScopedWordOperation::with_template_word_inputs(
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![&frozen],
            Vec::new(),
            &data,
        )
        .unwrap();
        assert!(
            operation
                .field_work
                .reserve_publication_copy(usize::MAX)
                .is_err()
        );
        let before = operation.field_work.original_input_state_for_test();
        assert!(
            operation
                .prepare_template_field(&frozen, &frozen, false)
                .is_err()
        );
        assert_eq!(operation.field_work.original_input_state_for_test(), before);
        assert_eq!(operation.template_copy_work.allowance, 0);
    }

    #[test]
    fn scoped_template_word_prepared_field_scalar_segments_and_mutation_authority() {
        use crate::text::{Field, RunContent, TemplateWordOrigin};
        let frozen = Field::new("CUSTOM", "first&\nlast");
        let data = serde_json::Value::Null;
        let mut operation = super::ScopedWordOperation::with_template_word_inputs(
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![&frozen],
            Vec::new(),
            &data,
        )
        .unwrap();
        let prepared = operation
            .prepare_template_field(&frozen, &frozen, false)
            .unwrap();
        assert_eq!(prepared, frozen);
        assert_eq!(operation.template_copy_work.allowance, 0);
        let frame = super::CT_Document::new();
        let mut paragraph = crate::text::CT_P::new();
        let mut run = crate::text::CT_R::new("");
        run.content = vec![RunContent::Field(prepared.clone())];
        paragraph.runs.push(run);
        let mut item = super::BodyContent::Paragraph(Box::new(paragraph));
        fn emit<'a>(
            operation: &mut super::ScopedWordOperation<'a>,
            item: &super::BodyContent,
            frame: &super::CT_Document,
            frozen: &'a Field,
        ) -> crate::Result<super::ScopedWordSource> {
            let super::BodyContent::Paragraph(paragraph) = item else {
                unreachable!()
            };
            let RunContent::Field(current) = &paragraph.runs[0].content[0] else {
                unreachable!()
            };
            let source = operation.source_model_body_item(
                frame,
                item,
                &[],
                &[],
                &[(current, frozen)],
                &[],
            )?;
            operation.close_source_namespaces(
                source,
                &std::collections::BTreeMap::from([(
                    "w".to_owned(),
                    crate::namespace::W_NS.to_owned(),
                )]),
            )
        }
        let source = emit(&mut operation, &item, &frame, &frozen).unwrap();
        assert_eq!(source.word_events.len(), 2);
        assert_eq!(
            source.word_events[0].origin,
            TemplateWordOrigin::CachedResult(std::ptr::from_ref(&frozen) as usize)
        );
        assert_eq!(source.word_events[0].decoded, 0..6);
        assert_eq!(source.word_events[1].decoded, 7..11);
        assert_eq!(
            operation.template_replaceable_texts(&source).unwrap(),
            ["first&last"]
        );
        assert_eq!(
            operation.template_copy_work.allowance,
            10 * (crate::namespace::W_NS.len() + 64)
        );
        let repeat = operation
            .prepare_template_field(&prepared, &frozen, true)
            .unwrap();
        let super::BodyContent::Paragraph(paragraph) = &mut item else {
            unreachable!()
        };
        paragraph.runs[0].content[0] = RunContent::Field(repeat);
        let repeated = emit(&mut operation, &item, &frame, &frozen).unwrap();
        assert_eq!(
            operation.template_replaceable_texts(&repeated).unwrap(),
            ["first&last"]
        );
        assert_eq!(
            operation.template_copy_work.allowance,
            10 * (crate::namespace::W_NS.len() + 64)
        );
        let super::BodyContent::Paragraph(paragraph) = &mut item else {
            unreachable!()
        };
        let RunContent::Field(current) = &mut paragraph.runs[0].content[0] else {
            unreachable!()
        };
        current.cached_result = "other&\nlast".into(); // Same length, untracked direct public mutation.
        let generated = emit(&mut operation, &item, &frame, &frozen).unwrap();
        assert!(generated.word_events.is_empty());
        assert_eq!(
            operation.template_copy_work.allowance,
            10 * (crate::namespace::W_NS.len() + 64)
        );
        assert_eq!(frozen.cached_result, "first&\nlast");
    }

    #[test]
    fn scoped_template_word_prepared_shared_source_fields_remain_distinct() {
        use crate::text::{Field, RunContent, TemplateWordOrigin};
        let first = Field::new("CUSTOM", "first");
        let mut second = first.clone(); // Same retained source Arc, divergent incoming operand.
        second.cached_result = "other".into();
        let data = serde_json::Value::Null;
        let mut operation = super::ScopedWordOperation::with_template_word_inputs(
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![&first, &second],
            Vec::new(),
            &data,
        )
        .unwrap();
        let mut frame = super::CT_Document::new();
        for frozen in [&first, &second] {
            let prepared = operation
                .prepare_template_field(frozen, frozen, false)
                .unwrap();
            let mut run = crate::text::CT_R::new("");
            run.content = vec![RunContent::Field(prepared)];
            let mut paragraph = crate::text::CT_P::new();
            paragraph.runs.push(run);
            frame
                .body
                .content
                .push(super::BodyContent::Paragraph(Box::new(paragraph)));
        }
        let mut events = Vec::new();
        for (item, frozen) in frame.body.content.iter().zip([&first, &second]) {
            let super::BodyContent::Paragraph(paragraph) = item else {
                unreachable!()
            };
            let RunContent::Field(current) = &paragraph.runs[0].content[0] else {
                unreachable!()
            };
            let source = operation
                .source_model_body_item(&frame, item, &[], &[], &[(current, frozen)], &[])
                .unwrap();
            let source = operation
                .close_source_namespaces(
                    source,
                    &std::collections::BTreeMap::from([(
                        "w".to_owned(),
                        crate::namespace::W_NS.to_owned(),
                    )]),
                )
                .unwrap();
            events.push(source.word_events[0].origin.clone());
            assert_eq!(
                operation.template_replaceable_texts(&source).unwrap(),
                [frozen.cached_result.as_str()]
            );
        }
        assert_eq!(
            events,
            [
                TemplateWordOrigin::CachedResult(std::ptr::from_ref(&first) as usize),
                TemplateWordOrigin::CachedResult(std::ptr::from_ref(&second) as usize)
            ]
        );
        assert_eq!(
            operation.template_copy_work.allowance,
            10 * (crate::namespace::W_NS.len() + 64)
        );
    }

    #[test]
    fn scoped_template_word_prepared_bypass_and_receipt_scope_stay_inert() {
        use crate::text::{CT_P, CT_R, Field, RunContent};
        let invalid = Field::new("CUSTOM", "\0");
        let first = Field::new("CUSTOM", "same");
        let equal_other = Field::new("CUSTOM", "same");
        let data = serde_json::Value::Null;
        let mut operation = super::ScopedWordOperation::with_template_word_inputs(
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![&invalid, &first, &equal_other],
            Vec::new(),
            &data,
        )
        .unwrap();
        let before = operation.field_work.original_input_state_for_test();
        let bypass = operation
            .prepare_template_field(&invalid, &invalid, false)
            .unwrap();
        assert_eq!(bypass, invalid);
        assert_eq!(operation.field_work.original_input_state_for_test(), before);
        assert_eq!(operation.template_copy_work.allowance, 0);
        let prepared = operation
            .prepare_template_field(&first, &first, false)
            .unwrap();
        let mut run = CT_R::new("");
        run.content = vec![RunContent::Field(prepared.clone())];
        let mut paragraph = CT_P::new();
        paragraph.runs.push(run);
        let item = super::BodyContent::Paragraph(Box::new(paragraph));
        let super::BodyContent::Paragraph(paragraph) = &item else {
            unreachable!()
        };
        let RunContent::Field(current) = &paragraph.runs[0].content[0] else {
            unreachable!()
        };
        let frame = super::CT_Document::new();
        let source = operation
            .source_model_body_item(&frame, &item, &[], &[], &[(current, &equal_other)], &[])
            .unwrap();
        assert!(source.word_events.is_empty()); // Equal bytes cannot rebind a live receipt.
        let mut other = super::ScopedWordOperation::with_template_word_inputs(
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![&first],
            Vec::new(),
            &data,
        )
        .unwrap();
        let source = other
            .source_model_body_item(&frame, &item, &[], &[], &[(current, &first)], &[])
            .unwrap();
        assert_eq!(source.word_events.len(), 1); // Actual new invocation pair, independent of foreign token.
        drop(operation);
        let source = other
            .source_model_body_item(&frame, &item, &[], &[], &[(current, &first)], &[])
            .unwrap();
        assert_eq!(source.word_events.len(), 1); // Expired token grants no authority of its own.
        assert_eq!(other.template_copy_work.allowance, 0);
    }

