    #[test]
    fn scoped_template_word_note_family_w14_insertion_preserves_text_witness() {
        use crate::text::RunContent;
        let xml = format!(
            r#"<w:p xmlns:w="{}" xmlns:w14="http://schemas.microsoft.com/office/word/2010/wordml" w14:paraId="12345678"><w:r><w:t>note</w:t></w:r></w:p>"#,
            crate::namespace::W_NS
        );
        let frozen = crate::text::CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
        let RunContent::Text(frozen_text) = &frozen.runs[0].content[0] else {
            unreachable!()
        };
        let notes = crate::footnotes::CT_Footnotes {
            footnotes: vec![crate::footnotes::CT_Footnote {
                id: 7,
                note_type: crate::footnotes::NoteType::Normal,
                paragraphs: vec![frozen.clone()],
            }],
        };
        let RunContent::Text(current_text) = &notes.footnotes[0].paragraphs[0].runs[0].content[0]
        else {
            unreachable!()
        };
        let data = serde_json::Value::Null;
        let mut operation = super::ScopedWordOperation::with_template_word_inputs(
            Vec::new(),
            vec![&frozen],
            Vec::new(),
            vec![frozen_text],
            Vec::new(),
            Vec::new(),
            &data,
        )
        .unwrap();
        for endnotes in [false, true] {
            let source = operation
                .source_model_notes(
                    &notes,
                    endnotes,
                    &[(current_text, frozen_text)],
                    &[],
                    &[],
                    false,
                )
                .unwrap();
            let expected = if endnotes {
                notes.to_xml_endnotes()
            } else {
                notes.to_xml_footnotes()
            }
            .unwrap();
            assert_eq!(source.as_bytes(), expected);
            assert!(
                std::str::from_utf8(source.as_bytes())
                    .unwrap()
                    .contains("xmlns:w14=")
            );
            let mut reader = quick_xml::Reader::from_reader(source.as_bytes());
            let range = loop {
                let start = reader.buffer_position() as usize;
                if let quick_xml::events::Event::Start(element) = reader.read_event().unwrap()
                    && element.local_name().as_ref() == b"p"
                {
                    reader.read_to_end(element.name()).unwrap();
                    break start..reader.buffer_position() as usize;
                }
            };
            let paragraph = operation
                .compose_sources(&[(Some(&source), range, &[])])
                .unwrap();
            let scope = std::collections::BTreeMap::from([
                ("w".to_owned(), crate::namespace::W_NS.to_owned()),
                (
                    "w14".to_owned(),
                    "http://schemas.microsoft.com/office/word/2010/wordml".to_owned(),
                ),
            ]);
            let paragraph = operation
                .close_source_namespaces(paragraph, &scope)
                .unwrap();
            assert_eq!(
                operation.template_replaceable_texts(&paragraph).unwrap(),
                ["note"]
            );
            assert_eq!(
                operation.template_copy_work.allowance,
                4 * (crate::namespace::W_NS.len() + 64)
            );
        }
    }
