    #[test]
    fn scoped_original_textbox_consumer_matches_legacy_and_uses_captured_word_inputs() {
        let word = crate::namespace::W_NS;
        for content in [
            "<w:p keep='yes'><w:r><w:t>TOKEN</w:t><w:t>&amp;tail</w:t></w:r></w:p>",
            "<w:tbl><w:tr><w:tc><w:p><w:r><w:t>TOKEN</w:t><w:t>tail</w:t></w:r></w:p></w:tc></w:tr></w:tbl>",
            "<w:sdt><w:sdtContent><w:p><w:r><w:t>TOKEN</w:t><w:t>tail</w:t></w:r></w:p></w:sdtContent></w:sdt>",
            "<w:p><w:r><w:t>TOKEN</w:t   ><w:t>tail</w:t></w:r  ></w:p >",
        ] {
            let xml = format!(
                r#"<part xmlns:w="{word}"><w:txbxContent>{content}</w:txbxContent></part>"#
            );
            let reference = crate::placeholder::replace_original_literals_in_xml_part(
                xml.as_bytes(),
                &[],
                &[("TOKEN", "value")],
            )
            .unwrap();
            let discovered =
                crate::placeholder::replace_original_literals_in_xml_part(xml.as_bytes(), &[], &[])
                    .unwrap()
                    .2;
            let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let (unchanged, count, texts) = operation
                .replace_original_template_literals(&source, &[], &[])
                .unwrap();
            assert_eq!(unchanged.as_bytes(), xml.as_bytes());
            assert_eq!(count, 0);
            assert_eq!(texts, discovered);
            let allowance = operation.template_copy_work.allowance;
            assert!(allowance > 0);
            let (rewritten, count, texts) = operation
                .replace_original_template_literals(&source, &[], &[("TOKEN", "value", &[])])
                .unwrap();
            assert_eq!(rewritten.as_bytes(), reference.0);
            assert_eq!(count, reference.1);
            assert!(texts.is_empty());
            assert_eq!(operation.template_copy_work.allowance, allowance);
            assert_eq!(source.as_bytes(), xml.as_bytes());
        }
    }

    #[test]
    fn scoped_original_textbox_consumer_preserves_implicit_consumed_root_and_exclusions() {
        let word = crate::namespace::W_NS;
        for content in [
            format!(
                r#"<q:p xmlns:q="{word}" xmlns:w="urn:foreign"><q:r><q:t>TOKEN</q:t></q:r></q:p>"#
            ),
            format!(r#"<p xmlns="{word}" xmlns:w="urn:foreign"><w:r><w:t>TOKEN</w:t></w:r></p>"#),
        ] {
            let xml = format!(
                r#"<part xmlns:w="{word}"><w:txbxContent>{content}</w:txbxContent></part>"#
            );
            let old = crate::placeholder::replace_original_literals_in_xml_part(
                xml.as_bytes(),
                &[],
                &[("TOKEN", "value")],
            )
            .unwrap();
            let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let (actual, count, _) = operation
                .replace_original_template_literals(&source, &[], &[("TOKEN", "value", &[])])
                .unwrap_or_else(|error| panic!("{content}, old count {}, {error}", old.1));
            assert_eq!(actual.as_bytes(), old.0);
            assert_eq!(count, old.1);
            let start = xml.find("<w:txbxContent>").unwrap();
            let end = xml.find("</w:txbxContent>").unwrap() + "</w:txbxContent>".len();
            let (actual, count, texts) = operation
                .replace_original_template_literals(
                    &source,
                    std::slice::from_ref(&(start..end)),
                    &[],
                )
                .unwrap();
            assert_eq!(actual.as_bytes(), source.as_bytes());
            assert_eq!(count, 0);
            assert!(texts.is_empty());
        }
    }

