    #[test]
    fn scoped_original_textbox_return_materializes_known_field_roles_before_source_drop() {
        let field = r#"<w:fldSimple w:instr="CUSTOM"><w:r><w:t>cached</w:t></w:r></w:fldSimple>"#;
        let xml = format!(
            r#"<part xmlns:w="{}"><w:txbxContent><w:p>{field}</w:p></w:txbxContent></part>"#,
            crate::namespace::W_NS
        );
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        let (returned, count, texts) = operation
            .replace_original_template_literals(&source, &[], &[])
            .unwrap();
        assert_eq!(count, 0);
        assert_eq!(texts, ["cached"]);
        let start = xml.find(field).unwrap();
        let expected = start..start + field.len();
        assert_eq!(
            source.publication.lock().unwrap().fields.as_slice(),
            std::slice::from_ref(&expected)
        );
        assert_eq!(
            returned.publication.lock().unwrap().fields.as_slice(),
            std::slice::from_ref(&expected)
        );
        let weak = std::sync::Arc::downgrade(&source.publication);
        drop(source);
        assert!(weak.upgrade().is_none());
        assert_eq!(
            returned.publication.lock().unwrap().fields.as_slice(),
            std::slice::from_ref(&expected)
        );
        let copied = operation
            .compose_sources(&[(Some(&returned), expected, &[])])
            .unwrap();
        assert_eq!(
            copied.publication.lock().unwrap().fields.as_slice(),
            std::slice::from_ref(&(0..field.len()))
        );
    }

