        let xml = format!(
            r#"<part xmlns:w="{word}"><w:txbxContent><q:p xmlns:q="{word}" xmlns:w="urn:foreign"><q:r>
 <q:t>{payload}</q:t>
 <q:t>x</q:t> </q:r></q:p></w:txbxContent></part>"#
        );
