    #[test]
    fn scoped_template_row_views_share_occurrences_not_equal_strings() {
        let xml = format!(
            r#"<w:tr xmlns:w="{}"><w:tc><w:p><w:r><w:t>same</w:t></w:r></w:p><w:p><w:r><w:t>same</w:t></w:r></w:p><w:tbl><w:tr><w:tc><w:p><w:r><w:t>nested</w:t></w:r></w:p></w:tc></w:tr></w:tbl></w:tc><w:tc/></w:tr>"#,
            crate::namespace::W_NS
        );
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        crate::table::CHECKED_TABLE_READS.with(|count| count.set(0));
        let (buffers, direct, all, hazard) =
            operation.template_row_replaceable_texts(&source).unwrap();
        assert_eq!(
            crate::table::CHECKED_TABLE_READS.with(|count| count.get()),
            1
        );
        let strings = |view: &[usize]| {
            view.iter()
                .map(|index| buffers[*index].as_str())
                .collect::<Vec<_>>()
        };
        assert_eq!(strings(&direct), ["same", "same"]);
        assert_eq!(strings(&all), ["same", "same", "nested"]);
        assert_ne!(direct[0], direct[1]);
        assert_eq!(&all[..2], direct);
        assert_eq!(buffers.len(), 3);
        assert!(!hazard);
        assert!(operation.template_copy_work.allowance > 0);
        assert_eq!(operation.template_copy_work.copied, 0);
        assert_eq!(source.as_bytes(), xml.as_bytes());
    }

