    #[test]
    fn scoped_template_row_direct_run_uses_its_actual_standalone_parser_companion() {
        use crate::text::WordBlockComponent as C;
        let xml = format!(
            r#"<w:sdt xmlns:w="{}"><w:sdtContent><w:r><w:t>direct</w:t><w:t>only</w:t></w:r><w:p><w:r><w:t>both</w:t></w:r></w:p></w:sdtContent></w:sdt>"#,
            crate::namespace::W_NS
        );
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        let admitted = super::admit_word_source(
            xml.as_bytes(),
            &[],
            None,
            Some(crate::content_control::SdtOwner::Standalone),
        )
        .unwrap()
        .with_source_map(
            source
                .source_map
                .with_word_source(&source.word_source_map, &source.word_events)
                .unwrap(),
        )
        .unwrap();
        let mut cursor = admitted
            .controls_for(xml.as_bytes())
            .with_field_origins(std::sync::Arc::clone(&operation.field_origins), true);
        let mut child = crate::text::WordBlockSourceMaps {
            collect_word_texts: true,
            ..Default::default()
        };
        let control = crate::content_control::CT_Sdt::from_raw_with_mapped_context_and_maps(
            xml.as_bytes(),
            &[],
            crate::content_control::SdtOwner::Standalone,
            Some(&mut cursor),
            Some(std::sync::Arc::clone(&admitted.source_map)),
            Some(&mut child),
        )
        .unwrap();
        let mut row = crate::table::CT_Row::new();
        row.content_controls.push((0, 0, control));
        let mut inner = crate::text::WordBlockSourceMaps::default();
        inner.append(C::RowControl(0), child);
        let mut maps = crate::text::WordBlockSourceMaps::default();
        maps.append(C::TableRow(0), inner);
        let (buffers, direct, all) = crate::placeholder::template_row_texts_in(
            &mut row,
            maps,
            &admitted.source_map,
            &mut operation.field_work,
            &mut operation.template_copy_work,
        )
        .unwrap();
        assert_eq!(buffers, ["directonly", "both"]);
        assert_eq!(direct, [0, 1]);
        assert_eq!(all, [1]);
        assert_eq!(operation.template_copy_work.copied, 4);
    }

    #[test]
    fn scoped_template_row_namespace_hazard_and_validation_before_credit() {
        for (name, declaration) in [
            (
                "q",
                format!(
                    r#"xmlns:q="{}" xmlns:w="urn:foreign""#,
                    crate::namespace::W_NS
                ),
            ),
            (
                "",
                format!(
                    r#"xmlns="{}" xmlns:w="urn:foreign""#,
                    crate::namespace::W_NS
                ),
            ),
        ] {
            let prefix = if name.is_empty() {
                String::new()
            } else {
                format!("{name}:")
            };
            let xml = format!(
                r#"<{prefix}tr {declaration}><{prefix}tc><{prefix}p><{prefix}r><{prefix}t>input</{prefix}t></{prefix}r></{prefix}p></{prefix}tc></{prefix}tr>"#
            );
            let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let (buffers, direct, all, hazard) =
                operation.template_row_replaceable_texts(&source).unwrap();
            assert_eq!(buffers, ["input"]);
            assert_eq!(direct, all);
            assert!(!hazard);
        }
        let xml = format!(
            r#"<w:tr xmlns:w="{}" xmlns:x="urn:opaque" x:kept="yes"><w:tc/><x:kept/></w:tr>"#,
            crate::namespace::W_NS
        );
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        let (buffers, direct, all, hazard) =
            operation.template_row_replaceable_texts(&source).unwrap();
        assert!(buffers.is_empty() && direct.is_empty() && all.is_empty());
        assert!(hazard);
        let mut bad = operation.compose_sources(&[(None, 0..0, b"<w:tr xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:tc><w:p><w:r><w:t>unvisited</w:t></w:r></w:p></w:tc></w:tr>")]).unwrap();
        // Deliberately corrupt this same-length test carrier after its creation
        // to exercise the consumer's own full-owner check, before TextWalk.
        let end = bad.bytes.len();
        bad.bytes[end - 3..end - 1].copy_from_slice(b"xx");
        let before = operation.template_copy_work.allowance;
        assert!(operation.template_row_replaceable_texts(&bad).is_err());
        assert_eq!(operation.template_copy_work.allowance, before);
    }

    #[test]
    fn scoped_template_row_commits_returned_field_ranges_with_nonzero_original_offset() {
        let word = crate::namespace::W_NS;
        let field = r#"<q:fldSimple q:instr="CUSTOM"><q:r><q:t>cached</q:t></q:r></q:fldSimple>"#;
        let row = format!(
            r#"<q:tr xmlns:q="{word}" xmlns:w="urn:foreign"><q:tc><q:p>{field}</q:p></q:tc></q:tr>"#
        );
        let original = format!(r#"<document>{row}</document>"#);
        let offset = original.find(&row).unwrap();
        let mut operation = super::ScopedWordOperation::new(original.as_bytes());
        let source = operation
            .source(offset..offset + row.len(), &Default::default())
            .unwrap();
        assert!(source.publication.lock().unwrap().fields.is_empty());
        let (buffers, direct, all, hazard) =
            operation.template_row_replaceable_texts(&source).unwrap();
        assert_eq!(buffers, ["cached"]);
        assert_eq!(direct, all);
        assert!(!hazard);
        let start = row.find(field).unwrap();
        assert_eq!(
            source.publication.lock().unwrap().fields.as_slice(),
            std::slice::from_ref(&(start..start + field.len()))
        );
        let state = operation.field_work.original_input_state_for_test();
        assert!(state.0 > 0);
        operation.template_row_replaceable_texts(&source).unwrap();
        assert_eq!(operation.field_work.original_input_state_for_test(), state);
        let copied = operation
            .compose_sources(&[(Some(&source), start..start + field.len(), &[])])
            .unwrap();
        drop(source);
        assert_eq!(
            copied.publication.lock().unwrap().fields.as_slice(),
            std::slice::from_ref(&(0..field.len()))
        );
    }

    #[test]
    fn scoped_template_row_generated_append_refuses_and_later_input_funds_actual_copy() {
        let original = format!(
            r#"<w:tr xmlns:w="{}"><w:tc><w:p><w:r><w:t>real</w:t></w:r></w:p></w:tc></w:tr>"#,
            crate::namespace::W_NS
        );
        let mut operation = super::ScopedWordOperation::new(original.as_bytes());
        let source = operation
            .source(0..original.len(), &Default::default())
            .unwrap();
        let start = original.find("<w:t>").unwrap();
        let end = original.find("</w:t>").unwrap() + 6;
        let prefix = format!(
            r#"<w:tr xmlns:w="{}"><w:tc><w:p><w:r><w:t>generated</w:t>"#,
            crate::namespace::W_NS
        );
        let suffix = b"</w:r></w:p></w:tc></w:tr>";
        let mixed = operation
            .compose_sources(&[
                (None, 0..0, prefix.as_bytes()),
                (Some(&source), start..end, &[]),
                (None, 0..0, suffix),
            ])
            .unwrap();
        let (buffers, direct, all, _) = operation.template_row_replaceable_texts(&mixed).unwrap();
        assert_eq!(buffers, ["generatedreal"]);
        assert_eq!(direct, all);
        assert_eq!(operation.template_copy_work.copied, 4);
        let allowance = operation.template_copy_work.allowance;
        operation.template_row_replaceable_texts(&mixed).unwrap();
        assert_eq!(operation.template_copy_work.allowance, allowance);
        assert_eq!(operation.template_copy_work.copied, 8);
        let mut unfunded = super::ScopedWordOperation::new(&[]);
        let generated = unfunded
            .compose_sources(&[(None, 0..0, mixed.as_bytes())])
            .unwrap();
        assert!(unfunded.template_row_replaceable_texts(&generated).is_err());
        assert_eq!(unfunded.template_copy_work.allowance, 0);
    }

    #[test]
    fn scoped_template_row_singleton_generated_page_is_moved_once_for_both_views() {
        use crate::text::{CT_P, CT_R, Field, RunContent};
        let frozen = Field::new("PAGE", "");
        let mut table = crate::table::CT_Tbl::new();
        let mut row = crate::table::CT_Row::new();
        let mut cell = crate::table::CT_Tc::new();
        cell.content = vec![crate::table::CellContent::Paragraph(CT_P {
            runs: vec![CT_R {
                content: vec![RunContent::Field(frozen.clone())],
                ..CT_R::new("")
            }],
            ..CT_P::new()
        })];
        row.cells.push(cell);
        table.rows.push(row);
        let item = super::BodyContent::Table(Box::new(table));
        let super::BodyContent::Table(table) = &item else {
            unreachable!()
        };
        let crate::table::CellContent::Paragraph(paragraph) = &table.rows[0].cells[0].content[0]
        else {
            unreachable!()
        };
        let RunContent::Field(current) = &paragraph.runs[0].content[0] else {
            unreachable!()
        };
        let data = serde_json::Value::Null;
        let mut operation = super::ScopedWordOperation::with_template_word_inputs(
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![&frozen],
            Vec::new(),
            &data,
        )
        .unwrap();
        let source = operation
            .source_model_body_item(
                &super::CT_Document::new(),
                &item,
                &[],
                &[],
                &[(current, &frozen)],
                &[],
            )
            .unwrap();
        let mut reader = quick_xml::Reader::from_reader(source.as_bytes());
        let range = loop {
            let start = reader.buffer_position() as usize;
            if let quick_xml::events::Event::Start(root) = reader.read_event().unwrap()
                && root.local_name().as_ref() == b"tr"
            {
                reader.read_to_end(root.name()).unwrap();
                break start..reader.buffer_position() as usize;
            }
        };
        let row = operation
            .compose_sources(&[(Some(&source), range, &[])])
            .unwrap();
        let (buffers, direct, all, _) = operation.template_row_replaceable_texts(&row).unwrap();
        assert_eq!(buffers, ["1"]);
        assert_eq!(direct, [0]);
        assert_eq!(all, direct);
        assert_eq!(operation.template_copy_work.allowance, 0);
        assert_eq!(operation.template_copy_work.copied, 0);
        assert!(operation.reserve_template_text_copy(1).is_err());
    }

    const IMPORT_FIELD_XML: &[u8] = br#"<w:p xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:r><w:t>outside</w:t></w:r><w:fldSimple w:instr="CUSTOM"><w:r><w:t>CACHE</w:t></w:r></w:fldSimple></w:p>"#;

    fn imported_field_parent() -> (super::ScopedWordOperation<'static>, super::ScopedWordSource) {
        let mut operation = super::ScopedWordOperation::new(IMPORT_FIELD_XML);
        let source = operation
            .source(0..IMPORT_FIELD_XML.len(), &Default::default())
            .unwrap();
        operation.source_paragraph(&source).unwrap();
        (operation, source)
    }

