    #[test]
    fn scoped_w14_full_document_writer_retains_actual_field_publication() {
        use crate::text::{CT_P, CT_R, Field, RunContent};
        let mut frozen = CT_P::from_xml_fragment(br#"<w:p xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:w14="http://schemas.microsoft.com/office/word/2010/wordml" w14:paraId="1234"/>"#).unwrap();
        let mut run = CT_R::new("");
        run.content = vec![RunContent::Field(Field::new("CUSTOM", "cache"))];
        frozen.runs.push(run);
        frozen.runs.push(CT_R::new("A&\r\nB"));
        let RunContent::Field(frozen_field) = &frozen.runs[0].content[0] else {
            unreachable!()
        };
        let RunContent::Text(frozen_text) = &frozen.runs[1].content[0] else {
            unreachable!()
        };
        let mut document = super::CT_Document::new();
        document.body.content = vec![super::BodyContent::Paragraph(Box::new(frozen.clone()))];
        let super::BodyContent::Paragraph(current) = &document.body.content[0] else {
            unreachable!()
        };
        let RunContent::Field(current_field) = &current.runs[0].content[0] else {
            unreachable!()
        };
        let RunContent::Text(current_text) = &current.runs[1].content[0] else {
            unreachable!()
        };
        let data = serde_json::Value::Null;
        let mut operation = super::ScopedWordOperation::with_template_word_inputs(
            Vec::new(),
            vec![&frozen],
            Vec::new(),
            Vec::new(),
            vec![frozen_field],
            Vec::new(),
            &data,
        )
        .unwrap();
        let source = operation
            .source_model_document(
                &document,
                &[(current_text, frozen_text)],
                &[(current_field, frozen_field)],
                &[],
            )
            .unwrap();
        assert_eq!(source.as_bytes(), document.to_xml().unwrap());
        assert!(!source.current_publication().fields.is_empty());
        assert!(
            crate::text::plan_w14_on_part_root(source.as_bytes())
                .unwrap()
                .is_none()
        );
        assert!(source.constructors.is_some());
        assert_eq!(
            source.word_events.len(),
            2,
            "Field cache and ordinary Text each retain their actual event"
        );
        let (_, _, ranges) = document.to_xml_with_body_spans().unwrap();
        let paragraph = operation
            .compose_sources(&[(Some(&source), ranges[0].clone(), &[])])
            .unwrap();
        let scope = std::collections::BTreeMap::from([
            ("w".into(), crate::namespace::W_NS.into()),
            (
                "w14".into(),
                "http://schemas.microsoft.com/office/word/2010/wordml".into(),
            ),
        ]);
        let paragraph = operation
            .close_source_namespaces(paragraph, &scope)
            .unwrap();
        assert_eq!(
            operation.template_replaceable_texts(&paragraph).unwrap(),
            ["cache", "A&\r\nB"]
        );
        let known = source.current_publication().fields;
        for range in known {
            assert!(String::from_utf8_lossy(&source.as_bytes()[range]).contains("CUSTOM"));
        }
    }

    #[test]
    fn scoped_w14_source_matches_shared_policy_aliases_bom_and_noop_moves() {
        let namespace = crate::namespace::W_NS;
        for (root, body, insert) in [
            ("", "<q:p w14:paraId=\"1\"/>", true),
            ("", "<q:p><q:r><q:t>w14</q:t></q:r></q:p>", false),
            (
                " xmlns:w14=\"urn:foreign\"",
                "<q:p w14:paraId=\"1\"/>",
                false,
            ),
            (
                " xmlns:w14=\"http://schemas.microsoft.com/office/word/2010/wordml\"",
                "<q:p w14:paraId=\"1\"/>",
                false,
            ),
            (
                "",
                "<q:p xmlns:i=\"http://schemas.microsoft.com/office/word/2010/wordml\" i:paraId=\"1\"/>",
                false,
            ),
        ] {
            for prefix in [&b""[..], &b"\xef\xbb\xbf \n"[..]] {
                let xml = format!(
                    r#"<q:document xmlns:q="{namespace}"{root}><q:body>{body}</q:body></q:document>"#
                );
                let xml = [prefix, xml.as_bytes()].concat();
                let mut expected = xml.clone();
                crate::text::declare_w14_on_part_root(&mut expected).unwrap();
                let mut operation = super::ScopedWordOperation::new(&xml);
                let source = operation.compose_sources(&[(None, 0..0, &xml)]).unwrap();
                let pointer = source.bytes.as_ptr();
                let state = operation.field_work.original_input_state_for_test();
                let source = operation.declare_source_w14_on_root(source).unwrap();
                assert_eq!(source.as_bytes(), expected);
                assert_eq!(source.as_bytes().len() > xml.len(), insert);
                assert_eq!(operation.field_work.original_input_state_for_test(), state);
                if !insert {
                    assert_eq!(source.bytes.as_ptr(), pointer);
                } else {
                    let declaration = crate::text::plan_w14_on_part_root(&xml).unwrap().unwrap();
                    let at = declaration.0;
                    let generated = source
                        .source_map
                        .slice(at..at + declaration.1.len())
                        .unwrap();
                    assert!(generated.original_pieces().is_empty());
                    assert!(!source.initial_delivery);
                }
            }
        }
    }

    #[test]
    fn scoped_w14_noop_preserves_actual_imported_payload_and_delivery() {
        let (mut operation, parent) = imported_field_parent();
        let owner = parent.current_publication().fields[0].clone();
        let source = operation
            .source_imported_field_xml(&parent, owner.clone(), "<r/>", false)
            .unwrap();
        let pointer = source.bytes.as_ptr();
        let payload = std::ptr::from_ref(source.payload.as_deref().unwrap());
        let delivered = source.initial_delivery;
        let state = operation.field_work.original_input_state_for_test();
        let source = operation.declare_source_w14_on_root(source).unwrap();
        assert_eq!(source.bytes.as_ptr(), pointer);
        assert_eq!(
            std::ptr::from_ref(source.payload.as_deref().unwrap()),
            payload
        );
        assert_eq!(source.initial_delivery, delivered);
        assert_eq!(operation.field_work.original_input_state_for_test(), state);
        operation
            .rewrite_imported_source(parent, vec![(owner, source)])
            .unwrap();
    }

    #[test]
    fn scoped_w14_refuses_known_field_copy_before_growth_and_stays_sticky() {
        let xml = br#"<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:fldSimple w:instr="CUSTOM"><w:r><w:t> w14:conservative</w:t></w:r></w:fldSimple></w:p></w:body></w:document>"#;
        let mut operation = super::ScopedWordOperation::new(xml);
        let source = operation.compose_sources(&[(None, 0..0, xml)]).unwrap();
        operation.source_document(&source).unwrap();
        assert!(!source.current_publication().fields.is_empty());
        assert_eq!(
            operation.field_work.original_input_state_for_test(),
            (0, 0, 0)
        );
        let held = operation
            .compose_sources(&[(None, 0..0, b"<held/>")])
            .unwrap();
        assert!(operation.declare_source_w14_on_root(source).is_err());
        assert!(operation.field_work.resource_refused());
        let allowance = operation.template_copy_work.allowance;
        assert!(operation.reserve_template_text_copy(0).is_err());
        assert_eq!(operation.template_copy_work.allowance, allowance);
        assert_eq!(held.as_bytes(), b"<held/>");
        assert!(operation.declare_source_w14_on_root(held).is_err());
    }

    #[test]
    fn scoped_w14_invalid_preparation_and_foreign_identity_do_not_spend_copy_work() {
        let prepare = || {
            let (mut operation, parent) = imported_field_parent();
            let owner = parent.current_publication().fields[0].clone();
            let source = operation
                .source_imported_field_xml(&parent, owner, "<r broken>", false)
                .unwrap();
            (operation, source)
        };
        let (mut operation, source) = prepare();
        let (reference, _) = prepare();
        let state = operation.field_work.original_input_state_for_test();
        assert!(operation.declare_source_w14_on_root(source).is_err());
        assert!(!operation.field_work.resource_refused());
        assert_eq!(operation.field_work.original_input_state_for_test(), state);
        let remaining = |work: &crate::text::WordOperationWork| {
            (0..10000)
                .take_while(|_| work.reserve_publication_copy(1).is_ok())
                .count()
        };
        assert_eq!(
            remaining(&operation.field_work),
            remaining(&reference.field_work)
        );
        let (mut foreign, _) = imported_field_parent();
        let (mut owner, _) = imported_field_parent();
        let source = owner.compose_sources(&[(None, 0..0, b"<r/>")]).unwrap();
        let state = foreign.field_work.original_input_state_for_test();
        assert!(foreign.declare_source_w14_on_root(source).is_err());
        assert!(!foreign.field_work.resource_refused());
        assert_eq!(foreign.field_work.original_input_state_for_test(), state);
    }

