    #[test]
    fn scoped_transport_copy_composition_unions_both_fact_stores_and_counts_output_occurrences() {
        for map_only in [false, true] {
            let (mut operation, source) = imported_field_parent();
            let source = operation.repeat_source(&source).unwrap();
            let before = operation.field_work.original_input_state_for_test();
            let fields = source.current_publication().fields;
            let known: usize = fields.iter().map(|range| range.len()).sum();
            assert!(known > 0);
            if map_only {
                source.publication.lock().unwrap().fields.clear();
                assert!(source.publication.lock().unwrap().fields.is_empty());
                assert!(
                    !source
                        .source_map
                        .materialized_publication()
                        .fields
                        .is_empty()
                );
            }
            let (mut reference, original) = imported_field_parent();
            let _same_first_copy = reference.repeat_source(&original).unwrap();
            let whole = source.as_bytes().len();
            let copied = operation
                .compose_sources(&[
                    (None, 0..0, b"<outer>"),
                    (Some(&source), 0..whole, &[]),
                    (None, 0..0, b"<extra xmlns=\"urn:generated\"/>"),
                    (Some(&source), 0..whole, &[]),
                    (None, 0..0, b"</outer>"),
                ])
                .unwrap();
            reference
                .field_work
                .reserve_publication_copy(known * 2)
                .unwrap();
            assert_eq!(operation.field_work.original_input_state_for_test(), before);
            let output = copied.current_publication();
            assert_eq!(
                output.fields.iter().map(|range| range.len()).sum::<usize>(),
                known * 2
            );
            assert!(
                output.ordinary.is_empty(),
                "generated gaps supply no ordinary proof"
            );
            assert!(!copied.initial_delivery);
            let remaining = |work: &crate::text::WordOperationWork| {
                (0..10000)
                    .take_while(|_| work.reserve_publication_copy(known).is_ok())
                    .count()
            };
            assert_eq!(
                remaining(&operation.field_work),
                remaining(&reference.field_work)
            );
            assert!(
                operation.compose_sources(&[]).is_err(),
                "refusal stays sticky for fieldless copies"
            );
        }
    }

