    #[test]
    fn scoped_import_many_splices_visit_only_selected_owned_ranges() {
        let count = 256;
        let ranges: Vec<_> = (0..count).map(|i| i * 4..i * 4 + 2).collect();
        let map = super::WordSourceMap::generated(count * 4)
            .with_publication_owned(ranges.clone())
            .unwrap();
        super::PUBLICATION_OWNED_RANGE_PROBES.set(0);
        for range in ranges {
            let selected = map.slice(range).unwrap();
            assert_eq!(selected.publication_owned, vec![0..2]);
        }
        let probes = super::PUBLICATION_OWNED_RANGE_PROBES.get();
        assert!(
            probes <= count * 12,
            "{probes} owned-range probes for {count} splices"
        );
    }

    #[test]
    fn scoped_property_complex_projection_returns_only_actual_outside_run_facts_and_keeps_field_priority()
     {
        for outside in [false, true] {
            let before = if outside { "<w:t>before</w:t>" } else { "" };
            let after = if outside { "<w:t>after</w:t>" } else { "" };
            let raw = format!(
                r#"<w:p xmlns:w="{}"><w:r><w:rPr><w:rStyle w:val="SHARED-STYLE"/></w:rPr>{before}<w:fldChar w:fldCharType="begin"/><w:instrText>CUSTOM</w:instrText><w:fldChar w:fldCharType="separate"/><w:t>cache</w:t><w:fldChar w:fldCharType="end"/>{after}</w:r></w:p>"#,
                crate::namespace::W_NS
            );
            let mut operation = super::ScopedWordOperation::new(raw.as_bytes());
            let source = operation.source(0..raw.len(), &Default::default()).unwrap();
            let mut facts = Vec::new();
            let paragraph = operation
                .parse_source_paragraph_with_properties(
                    &source,
                    None,
                    None,
                    None,
                    Some(&mut facts),
                    None,
                )
                .unwrap();
            assert_eq!(
                facts.len(),
                if outside { 2 } else { 0 },
                "only actual returned outside runs have ordinary companions"
            );
            assert_eq!(paragraph.runs.len(), if outside { 3 } else { 1 });
            let at = source
                .as_bytes()
                .windows(12)
                .position(|part| part == b"SHARED-STYLE")
                .unwrap();
            assert_eq!(
                source.imported_owner_kind(&(at..at + 12)),
                Some(true),
                "the shared property is also a real Field shell"
            );
            super::WordOrdinaryFact::publish_all(facts);
            assert_eq!(source.imported_owner_kind(&(at..at + 12)), Some(true));
            assert_eq!(operation.template_copy_work.allowance, 0);
        }
    }

    #[test]
    fn scoped_property_mapping_keeps_generated_holes_and_unions_overlapping_collector_tapes() {
        let collector = std::sync::Arc::new(std::sync::Mutex::new(
            super::WordPublicationCoverage::default(),
        ));
        let mut map = super::WordSourceMap::generated(3);
        let first = super::WordPublicationPiece {
            output: 0..1,
            current: 10..11,
            collector: std::sync::Arc::downgrade(&collector),
        };
        map.publication = vec![
            first.clone(),
            super::WordPublicationPiece {
                output: 2..3,
                current: 12..13,
                collector: std::sync::Arc::downgrade(&collector),
            },
            first,
        ];
        super::WordOrdinaryFact::publish_all(vec![super::WordOrdinaryFact {
            map: std::sync::Arc::new(map),
            selected: 0..3,
        }]);
        assert_eq!(collector.lock().unwrap().ordinary, vec![10..11, 12..13]);
        collector
            .lock()
            .unwrap()
            .add_ranges(std::iter::once(12..13).collect());
        assert_eq!(collector.lock().unwrap().ordinary, vec![10..11]);
        assert_eq!(collector.lock().unwrap().fields, vec![12..13]);
    }

    #[test]
    fn scoped_property_late_wrapper_reader_publishes_only_after_its_actual_success() {
        for valid in [true, false] {
            let failure = if valid {
                ""
            } else {
                "<w:r><w:rPr><w:sz w:val=\"invalid\"/></w:rPr></w:r>"
            };
            let raw = format!(
                r#"<w:smartTag xmlns:w="{}"><w:r><w:rPr><w:rStyle w:val="LATE-STYLE"/></w:rPr><w:t>x</w:t></w:r>{failure}</w:smartTag>"#,
                crate::namespace::W_NS
            );
            let mut operation = super::ScopedWordOperation::new(raw.as_bytes());
            let source = operation.source(0..raw.len(), &Default::default()).unwrap();
            let at = source
                .as_bytes()
                .windows(10)
                .position(|part| part == b"LATE-STYLE")
                .unwrap();
            assert_eq!(source.imported_owner_kind(&(at..at + 10)), None);
            let input = super::WordFieldInput::produced(
                source
                    .source_map
                    .clone()
                    .with_publication_collector(&source.publication),
                std::sync::Arc::clone(&operation.field_origins),
            );
            let parsed = crate::text::run_wrapper_paragraph_in(
                source.as_bytes(),
                &["w".into()],
                Some(&input),
                None,
                None,
                None,
            )
            .unwrap();
            assert_eq!(parsed.is_some(), valid);
            assert_eq!(
                source.imported_owner_kind(&(at..at + 10)),
                valid.then_some(false)
            );
            assert_eq!(operation.template_copy_work.allowance, 0);
        }
    }

    #[test]
    fn scoped_property_source_document_retains_selected_facts_through_tables_and_controls() {
        let paragraph = r#"<w:p><w:pPr><w:pStyle w:val="CONTAINER-P"/></w:pPr><w:r><w:rPr><w:rStyle w:val="CONTAINER-R"/></w:rPr><w:t>x</w:t></w:r></w:p>"#;
        let inline = r#"<w:p><w:pPr><w:pStyle w:val="CONTAINER-P"/></w:pPr><w:sdt><w:sdtContent><w:r><w:rPr><w:rStyle w:val="CONTAINER-R"/></w:rPr><w:t>x</w:t></w:r></w:sdtContent></w:sdt></w:p>"#;
        let linked = r#"<w:p><w:pPr><w:pStyle w:val="CONTAINER-P"/></w:pPr><w:hyperlink w:anchor="a"><w:r/><w:r><w:rPr><w:rStyle w:val="CONTAINER-R"/></w:rPr><w:t>x</w:t></w:r></w:hyperlink></w:p>"#;
        let bodies = [
            paragraph.to_owned(),
            format!("<w:tbl><w:tr><w:tc>{paragraph}</w:tc></w:tr></w:tbl>"),
            format!("<w:sdt><w:sdtContent>{paragraph}</w:sdtContent></w:sdt>"),
            format!(
                "<w:tbl><w:sdt><w:sdtContent><w:tr><w:tc>{paragraph}</w:tc></w:tr></w:sdtContent></w:sdt></w:tbl>"
            ),
            format!(
                "<w:tbl><w:tr><w:sdt><w:sdtContent><w:tc>{paragraph}</w:tc></w:sdtContent></w:sdt></w:tr></w:tbl>"
            ),
            format!(
                "<w:tbl><w:tr><w:tc><w:sdt><w:sdtContent>{paragraph}</w:sdtContent></w:sdt></w:tc></w:tr></w:tbl>"
            ),
            inline.to_owned(),
            linked.to_owned(),
        ];
        for (kind, body) in bodies.into_iter().enumerate() {
            for (prefix, bom) in [("w", ""), ("q", "\u{feff}")] {
                let body = body.replace("w:", &format!("{prefix}:"));
                let raw = format!(
                    r#"{bom}<{prefix}:document xmlns:{prefix}="{}"><{prefix}:body>{body}</{prefix}:body></{prefix}:document>"#,
                    crate::namespace::W_NS
                );
                let mut operation = super::ScopedWordOperation::new(raw.as_bytes());
                let source = operation.source(0..raw.len(), &Default::default()).unwrap();
                let p = source
                    .as_bytes()
                    .windows(11)
                    .position(|part| part == b"CONTAINER-P")
                    .unwrap();
                let r = source
                    .as_bytes()
                    .windows(11)
                    .position(|part| part == b"CONTAINER-R")
                    .unwrap();
                let parsed = operation.source_document(&source).unwrap();
                assert!(
                    !matches!(parsed.body.content[0], super::BodyContent::RawXml(_)),
                    "fixture {kind} must reach a typed owner"
                );
                assert_eq!(
                    source.imported_owner_kind(&(p..p + 11)),
                    Some(false),
                    "pStyle owner {kind} {prefix}"
                );
                assert_eq!(
                    source.imported_owner_kind(&(r..r + 11)),
                    Some(false),
                    "rStyle owner {kind} {prefix}"
                );
                assert_eq!(operation.template_copy_work.allowance, 0);
            }
        }
    }

