    #[test]
    fn scoped_property_source_paragraph_qualifies_aliases_and_bom_without_selecting_text() {
        for prefix in ["w", "q"] {
            for bom in ["", "\u{feff}"] {
                let raw = format!(
                    r#"{bom}<{prefix}:p xmlns:{prefix}="{}"><{prefix}:pPr><{prefix}:pStyle {prefix}:val="P-STYLE-VALUE"/></{prefix}:pPr><{prefix}:r><{prefix}:rPr><{prefix}:rStyle {prefix}:val="R-STYLE-VALUE"/></{prefix}:rPr><{prefix}:t>ordinary-text</{prefix}:t></{prefix}:r></{prefix}:p>"#,
                    crate::namespace::W_NS
                );
                let mut operation = super::ScopedWordOperation::new(raw.as_bytes());
                let source = operation.source(0..raw.len(), &Default::default()).unwrap();
                let bytes = source.as_bytes();
                let p = bytes
                    .windows(13)
                    .position(|part| part == b"P-STYLE-VALUE")
                    .unwrap();
                let r = bytes
                    .windows(13)
                    .position(|part| part == b"R-STYLE-VALUE")
                    .unwrap();
                let text = bytes
                    .windows(13)
                    .position(|part| part == b"ordinary-text")
                    .unwrap();
                assert_eq!(source.imported_owner_kind(&(p..p + 13)), None);
                operation.source_paragraph(&source).unwrap();
                assert_eq!(
                    source.imported_owner_kind(&(p..p + 13)),
                    Some(false),
                    "{raw}"
                );
                assert_eq!(
                    source.imported_owner_kind(&(r..r + 13)),
                    Some(false),
                    "{raw}"
                );
                assert_eq!(source.imported_owner_kind(&(text..text + 13)), None);
                assert_eq!(operation.template_copy_work.allowance, 0);
            }
        }
    }

