    #[test]
    fn scoped_property_run_companion_replaces_overwritten_properties_without_early_publication() {
        let xml = br#"<w:r xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:rPr><w:rStyle w:val="old"/></w:rPr><w:t>x</w:t><w:rPr><w:rStyle w:val="new"/></w:rPr></w:r>"#;
        let mut operation = super::ScopedWordOperation::new(xml);
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        let input = super::WordFieldInput::produced(
            source
                .source_map
                .clone()
                .with_publication_collector(&source.publication),
            std::sync::Arc::clone(&operation.field_origins),
        );
        let mut fact = None;
        let run = crate::text::parse_run_raw_with_observation(
            source.as_bytes(),
            &["w".into()],
            None,
            Some(&input),
            Some(&mut fact),
        )
        .unwrap();
        assert_eq!(run.properties.unwrap().style_id.as_deref(), Some("new"));
        assert!(source.publication.lock().unwrap().ordinary.is_empty());
        assert_eq!(operation.template_copy_work.allowance, 0);
        super::WordOrdinaryFact::publish_all(vec![fact.unwrap()]);
        let old = xml.windows(3).position(|bytes| bytes == b"old").unwrap();
        let new = xml.windows(3).position(|bytes| bytes == b"new").unwrap();
        assert_eq!(source.imported_owner_kind(&(old..old + 3)), None);
        assert_eq!(source.imported_owner_kind(&(new..new + 3)), Some(false));
    }

