    #[test]
    fn scoped_import_rewrite_sorts_actual_payloads_and_allows_interior_empty_values() {
        let (mut operation, source) = imported_field_parent();
        let owner = source.publication.lock().unwrap().fields[0].clone();
        let instruction = IMPORT_FIELD_XML
            .windows(6)
            .position(|bytes| bytes == b"CUSTOM")
            .unwrap();
        let cache = IMPORT_FIELD_XML
            .windows(5)
            .position(|bytes| bytes == b"CACHE")
            .unwrap();
        let first = operation
            .source_imported_field_xml(&source, owner.clone(), "A", false)
            .unwrap();
        let last = operation
            .source_imported_field_xml(&source, owner, "B", false)
            .unwrap();
        let result = operation
            .rewrite_imported_source(
                source,
                vec![(cache..cache + 5, last), (instruction..instruction, first)],
            )
            .unwrap();
        let mut expected = IMPORT_FIELD_XML.to_vec();
        expected.splice(cache..cache + 5, b"B".iter().copied());
        expected.splice(instruction..instruction, b"A".iter().copied());
        assert_eq!(result.as_bytes(), expected);
        assert!(result.constructors.is_none());
        assert!(!result.initial_delivery);
        operation.source_paragraph(&result).unwrap();
    }

