    #[test]
    fn scoped_ordinary_bom_roots_exclude_the_bom_and_use_physical_current_positions() {
        let xml = format!(
            "<w:document xmlns:w=\"{}\">\n<w:body/>\n</w:document>",
            crate::namespace::W_NS
        );
        let input = [b"\xef\xbb\xbf".as_slice(), xml.as_bytes()].concat();
        let mut operation = super::ScopedWordOperation::new(&input);
        let source = operation
            .source(0..input.len(), &Default::default())
            .unwrap();
        assert_eq!(source.as_bytes(), input);
        let parsed = operation.source_document(&source).unwrap();
        assert_eq!(
            parsed.to_xml().unwrap(),
            super::CT_Document::from_xml(&input)
                .unwrap()
                .to_xml()
                .unwrap()
        );
        let text = std::str::from_utf8(&input).unwrap();
        let doc_end = text.find('>').unwrap() + 1;
        let body = text.find("<w:body/>").unwrap();
        let close = text.find("</w:document>").unwrap();
        let coverage = source.publication.lock().unwrap();
        assert_eq!(
            coverage.ordinary,
            vec![3..doc_end, body..body + 9, close..input.len()]
        );
        assert!(!coverage.ordinary.iter().any(|range| range.start < 3));
    }

