    #[test]
    fn scoped_ordinary_root_facts_use_actual_current_event_bounds_only() {
        let word = crate::namespace::W_NS;
        let xml = format!(
            r#"<!--prefix--><q:document xmlns:q="{word}" xmlns:w="urn:foreign"><q:background><w:body/></q:background><q:body marker="kept"><q:p><q:fldSimple q:instr="CUSTOM"><q:r><q:t>cache</q:t></q:r></q:fldSimple></q:p></q:body></q:document><!--suffix-->"#,
        );
        let original = format!("<packet>unselected{xml}</packet>");
        let offset = original.find(&xml).unwrap();
        let mut operation = super::ScopedWordOperation::new(original.as_bytes());
        let source = operation
            .source(offset..offset + xml.len(), &Default::default())
            .unwrap();
        let ordinary = super::CT_Document::from_xml(xml.as_bytes()).unwrap();
        let parsed = operation.source_document(&source).unwrap();
        assert_eq!(parsed.to_xml().unwrap(), ordinary.to_xml().unwrap());
        let doc = xml.find("<q:document").unwrap();
        let doc_end = doc + xml[doc..].find('>').unwrap() + 1;
        let body = xml.find("<q:body ").unwrap();
        let body_end = body + xml[body..].find('>').unwrap() + 1;
        let close = xml.find("</q:document>").unwrap();
        let expected = vec![
            doc..doc_end,
            body..body_end,
            close..close + "</q:document>".len(),
        ];
        let coverage = source.publication.lock().unwrap();
        assert_eq!(coverage.ordinary, expected);
        assert!(!coverage.fields.is_empty());
        let child = xml.find("<q:p>").unwrap();
        let background = xml.find("<q:background>").unwrap();
        assert!(
            !coverage
                .ordinary
                .iter()
                .any(|range| range.contains(&child) || range.contains(&background))
        );
        assert_eq!(
            operation.field_work.original_input_state_for_test(),
            (0, 0, 0)
        );
        assert_eq!(operation.template_copy_work.allowance, 0);
        assert_eq!(operation.template_copy_work.copied, 0);
    }

    #[test]
    fn scoped_ordinary_empty_body_does_not_classify_shadowed_foreign_events() {
        let xml = format!(
            r#"<q:document xmlns:q="{}" xmlns:w="urn:foreign"><w:body/><q:body/></q:document>"#,
            crate::namespace::W_NS,
        );
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        operation.source_document(&source).unwrap();
        let foreign = xml.find("<w:body/>").unwrap();
        let body = xml.find("<q:body/>").unwrap();
        let coverage = source.publication.lock().unwrap();
        assert!(coverage.fields.is_empty());
        assert!(
            !coverage
                .ordinary
                .iter()
                .any(|range| range.contains(&foreign))
        );
        assert!(
            coverage
                .ordinary
                .iter()
                .any(|range| range.start <= body && body + "<q:body/>".len() <= range.end)
        );
        assert!(
            !coverage
                .ordinary
                .iter()
                .any(|range| range.start == 0 && range.end == xml.len())
        );
        assert_eq!(
            operation.field_work.original_input_state_for_test(),
            (0, 0, 0)
        );
    }

    #[test]
    fn scoped_ordinary_images_survive_copy_drop_and_leave_namespace_insertions_unknown() {
        let xml = format!(
            r#"<q:document xmlns:q="{}"><q:body><x:unknown xmlns:x="urn:opaque"/></q:body></q:document>"#,
            crate::namespace::W_NS,
        );
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        operation.source_document(&source).unwrap();
        let before = source.publication.lock().unwrap().ordinary.clone();
        let map = source
            .source_map
            .clone()
            .with_publication_collector(&source.publication);
        let body = before[1].clone();
        let selected = map.slice(body.clone()).unwrap().materialized_publication();
        assert_eq!(
            selected.ordinary.as_slice(),
            std::slice::from_ref(&(0..body.len()))
        );
        let composed = operation
            .compose_sources(&[
                (None, 0..0, b"<!--new-->"),
                (Some(&source), 0..xml.len(), &[]),
                (None, 0..0, b"<!--tail-->"),
            ])
            .unwrap();
        assert_eq!(
            composed.publication.lock().unwrap().ordinary,
            before
                .iter()
                .map(|range| range.start + 10..range.end + 10)
                .collect::<Vec<_>>()
        );
        let repeated = operation.repeat_source(&composed).unwrap();
        drop(source);
        drop(composed);
        assert!(
            !repeated
                .source_map
                .materialized_publication()
                .ordinary
                .is_empty()
        );
        let scope = std::collections::BTreeMap::from([("z".to_owned(), "urn:new".to_owned())]);
        let closed = operation.close_source_namespaces(repeated, &scope).unwrap();
        let text = std::str::from_utf8(closed.as_bytes()).unwrap();
        let inserted = text.find(" xmlns:z=").unwrap();
        assert!(
            !closed
                .publication
                .lock()
                .unwrap()
                .ordinary
                .iter()
                .any(|range| range.contains(&inserted))
        );
        assert!(
            !closed
                .source_map
                .materialized_publication()
                .ordinary
                .iter()
                .any(|range| range.contains(&inserted))
        );
        operation.source_document(&closed).unwrap();
        assert!(
            closed
                .publication
                .lock()
                .unwrap()
                .ordinary
                .iter()
                .any(|range| range.contains(&inserted))
        );
        assert_eq!(
            operation.field_work.original_input_state_for_test(),
            (0, 0, 0)
        );
        assert_eq!(operation.template_copy_work.allowance, 0);
    }

    #[test]
    fn scoped_ordinary_ranges_yield_to_positive_fields_without_filling_unknown_gaps() {
        let mut coverage = super::WordPublicationCoverage::default();
        coverage.add_ordinary_ranges(vec![0..10, 20..30]);
        coverage.add_ranges(vec![2..4, 6..8, 24..26]);
        assert_eq!(coverage.ordinary, vec![0..2, 4..6, 8..10, 20..24, 26..30]);
        coverage.add_ordinary_ranges(std::iter::once(1..29).collect());
        assert_eq!(coverage.ordinary, vec![0..2, 4..6, 8..24, 26..30]);
        coverage.add_ranges(std::iter::once(1..29).collect());
        assert_eq!(coverage.ordinary, vec![0..1, 29..30]);
        assert_eq!(coverage.fields.as_slice(), std::slice::from_ref(&(1..29)));
        // The algebra uses supplied positive facts. It is not a constructor
        // observation or a certificate for any untouched source complement.
    }

    #[test]
    fn scoped_source_document_matches_the_actual_factory_without_word_input_activation() {
        let word = crate::namespace::W_NS;
        let simple =
            r#"<w:p><w:fldSimple w:instr="CUSTOM"><w:r><w:t>cache</w:t></w:r></w:fldSimple></w:p>"#;
        let complex = r#"<w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText> CUSTOM </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>result</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>"#;
        let bodies = [
            simple.to_owned(),
            format!("{simple}{complex}"),
            format!(
                "<w:tbl><w:tr><w:tc>{simple}</w:tc></w:tr></w:tbl><w:sdt><w:sdtContent>{simple}</w:sdtContent></w:sdt>"
            ),
        ];
        for (index, body) in bodies.iter().enumerate() {
            let xml = format!(
                r#"<w:document xmlns:w="{word}" xmlns:x="urn:opaque" x:flag="retained"><w:background w:color="ABCDEF"/><w:body>{body}<x:opaque a="&amp;"><x:leaf/></x:opaque></w:body></w:document>"#
            );
            let xml = if index == 1 {
                xml.replace("w:", "a:")
                    .replace("xmlns:w=", "xmlns:a=")
                    .replacen("<a:document ", "<a:document xmlns:w=\"urn:foreign\" ", 1)
            } else {
                xml
            };
            let ordinary = super::CT_Document::from_xml(xml.as_bytes()).unwrap();
            let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let before = operation.field_work.original_input_state_for_test();
            let parsed = operation.source_document(&source).unwrap();
            assert_eq!(parsed.to_xml().unwrap(), ordinary.to_xml().unwrap());
            assert_eq!(parsed.root_attributes, ordinary.root_attributes);
            assert_eq!(parsed.extra_namespaces, ordinary.extra_namespaces);
            assert_eq!(parsed.background_xml, ordinary.background_xml);
            assert_eq!(parsed.background_extra_xml, ordinary.background_extra_xml);
            assert_eq!(source.as_bytes(), xml.as_bytes());
            assert!(!source.publication.lock().unwrap().fields.is_empty());
            assert_eq!(operation.field_work.original_input_state_for_test(), before);
            assert!(operation.template_copy_work.word_inputs.is_empty());
            assert_eq!(operation.template_copy_work.copied, 0);
        }
    }

