    #[test]
    fn scoped_template_word_generated_prefix_uses_later_visited_input_before_append() {
        let xml = format!(
            r#"<w:p xmlns:w="{}"><w:r><w:t>input</w:t></w:r></w:p>"#,
            crate::namespace::W_NS
        );
        let start = xml.find("<w:t>").unwrap();
        let end = xml.find("</w:t>").unwrap() + "</w:t>".len();
        let scope =
            std::collections::BTreeMap::from([("w".to_owned(), crate::namespace::W_NS.to_owned())]);
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let input = operation.source(start..end, &scope).unwrap();
        let prefix = format!(
            r#"<w:p xmlns:w="{}"><w:r><w:t>G</w:t><w:t>Z</w:t>"#,
            crate::namespace::W_NS
        );
        let mixed = operation
            .compose_sources(&[
                (None, 0..0, prefix.as_bytes()),
                (Some(&input), 0..input.as_bytes().len(), &[]),
                (None, 0..0, b"</w:r></w:p>"),
            ])
            .unwrap();
        assert_eq!(
            operation.template_replaceable_texts(&mixed).unwrap(),
            ["GZinput"]
        );
        assert_eq!(
            operation.template_copy_work.allowance,
            5 * (crate::namespace::W_NS.len() + 64)
        );
        assert_eq!(operation.template_copy_work.copied, 6);
    }
    #[test]
    fn scoped_returned_read_document_and_selected_item_keep_actual_text_inputs() {
        let xml = format!(
            r#"<w:document xmlns:w="{}"><w:body><w:p><w:r><w:t>A&amp;B</w:t></w:r></w:p><w:tbl><w:tr><w:tc><w:p><w:r><w:t>cell</w:t></w:r></w:p></w:tc></w:tr></w:tbl></w:body></w:document>"#,
            crate::namespace::W_NS
        );
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        assert!(
            operation
                .source_model_document_from_read(&super::CT_Document::new(), &source)
                .is_err()
        );
        let document = operation.source_document(&source).unwrap();
        let emitted = operation
            .source_model_document_from_read(&document, &source)
            .unwrap();
        assert_eq!(emitted.as_bytes(), document.to_xml().unwrap());
        assert_eq!(emitted.word_events.len(), 2);
        for (index, item) in document.body.content.iter().enumerate() {
            let selected = operation
                .source_model_body_item_from_read(&document, item, &source, index, &[])
                .unwrap();
            assert_eq!(selected.word_events.len(), 1);
        }
        let item = operation
            .source_model_body_item_from_read(&document, &document.body.content[0], &source, 0, &[])
            .unwrap();
        let scope = std::collections::BTreeMap::from([("w".into(), crate::namespace::W_NS.into())]);
        let item = operation.close_source_namespaces(item, &scope).unwrap();
        let buffers = operation.template_replaceable_texts(&item).unwrap();
        assert_eq!(buffers, ["A&B"]);
        operation
            .reserve_template_text_copy(buffers[0].len())
            .unwrap();
        let copied = buffers[0].clone();
        assert_eq!(copied, "A&B");
        let moved = operation.repeat_source(&source).unwrap();
        assert!(
            operation
                .source_model_document_from_read(&document, &moved)
                .is_err(),
            "payload copy does not certify its model was read"
        );
        let mut foreign = super::ScopedWordOperation::new(xml.as_bytes());
        assert!(
            foreign
                .source_model_document_from_read(&document, &source)
                .is_err()
        );
    }

