    #[test]
    fn scoped_returned_read_note_families_keep_actual_vector_paths_and_bytes() {
        for (root, item, endnotes) in [
            ("footnotes", "footnote", false),
            ("endnotes", "endnote", true),
        ] {
            let xml = format!(
                r#"<w:{root} xmlns:w="{}"><w:{item} w:id="2"><w:p><w:r><w:t>A&amp;B</w:t></w:r></w:p></w:{item}></w:{root}>"#,
                crate::namespace::W_NS
            );
            let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let notes = operation.source_notes(&source).unwrap();
            assert_eq!(
                notes,
                crate::footnotes::CT_Footnotes::from_xml(xml.as_bytes()).unwrap()
            );
            let emitted = operation
                .source_model_notes_from_read(&notes, endnotes, &source)
                .unwrap();
            let expected = if endnotes {
                notes.to_xml_endnotes()
            } else {
                notes.to_xml_footnotes()
            }
            .unwrap();
            assert_eq!(emitted.as_bytes(), expected);
            assert_eq!(emitted.word_events.len(), 1);
            let xml = std::str::from_utf8(emitted.as_bytes()).unwrap();
            let start = xml.find("<w:p>").unwrap();
            let end = start + xml[start..].find("</w:p>").unwrap() + 6;
            let paragraph = operation
                .compose_sources(&[(Some(&emitted), start..end, &[])])
                .unwrap();
            let paragraph = operation
                .close_source_namespaces(
                    paragraph,
                    &std::collections::BTreeMap::from([(
                        "w".into(),
                        crate::namespace::W_NS.into(),
                    )]),
                )
                .unwrap();
            let text = operation.template_replaceable_texts(&paragraph).unwrap();
            operation.reserve_template_text_copy(text[0].len()).unwrap();
            assert_eq!(text, ["A&B"]);
        }
    }

    #[test]
    fn scoped_returned_read_selected_later_note_never_serializes_preceding_note() {
        for (root, item, endnotes) in [
            ("footnotes", "footnote", false),
            ("endnotes", "endnote", true),
        ] {
            let xml = format!(
                r#"<w:{root} xmlns:w="{}"><w:{item} w:id="1"><w:p><w:r><w:t>preceding note</w:t></w:r></w:p></w:{item}><w:{item} w:id="2"><w:p><w:r><w:t>A&amp;B</w:t></w:r></w:p></w:{item}></w:{root}>"#,
                crate::namespace::W_NS
            );
            let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let notes = operation.source_notes(&source).unwrap();
            let selected = &notes.footnotes[1];
            let emitted = operation
                .source_model_note_from_read(selected, endnotes, &source, 1)
                .unwrap();
            let one = crate::footnotes::CT_Footnotes {
                footnotes: vec![selected.clone()],
            };
            let expected = if endnotes {
                one.to_xml_endnotes()
            } else {
                one.to_xml_footnotes()
            }
            .unwrap();
            assert_eq!(emitted.as_bytes(), expected);
            assert_eq!(emitted.word_events.len(), 1);
            assert_eq!(emitted.word_events[0].decoded.len(), 3);
            let crate::text::TemplateWordOrigin::Raw { start, .. } = emitted.word_events[0].origin
            else {
                panic!("actual original raw Text origin")
            };
            assert!(start >= xml.as_ptr() as usize + xml.find("A&amp;B").unwrap());
            let xml = std::str::from_utf8(emitted.as_bytes()).unwrap();
            assert!(!xml.contains("preceding note"));
            let begin = xml.find("<w:p>").unwrap();
            let end = begin + xml[begin..].find("</w:p>").unwrap() + 6;
            let paragraph = operation
                .compose_sources(&[(Some(&emitted), begin..end, &[])])
                .unwrap();
            let paragraph = operation
                .close_source_namespaces(
                    paragraph,
                    &std::collections::BTreeMap::from([(
                        "w".into(),
                        crate::namespace::W_NS.into(),
                    )]),
                )
                .unwrap();
            let text = operation.template_replaceable_texts(&paragraph).unwrap();
            operation.reserve_template_text_copy(text[0].len()).unwrap();
            assert_eq!(text, ["A&B"]);
            assert!(
                operation
                    .source_model_note_from_read(selected, endnotes, &source, 9)
                    .is_err()
            );
        }
    }

    #[test]
    fn scoped_returned_read_field_preparation_forwards_existing_input_only() {
        for (field_xml, expected_text) in [
            (
                r#"<w:fldSimple w:instr="CUSTOM"><w:r><w:t>cache</w:t></w:r></w:fldSimple>"#,
                "A&Bcache",
            ),
            (
                r#"<w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText>CUSTOM</w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:fldSimple w:instr="INNER"><w:r><w:t>cache</w:t></w:r></w:fldSimple><w:r><w:fldChar w:fldCharType="end"/></w:r>"#,
                "A&B",
            ),
        ] {
            let xml = format!(
                r#"<w:document xmlns:w="{}"><w:body><w:p><w:r><w:t>A&amp;B</w:t></w:r>{field_xml}</w:p></w:body></w:document>"#,
                crate::namespace::W_NS
            );
            let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let unread = operation.source(0..xml.len(), &Default::default()).unwrap();
            let mut document = operation.source_document(&source).unwrap();
            let super::BodyContent::Paragraph(paragraph) = &mut document.body.content[0] else {
                unreachable!()
            };
            let field = paragraph
                .runs
                .iter_mut()
                .flat_map(|run| &mut run.content)
                .find_map(|content| match content {
                    crate::text::RunContent::Field(field) => Some(field),
                    _ => None,
                })
                .unwrap();
            let original = field.clone();
            assert!(
                operation
                    .prepare_template_field_from_read(field, &unread, true)
                    .is_err()
            );
            let unrelated = crate::text::Field::new("CUSTOM", "cache");
            assert!(
                operation
                    .prepare_template_field_from_read(&unrelated, &source, true)
                    .is_err()
            );
            let mut foreign = super::ScopedWordOperation::new(xml.as_bytes());
            assert!(
                foreign
                    .prepare_template_field_from_read(field, &source, true)
                    .is_err()
            );
            *field = operation
                .prepare_template_field_from_read(field, &source, false)
                .unwrap();
            assert_eq!(field, &original);
            *field = operation
                .prepare_template_field_from_read(field, &source, true)
                .unwrap();
            assert_eq!(field.cached_result, "cache");
            let emitted = operation
                .source_model_document_from_read(&document, &source)
                .unwrap();
            let output = std::str::from_utf8(emitted.as_bytes()).unwrap();
            let begin = output.find("<w:p>").unwrap();
            let end = begin + output[begin..].find("</w:p>").unwrap() + 6;
            let selected = operation
                .compose_sources(&[(Some(&emitted), begin..end, &[])])
                .unwrap();
            let selected = operation
                .close_source_namespaces(
                    selected,
                    &std::collections::BTreeMap::from([(
                        "w".into(),
                        crate::namespace::W_NS.into(),
                    )]),
                )
                .unwrap();
            let texts = operation.template_replaceable_texts(&selected).unwrap();
            assert_eq!(texts.concat(), expected_text);
            operation
                .reserve_template_text_copy(texts.iter().map(String::len).sum())
                .unwrap();
        }
    }
    #[test]
    fn scoped_returned_read_inline_control_and_revision_preserve_actual_text_records() {
        let p = r#"<w:p><w:ins w:id="1" w:author="A"><w:r><w:t>A&amp;B</w:t></w:r></w:ins><w:sdt><w:sdtPr/><w:sdtContent><w:r><w:t>C&amp;D</w:t></w:r><w:ins w:id="2" w:author="B"><w:r><w:t>E&amp;F</w:t></w:r></w:ins></w:sdtContent></w:sdt></w:p>"#;
        for (context, payload) in [
            ("body", p.to_owned()),
            (
                "table",
                format!("<w:tbl><w:tr><w:tc>{p}</w:tc></w:tr></w:tbl>"),
            ),
            (
                "block control",
                format!("<w:sdt><w:sdtPr/><w:sdtContent>{p}</w:sdtContent></w:sdt>"),
            ),
            ("paragraph", p.to_owned()),
            ("footnotes", p.to_owned()),
            ("endnotes", p.to_owned()),
        ] {
            let xml = match context {
                "paragraph" => payload.replacen(
                    "<w:p>",
                    &format!(r#"<w:p xmlns:w="{}">"#, crate::namespace::W_NS),
                    1,
                ),
                "footnotes" | "endnotes" => {
                    let item = if context == "footnotes" {
                        "footnote"
                    } else {
                        "endnote"
                    };
                    format!(
                        r#"<w:{context} xmlns:w="{}"><w:{item} w:id="2">{payload}</w:{item}></w:{context}>"#,
                        crate::namespace::W_NS
                    )
                }
                _ => format!(
                    r#"<w:document xmlns:w="{}"><w:body>{payload}</w:body></w:document>"#,
                    crate::namespace::W_NS
                ),
            };
            let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let (emitted, expected) = match context {
                "paragraph" => {
                    let model = operation.source_paragraph(&source).unwrap();
                    let item = super::BodyContent::Paragraph(Box::new(model));
                    let expected = super::CT_Document::new().body_item_xml(&item).unwrap();
                    (
                        operation
                            .source_model_body_item_from_read(
                                &super::CT_Document::new(),
                                &item,
                                &source,
                                0,
                                &[],
                            )
                            .unwrap(),
                        expected,
                    )
                }
                "footnotes" | "endnotes" => {
                    let model = operation.source_notes(&source).unwrap();
                    let endnotes = context == "endnotes";
                    let expected = if endnotes {
                        model.to_xml_endnotes()
                    } else {
                        model.to_xml_footnotes()
                    }
                    .unwrap();
                    (
                        operation
                            .source_model_notes_from_read(&model, endnotes, &source)
                            .unwrap(),
                        expected,
                    )
                }
                _ => {
                    let model = operation.source_document(&source).unwrap();
                    (
                        operation
                            .source_model_document_from_read(&model, &source)
                            .unwrap(),
                        model.to_xml().unwrap(),
                    )
                }
            };
            assert_eq!(emitted.as_bytes(), expected, "{context}");
            let output = std::str::from_utf8(emitted.as_bytes()).unwrap();
            let start = output.find("<w:p").unwrap();
            let end = start + output[start..].find("</w:p>").unwrap() + 6;
            let paragraph = operation
                .compose_sources(&[(Some(&emitted), start..end, &[])])
                .unwrap();
            let paragraph = operation
                .close_source_namespaces(
                    paragraph,
                    &std::collections::BTreeMap::from([(
                        "w".into(),
                        crate::namespace::W_NS.into(),
                    )]),
                )
                .unwrap();
            let texts = operation.template_replaceable_texts(&paragraph).unwrap();
            assert_eq!(texts.concat(), "A&BC&DE&F", "{context}");
            assert_eq!(
                operation.template_copy_work.allowance,
                9 * (crate::namespace::W_NS.len() + 64),
                "{context}: every actual Text input reaches selection exactly once"
            );
            operation
                .reserve_template_text_copy(texts.iter().map(String::len).sum())
                .unwrap();
        }
    }
    #[test]
    fn scoped_first_namespace_closure_copy_selects_only_original_field_bytes() {
        let field = r#"<w:fldSimple w:instr="CUSTOM"><w:r><w:t>kept</w:t></w:r></w:fldSimple>"#;
        let xml = format!(r#"<w:p xmlns:w="{}">{field}</w:p>"#, crate::namespace::W_NS);
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        let _paragraph = operation
            .parse_source_paragraph(&source, None, None, None)
            .unwrap();
        assert_eq!(
            operation.field_work.original_input_state_for_test(),
            (0, 0, 0)
        );
        let scope = std::collections::BTreeMap::from([("z".into(), "urn:extra".into())]);
        let closed = operation.close_source_namespaces(source, &scope).unwrap();
        assert!(
            std::str::from_utf8(closed.as_bytes())
                .unwrap()
                .contains("xmlns:z=\"urn:extra\"")
        );
        let selected = operation.field_work.original_input_state_for_test();
        assert_eq!(selected, (field.len(), 0, field.len()));
        assert!(operation.repeat_source(&closed).is_err());
        assert_eq!(
            operation.field_work.original_input_state_for_test(),
            selected
        );
    }
