    #[test]
    fn scoped_revision_installer_prepares_two_actual_slots_and_retains_word_text() {
        for nested in [false, true] {
            let body = r#"<w:r><w:t>A&amp;B</w:t></w:r><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText> FIRST </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>one</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText> SECOND </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>two</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r>"#;
            let content = if nested {
                format!(r#"<w:ins w:id="2" w:author="B">{body}</w:ins>"#)
            } else {
                body.to_owned()
            };
            let xml = format!(
                r#"<w:p xmlns:w="{}"><w:ins w:id="1" w:author="A">{content}</w:ins></w:p>"#,
                crate::namespace::W_NS
            );
            let frozen = crate::text::CT_P::from_xml_fragment(xml.as_bytes()).unwrap();
            let mut operation = super::ScopedWordOperation::with_template_word_inputs(
                vec![],
                vec![&frozen],
                vec![],
                vec![],
                vec![],
                vec![],
                &serde_json::Value::Null,
            )
            .unwrap();
            let mut current = frozen.clone();
            let paths = current.accepted_run_paths();
            let mut installs = 0;
            for path in paths {
                let run = current.accepted_run(&path).unwrap();
                let fields = run
                    .content
                    .iter()
                    .enumerate()
                    .filter_map(|(slot, content)| {
                        let crate::text::RunContent::Field(field) = content else {
                            return None;
                        };
                        let crate::text::RunContent::Field(input) =
                            &frozen.accepted_run(&path).unwrap().content[slot]
                        else {
                            unreachable!()
                        };
                        Some((
                            slot,
                            operation
                                .prepare_template_field(field, input, true)
                                .unwrap(),
                        ))
                    })
                    .collect::<Vec<_>>();
                if fields.is_empty() {
                    continue;
                }
                assert!(
                    operation
                        .install_template_prepared_fields(
                            &mut current,
                            &path,
                            fields,
                            Some(&frozen)
                        )
                        .unwrap()
                );
                installs += 1;
            }
            assert_eq!(installs, 2);
            let frame = super::CT_Document::new();
            let item = super::BodyContent::Paragraph(Box::new(current));
            // The actual writer consumes the refreshed owner's private receipt.
            let output = operation
                .source_model_body_item(&frame, &item, &[], &[], &[], &[])
                .unwrap();
            let output = operation
                .close_source_namespaces(
                    output,
                    &std::collections::BTreeMap::from([(
                        "w".into(),
                        crate::namespace::W_NS.into(),
                    )]),
                )
                .unwrap();
            let read = operation.template_replaceable_texts(&output).unwrap();
            assert_eq!(read.concat(), "A&B");
            operation.reserve_template_text_copy(3).unwrap();
        }
    }

    fn revision_installer_xml() -> String {
        format!(
            r#"<w:p xmlns:w="{}"><w:ins w:id="1" w:author="A"><w:r><w:t>A&amp;B</w:t></w:r><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText> TEST </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>kept</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r></w:ins></w:p>"#,
            crate::namespace::W_NS
        )
    }

    #[test]
    fn scoped_revision_installer_returned_paragraph_and_notes_keep_same_reader_facts() {
        for notes in [false, true] {
            let paragraph = revision_installer_xml();
            let xml = if notes {
                format!(
                    r#"<w:footnotes xmlns:w="{}"><w:footnote w:id="2">{paragraph}</w:footnote></w:footnotes>"#,
                    crate::namespace::W_NS
                )
            } else {
                paragraph
            };
            let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
            let source = operation.source(0..xml.len(), &Default::default()).unwrap();
            let mut family = if notes {
                Some(operation.source_notes(&source).unwrap())
            } else {
                None
            };
            let mut single = if notes {
                None
            } else {
                Some(operation.source_paragraph(&source).unwrap())
            };
            let paragraph = if let Some(family) = &mut family {
                &mut family.footnotes[0].paragraphs[0]
            } else {
                single.as_mut().unwrap()
            };
            let path = paragraph
                .accepted_run_paths()
                .into_iter()
                .find(|path| {
                    paragraph
                        .accepted_run(path)
                        .unwrap()
                        .content
                        .iter()
                        .any(|c| matches!(c, crate::text::RunContent::Field(_)))
                })
                .unwrap();
            let crate::text::RunContent::Field(field) =
                &paragraph.accepted_run(&path).unwrap().content[0]
            else {
                panic!("Field")
            };
            let prepared = operation
                .prepare_template_field_from_read(field, &source, true)
                .unwrap();
            assert!(
                operation
                    .install_template_prepared_fields(paragraph, &path, vec![(0, prepared)], None)
                    .unwrap()
            );
            let item = super::BodyContent::Paragraph(Box::new(paragraph.clone()));
            let emitted = if let Some(family) = &family {
                operation
                    .source_model_notes_from_read(family, false, &source)
                    .unwrap()
            } else {
                operation
                    .source_model_body_item_from_read(
                        &super::CT_Document::new(),
                        &item,
                        &source,
                        0,
                        &[],
                    )
                    .unwrap()
            };
            let text = std::str::from_utf8(emitted.as_bytes()).unwrap();
            let start = text.find("<w:p").unwrap();
            let end = start + text[start..].find("</w:p>").unwrap() + 6;
            let selected = operation
                .compose_sources(&[(Some(&emitted), start..end, &[])])
                .unwrap();
            let selected = operation
                .close_source_namespaces(
                    selected,
                    &std::collections::BTreeMap::from([(
                        "w".into(),
                        crate::namespace::W_NS.into(),
                    )]),
                )
                .unwrap();
            assert_eq!(
                operation
                    .template_replaceable_texts(&selected)
                    .unwrap()
                    .concat(),
                "A&B"
            );
            operation.reserve_template_text_copy(3).unwrap();
        }
    }

    #[test]
    fn scoped_revision_installer_rejects_ordinary_mutation_and_foreign_or_dead_read_context() {
        let xml = revision_installer_xml();
        let mut operation = super::ScopedWordOperation::new(xml.as_bytes());
        let source = operation.source(0..xml.len(), &Default::default()).unwrap();
        let original = operation.source_paragraph(&source).unwrap();
        let path = original
            .accepted_run_paths()
            .into_iter()
            .find(|p| {
                matches!(
                    original.accepted_run(p).unwrap().content.first(),
                    Some(crate::text::RunContent::Field(_))
                )
            })
            .unwrap();
        let crate::text::RunContent::Field(field) =
            &original.accepted_run(&path).unwrap().content[0]
        else {
            panic!("Field")
        };
        let prepared = operation
            .prepare_template_field_from_read(field, &source, false)
            .unwrap();
        let mut changed = original.clone();
        let run = changed.accepted_run(&path).unwrap().clone();
        assert!(changed.replace_accepted_run(&path, run).unwrap());
        let before = changed.clone();
        assert!(
            operation
                .install_template_prepared_fields(
                    &mut changed,
                    &path,
                    vec![(0, prepared.clone())],
                    None
                )
                .is_err()
        );
        assert_eq!(changed, before);
        let mut foreign = super::ScopedWordOperation::new(xml.as_bytes());
        let mut current = original.clone();
        assert!(
            foreign
                .install_template_prepared_fields(
                    &mut current,
                    &path,
                    vec![(0, prepared.clone())],
                    None
                )
                .is_err()
        );
        drop(source);
        drop(operation);
        assert!(
            foreign
                .install_template_prepared_fields(&mut current, &path, vec![(0, prepared)], None)
                .is_err()
        );
        assert_eq!(current, original);
    }

    #[test]
    fn scoped_revision_installer_validates_all_same_run_slots_before_mutation() {
        let mut frozen = crate::text::CT_P::new();
        let mut run = crate::text::CT_R::new("A&B");
        run.content
            .push(crate::text::RunContent::Field(crate::text::Field::new(
                "FIRST", "one",
            )));
        run.content
            .push(crate::text::RunContent::Field(crate::text::Field::new(
                "SECOND", "two",
            )));
        frozen.runs.push(run);
        let mut operation = super::ScopedWordOperation::with_template_word_inputs(
            vec![],
            vec![&frozen],
            vec![],
            vec![],
            vec![],
            vec![],
            &serde_json::Value::Null,
        )
        .unwrap();
        let mut current = frozen.clone();
        let path = current.accepted_run_paths().remove(0);
        let fields = (1..=2)
            .map(|slot| {
                let crate::text::RunContent::Field(field) = &current.runs[0].content[slot] else {
                    panic!("Field")
                };
                let crate::text::RunContent::Field(input) = &frozen.runs[0].content[slot] else {
                    panic!("Field")
                };
                (
                    slot,
                    operation
                        .prepare_template_field(field, input, false)
                        .unwrap(),
                )
            })
            .collect::<Vec<_>>();
        let before = current.clone();
        assert!(
            operation
                .install_template_prepared_fields(
                    &mut current,
                    &path,
                    vec![fields[0].clone(), fields[0].clone()],
                    Some(&frozen)
                )
                .is_err()
        );
        assert_eq!(current, before);
        assert!(
            operation
                .install_template_prepared_fields(&mut current, &path, fields, Some(&frozen))
                .unwrap()
        );
        assert_eq!(current.runs[0].content.len(), 3);
        assert!(
            matches!(&current.runs[0].content[0], crate::text::RunContent::Text(text) if text.text == "A&B")
        );
    }
